window.__D("text/maamarei-admur-hazaken/c002",{"p":[[2100490224,"קרובים יותר לאור הא\"ס יהי' נמשך בהן האור והשפע מן המאציל יותר בגילוי כו', ולבחי' חג\"ת שהן מדו' שנולדי' מחב\"ד כידוע והן רחוקים יותר לא יהא בהן גילוי אור כ\"כ מפני שאין בהם בחי' הביטול כ\"כ אבל מ\"מ יש בהן בחי' הביטול קצת מפני היותם בבחי' התפעלו' אוי\"ר אלקיי' כו' ועד\"ז יורד עוד האור ונמשך גם בנו\"ה ענפיהן הגם שהן רק בחי' התולדה של חב\"ד וחג\"ת, ועכ\"פ דרך כלל עיקר הענין הוא שאין אור המאציל מאיר רק בי\"ס דקדושה דהיינו במה שיש בחי' ביטול או התפעלו' לגבי אא\"ס והוא הנק' סט' דקדושה כידוע אבל לא תלך אור השפע מאיתו לרחוקי' מאור המאציל כלל רק הם יקבלו מבחי' תמצית ופסולת הנשאר מסט' דקדושה האלקי' והוא הנק'<sup data-n=\"924\">24</sup> בחי' אחוריי' ומשם יהיו יונקי' החיצוני' הנק' אלקי' אחרים כו' עד שגם בסוף כל המדרגו' כמו במל' דעשי' ג\"כ אין החיצוני' מקבלי' רק מבחי' אחוריי' דהיינו מבחי' אחורי העור דנוק' וע\"ז נאמר וש\"ק<sup data-n=\"925\">25</sup> אשים כסותם כידוע, ועד\"מ בעור האדם יש ג' עורות כו', וגם למעלה הם ג' מיני צרופי אותיות דמחדו\"מ והחיצוני' אינם מקבלי' רק ממה שבוקע האור ועובר בין צירוף לצירוף בלבד כמ\"ש במ\"א, וזהו מאחורי<sup data-n=\"926\">26</sup> העור וכמ\"ש ויעש<sup data-n=\"927\">27</sup> ה' לאדם ואשתו כתנות עור כו' וכמ\"ש במ\"א וד\"ל. וכל זה ההבדל נעשה רק מסיבת הצמצום שהי' בראשונה ואם לא הצמצום היו הכל מקבלי' בהשווא' א' כנ\"ל וד\"ל.\n<b>וזהו</b> ואלה<sup data-n=\"928\">28</sup> המלכי' אשר מלכו בארץ אדום כו' פי' כשהי' אור החסד עליון של המאציל יוצא בתחלה בלא צמצום כנ\"ל הרי היו הכל שוין לפניו משום כחשכה כאורה ע\"כ גם בארץ אדום שהן ז' היכלו' החיצוני' שרש דז' אומות כידוע הי' בחי' מלכי' מפני שהיו מקבלים ג\"כ משם ב\"ן של המאציל וכמ\"ש וימלוך באדום כו', אך כל זה לפני מלוך מלך לבנ\"י דהיינו קודם שנעשה בחי' ההבדלה הנ\"ל שילך אור השפע רק לבחי' הפנימי', אבל לאחר שנעשה ע\"י שמלך מלך לבנ\"י ההבדלה שיאיר אור ה' רק בבחי' פנימי' לבנ\"י לבד וכמ\"ש יאר<sup data-n=\"929\">29</sup> ה' פניו אליך דוקא פי' בחי' פניו יהי' אליך דוקא כו' אזי נאמר מלך אין באדום לפי שכבר הובדלו יניקו' החיצונים שלא יקבלו מאור המאציל בהשווא' א' אלא יקבלו רק דרך בחי' הקדושה ומשם לא יקבלו רק בבחי' אחוריי' דאחוריי' כנ\"ל ע\"כ נא' אז דוקא מלך אין באדום משא\"כ לפני מלוך מלך לבנ\"י שהיו בהם מלכי' רבים מטעם הנ\"ל וד\"ל.\n<b>והנה</b> כתיב אם<sup data-n=\"930\">30</sup> תגביה כנשר משם אורידך נאום הוי' כו'. וי\"ל לכאורה מה שאמר כנשר דוקא, וגם האיך ביכולת לו להגביה א\"ע כ\"כ מעצמו כו'. אך הנה",[["924","24","<b>הנק' בחי' אחורי'. . הנק' אלקים אחרים</b>: ראה לקוטי תורה להאריז\"ל נח ו, יג."],["925","25","<b>ושק אשים כסותם</b>: ישעי' נ, ג."],["926","26","<b>מאחורי העור</b>: ראה תו\"א וישלח כו, ב. סה\"מ תרל\"ח ע' תצה-ו."],["927","27","<b>ויעש ה' לאדם ואשתו כתנות עור</b>: בראשית ג, כא. וראה תו\"א ה, ב."],["928","28","<b>ואלה המלכים. . וימלוך באדום</b>: וישלח לו, לא-לב."],["929","29","<b>יאר ה' פניו</b>: נשא ו, כה."],["930","30","<b>אם תגביה כנשר</b>: עובדי' א, ד."]]],[2100490225,"מבואר למעלה דמצד עצמו' המאציל היו כולן מקבלי' בהשווא' א', ומה שנעשה שיהי' ענין השפע בבחי' הבדלה בין פנימי' לחיצוני' והיינו שיומשך האור בסט' דקדושה דוקא, זהו ע\"י אתדל\"ת דוקא דהיינו ע\"י העלא' מ\"נ מלמטה רוח<sup data-n=\"931\">31</sup> אייתי רוח כו' שיהא אור השפע מעצמו' המאציל נבדל להיות נמשך ובא לקרובי' ולא לרחוקי' כו'. והנה הראשון להעלא' מ\"נ בזה אחד<sup data-n=\"932\">32</sup> הי' אברהם אע\"ה בעובדות ויחודים עליונים שעשה למטה כידוע ואחריו יצחק בעובדות דחפירות בארות והמובחר<sup data-n=\"933\">33</sup> שבאבות הוא יעקב כידוע שהוא השלים עבודה תמה זאת ע\"י עובדא<sup data-n=\"934\">34</sup> דמקלות אשר פיצל כו' וכידוע שזהו כללו' ענין עקודי'<sup data-n=\"935\">35</sup> נקודים וברודים שעשה בצאן לבן, דהנה בחי' לבן הוא בחי' לובן<sup data-n=\"936\">36</sup> העליון שמעלה מכל ההשתלשלו' דאצי' והיו הכל כלולים בו וזהו וללבן<sup data-n=\"937\">37</sup> שתי בנות רח\"ל ולא\"ה שהכל הי' של לבן בתחלה, וגם הצאן שהן מדרגו' אורות היוצאים ובוקעים כמ\"ש צאנה<sup data-n=\"938\">38</sup> וראנה כו' היו נק'<sup data-n=\"939\">39</sup> צאן לבן ולא של יעקב וכמ\"ש לבן אליו הבנות<sup data-n=\"940\">40</sup> בנותי והצאן צאני כו', וגם בני לבן אמרו מאשר<sup data-n=\"941\">41</sup> לאבינ\"ו הציל את כל הכבוד הזה כו' וכמ\"ש ביאור הדברים במ\"א שיעקב שהוא נק' בעל עולם האצי' כידוע והוא אשר המשיך כל עיקר ענין הגילוי אורות מבחי' ההעלם שבלובן העליון עד שנמשך להיות בתחלה בחי' עקודי' נקודי' ואח\"כ ברודים כמ\"ש בע\"ח וכללות הענין הוא שהמשיך אא\"ס שיאיר ויתגלה הכל בבחי' הקדושה דוקא ולא יאיר ויתגלה חוץ מן הקדושה כ\"א דרך מעבר הקדושה דוקא יאיר האור והשפע גם לחיצונים ואז לא יוכלו לקבל רק מבחי' התמצית והפסולת כנ\"ל, וזה הי' נעשה הכל ע\"י אתדל\"ת דיעקב בעובדות שעשה למטה במס\"נ כו', ועי\"ז נעשה אתדל\"ע למעלה דהיינו שיהא אור המאציל נאצל ונמשך בבחי' הפנימי' לסט' דקדושה דוקא כו'.\n<b>והנה</b> כמו שבקדושה האלקי' יש כאן ב' עניני' להתעוררו' הבדלת השפע א' מלמטה למעלה בבחי' מ\"נ, והב' מלמעלה למטה בבחי' מ\"ד אח\"כ כנ\"ל, כך הנה בסט' דקליפה מאחר שאת זלעו\"ז עשה כו' ג\"כ יש ב' עניני' הללו הנ\"ל, אך שהן בהיפוך ממש מן הקצה לקצה מאחר שהן בחי' מנגד כו' והיינו מ\"ש אם תגביה כנשר כו'. והענין בכלל הוא ששרש תשוקת סט' דקליפה הוא שיקבלו יניקתם מלמעלה מעלה דהיינו מבחי' עצמו' המאציל כמו שהי' האור והשפע הולכת מאתו בהשווא' א' לכולם ולא שיקבלו יניקתם דרך מעבר הקדושה בלבד כנ\"ל כי מן",[["931","31","<b>רוח אייתי רוח</b>: זח\"ב קסב, ב."],["932","32","<b>אחד הי' אברהם</b>: יחזקאל לג, כד."],["933","33","<b>והמובחר שבאבות</b>: ראה עץ חיים שער (לח) לאה ורחל פ\"ב. לקוטי תורה להאריז\"ל תולדות כז, כה. לקו\"ש ח\"ג ע' 832 הערה 11."],["934","34","<b>עובדא דמקלות</b>: ויצא ל, לז ואילך."],["935","35","<b>עקודים נקודים וברודים</b>: ראה ג\"כ תו\"א נח יא, א."],["936","36","<b>לבן. . לובן העליון</b>: ראה עץ חיים שער (ו) העקודים פ\"א. שער (לח) לאה ורחל פ\"ג. וראה גם בראשית רבה פ\"ע, י."],["937","37","<b>וללבן שתי בנות</b>: ויצא כט, כז."],["938","38","<b>צאינה וראינה</b>: שה\"ש ג, יא. תו\"ח וישלח קפ, ד. קפב, א."],["939","39","<b>נק' צאן לבן</b>: ראה ג\"כ תו\"א ויצא כג, ג."],["940","40","<b>הבנות בנותי</b>: ויצא לא, מג."],["941","41","<b>מאשר לאבינו הציל</b>: ראה ויצא לא, טז."]]],[2100490226,"הקדושה לא יוכלו לקבל רק בחי' אחוריי' וחיצוני' השפע כנ\"ל בענין קבלתם מאחורי עור דנוק' וכיוצא, ואמנם לאחר שכבר הובדל אור השפע מן המאציל להיות נמשך במה שהוא בבחי' ביטול לאור המאציל כנ\"ל אז מן ההכרח שיקבלו רק מבחי' אחוריי' דקדושה, ולכך זאת היא התשוקה של סט' דקליפ' שיעלו למעלה לקבל ממקור האמיתי שהוא מקור לכולם בהשווא' שמצדו הכל הן שוין כנ\"ל ולא יהי' האור הולך ושופע רק במה שהוא בחי' ביטול דוקא כי הרי באמת אין בחי' הביטול תופס מקום כלל כמ\"ש אם<sup data-n=\"942\">42</sup> צדקת מה תתן לו כו' משום דקמי' כחשיכה כאורה ממש כו' ואז ישתוו גם הם בקבלת השפע כמו סט' דקדושה וזהו שרוצים להתדמות כקוף<sup data-n=\"943\">43</sup> בפני אדם כו' והיינו מה שאמר אם תגביה כנשר כו' דקאי על שר של אדום. ומה שאמר כנשר דוקא, דהנה כתי' דרך<sup data-n=\"944\">44</sup> הנשר בשמים כו', והענין הוא למעלה בשמים העליונים שהוא בחי' עצמו' המאציל המקיף לכל צד בהשוואה א' כנ\"ל שנק' סוכ\"ע כו' (ושם הוא דרך הנשר כו' להיות ביכולתו להגביה א\"ע כ\"כ לקבל מן בחי' עיגול היותר בגובה בשמים העליוני' כו' והוא בחי' הדרך היותר גבוה מדרך גב\"ר בעלמה שהוא מ\"ה וב\"ן ע\"י יחודן כו' ומטעם הנ\"ל דמצד עוצם הרוממו' הכל שוין משא\"כ ע\"י יחודי' בהכרח שיהי' צמצום בתחלה כנ\"ל וד\"ל), ויש כאן ג\"כ ב' עניני' ע\"ד הנ\"ל בקדושה הא' ענין אתדל\"ת והוא בחי' החוצפא וההתנשאות שיש בקליפה ונק' גסו' הרוח כידוע, והב' למעלה מה שמגביהי' א\"ע לקבל מאא\"ס בעצמו שלא ע\"י הקדושה ולהיות אתדל\"ע היפך אתדל\"ע שנעשה מן הקדושה כנ\"ל.\n<b>וזהו</b> אם תגביה כנשר משם אורידך נאום הוי', פי' הגם שכבר הגביה א\"ע כנשר לקבל מאור המאציל בעצמו משם אורידך למטה לקבל רק מבחי' התמצית והפסולת הנשאר מן הקדושה כנ\"ל, ובמה בנאום הוי', פי' במה שיהי' נמשך שם הוי' דקדושה להיות נבדל השפע בזה שיהא רק לבחי' הפנימי' והוא ע\"י שם הוי' שיש בכל התגלות עולם בסט' דקדושה כמו שם הוי' שבעולם העקודי', ואח\"כ שם הוי' דעולם הנקודי' ואח\"כ שם הוי' דברודי' כו', וזהו נאם הוי' ששם הוי' הוא מתגלה כי נא\"ם הוא בחי' דיבור כמו נומת\"י לו כו' וד\"ל.\n<b>ובכ\"ז</b> יובן מאמר הזוהר<sup data-n=\"945\">45</sup> ע\"פ קולה כנחש ילך כו', מה נחש רישא שכיבת לעפרא וזנבא סליק לעילא כו' ע\"ש. והנה ידוע דגלו לאדום שכינה עמהם הענין הוא דאור השכינה הוא בחי' מקור החיות והשפע לאותו השר כו', והוא ענין גלות השכינה, דענין גלות הוא ליתן שפע לשונא וכיוצא. ומה שאמר דרישא שכיבת לעפרא כמו דמיון הנחש כו', מרמז בזה ענין עמוק והוא ענין הנ\"ל, דבהיות שע\"י אתדל\"ת בעובדו' דיעקב ואח\"כ במ\"ת ומצות מעשיות הי' הכל למעלה השפע רק",[["942","42","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["943","43","<b>כקוף בפני אדם</b>: ראה זהר תרומה קמח, א. וראה הלשון ג\"כ תו\"א מג\"א צג, ד. תו\"ח נח עה, ב. חיי שרה קכז, ד. ויגש רלו, א. יתרו [הוצאת קה\"ת — תשס\"ג] ער, א. שמות שצד, ב."],["944","44","<b>דרך הנשר בשמים</b>: משלי ל, יט."],["945","45","<b>מאמר הזוהר ע\"פ קולה כנחש ילך. . מה נחש רישא שכיבת לעפרא</b>: ירמי' מו, כב. וראה זהר במדבר קיט, ב. ע\"ח (שער מיעוט הירח) של\"ו, פ\"ב."]]],[2100490227,"בבחי' הבדלה לגמרי, ואמנם בגלותא נהפוך הוא דהקליפה מגבהת עצמה ומקבלת מלמעלה מעלה כמו שהי' קודם בחי' התיקון דיעקב עד שגם הוא מקבל מאור המאציל בעצמו כנ\"ל, וזהו כמו דזנבא דנחש סליק לעילא כו', כך נחה\"ק מקבל מלעילא לעילא כו', וגם כנ\"י בגלות משתווה עמה בזה, וזהו קול\"ה כנח\"ש ילך דרישא שכיבת לעפרא כו', והוא מפני שאין מי שיעורר אתדל\"ת הרי מצד עצמו' המאציל הכל שוין, וע\"כ רישא בחי' הפנימי' שכיבת לעפרא להחיות הע\"ש וזנבא סליק לעילא לקבל מבלתי יש הפרש כלל בין קטן וגדול וראוי ושאינו ראוי שניהם שוין משום דקמי' כחשיכה<sup data-n=\"946\">46</sup> כאורה כו' וד\"ל. משא\"כ שלא בזמן הגלות נא' ואת<sup data-n=\"947\">47</sup> עשו שנאתי מפני שנמשך שנאה לאוה\"ע כמו בשעת מ\"ת שירדה<sup data-n=\"948\">48</sup> שנאה לאוה\"ע ולכאורה למה גם עכשיו לא ישנאם כי אין השנאה חולפת ועוברת מכמו שהיתה מבלתי יהיה סיבה להעברתה כו', אך הענין הוא דמה שאמר ואת עשו שנאתי זה הי' ע\"י עובדו' ומע\"ט דתומ\"צ שממשיכים אא\"ס לקרב הקרובים ולרחק הרחוקים כנ\"ל, אבל כשאין אתדל\"ת למטה כלל הרי מצד עצמו כחשיכה כאורה ואין כולם תופסים מקום כלל עד שיתכן לומר ענין שנאה לעוברי רצונו וכו' כי אם צדקת וכו' וכנ\"ל, והיינו שארז\"ל הן<sup data-n=\"949\">49</sup> הן גבורותיו גוים מרקדין בהיכלו והוא שותק כו' וכמשל השממית הנ\"ל וד\"ל.\n<b>וזהו</b> ויאבק איש עמו, פי' ויאבק הוא ע\"ד ענין מלחמה גשמיו' כמו שב' בנ\"א נלחמים יחד שמתאבקים יחד שכל א' מחבק ידיו על אחורי כתיפו של חבירו כידוע, וגם כאן הנה הי' ענין מלחמה גשמי' ג\"כ, וזהו המלחמה היתה למטה בשר של עשו שלמטה עם יעקב שלמטה, אך הנה שרש של זאת המלחמה היתה למעלה וענין אותה המלחמה שלמעלה הוא כמבואר למעלה, דשרש שר של עשו שלמעלה הוא בחי' סט' דקליפה כנ\"ל בכלל, והוא בחי' ז\"א דקליפה שנגד אצי' כו' שנק' איש<sup data-n=\"950\">50</sup> בליעל כידוע ועיקר כוונתו במלחמה הוא להעלות ולהגביה א\"ע כנשר לקבל גם הוא מאור המאציל בעצמו שלא ע\"י סט' דקדושה. והנה יעקב הוא בעל עולם האצי' להמשיך אור המאציל בבחי' הקדושה דוקא כנ\"ל במ\"ש בני לבן מכל אשר לאבינו הציל כו'. ע\"כ עיקר המלחמה של איש זה דסט' דקליפ' הי' רק לנגד יעקב דקדושה להשפילו למטה בהאבקו עמו כמשי\"ת בעזר\"ה ובזה לא יצטרך עוד לקבל למעלה ההארה והשפע ע\"י הקדושה אלא יקבל בהשווא' א' עם הקדוש' כנ\"ל, וזאת היתה ענין המלחמה למעלה והוא בבחי' דכ\"ר דקליפה, והיינו ענין מדרגה השני' הנ\"ל בענין מ\"ן ומ\"ד כמו שיש בקדוש' כך יש בס\"א כו' וזהו שאמר ויאבק אי\"ש אי\"ש דוקא וד\"ל.\n<b>והנה</b> עתה י\"ל מה שנאבק עם יעקב להשפילו שזאת הוא ענין מלחמה שלמטה כנ\"ל, למה דוקא עם יעקב ואיך יהיה ביכולתו להשפילו כו'. הנה יעקב<sup data-n=\"951\">51</sup> הוא יו\"ד",[["946","46","<b>כחשכה כאורה</b>: תהלים קלט, יב."],["947","47","<b>ואת עשו שנאתי</b>: מלאכי א, ג."],["948","48","<b>שירדה שנאה לאוה\"ע</b>: ראה שבת פט, סע\"א."],["949","49","<b>הן הן גבורותיו. . שותק</b>: ראה יומא סט, ב. יל\"ש נחמי' רמז תתרעא."],["950","50","<b>איש בליעל</b>: ראה ג\"כ פירוש המילות פו, ד."],["951","51","<b>יעקב הוא יו\"ד עקב</b>: ע\"ח (שער סדר אצי') ש\"ג, פ\"ב. פרדס ערך יעקב. קהלת יעקב ערך ישראל."]]],[2100490228,"עק\"ב ובחי' יו\"ד שבו היינו בחי' הארת יסוד אבא שבוקע יסוד אימ' ויורד עד סיום חג\"ת דז\"א ולכך נק' יעקב כמ\"ש בע\"ח, וידוע דבחי' החכמה<sup data-n=\"952\">52</sup> היא בחי' אין והבינה נק' יש לפי שבחי' החכמה הוא ענין נקודת ההשכלה שאינה נתפסת עדיין בגדר השגה והבנה משא\"כ הבינה היא בכלל השגה והבנה ומן ההשגה וההבנה דוקא הוא שנולדו בחי' התפעלות המדות הנק' חג\"ת כידוע, וידוע ג\"כ שכל המקיפים מבינה פי' שיש ב' מיני התפעלות אוי\"ר, הא' מאותה ההשג' וההתבוננות שמתצמצמת מאד להוליד התפעלות המדות דמאחר שכבר מצומצמת בכלי ההשגה כבר מתיישבת היא גם בכלי המדות דהיינו שהמדות ביכולתם להכילה, וגם המדות בלב הלב מכיל אותם מטעם זה כידוע, אבל יש בחי' השגה שאינה מתצמצמת במוח ולב כלל לפי שאין כלי המוח והלב ביכולת להכילה ואזי היא באה בבחי' הביטול במציאות זהו ההארה שבאה מבחי' אור החכמה דוקא, כי בחי' החכמה הוא למעלה לגמרי מבחי' השגה והבנה ולכך נק' אי\"ן, וידוע שבחי' או\"פ שבעליון נעשה או\"מ בתחתון ע\"כ בבינה נעשה מאותה הארת או\"פ דאבא בחי' או\"מ למוחין שבמדות והוא בחי' המקיפים שמבינה שמאירים על התפעלות המדות והיינו בחי' אור ההשגה הבלתי מתיישב בכלי המוח והלב וההתפעלות ממנו הוא בחי' הביטול במציאות לבד כי למעלה הוא מבחי' התפעלות מורגשת כו' מטעם זה וד\"ל. והנה אחיזת יניקת החיצוני' אינה אלא מבחי' חג\"ת שנולדו כבר בגילוי אור מנה\"י דאימא כו' כידוע, אבל בבחי' חב\"ד בכלל אין להם אחיזה ויניקה עדיין וכמ\"ש ימותו<sup data-n=\"953\">53</sup> ולא בחכמה שאין בחכמה בחי' מיתה שהיא הנפילה כידוע. והטעם לזה לפי שהמדות נפלו בבחי' שבה\"כ ונעשה ונסתעף מזה עד שיהי' מציאות ז' מדות דקליפות גם לנגד בחי' ז\"א דאצי' והוא בחי' היש המורגש שם ובעולם הבריאה נק' ז'<sup data-n=\"954\">54</sup> מדות רעות והן ז' פרות הרעות כידוע, ולמטה באדם התחתון ג\"כ אנו רואים שיש מדות רעות לעומת מדות דקדושה כי הרי כשאדם מתפלל בכונה באוי\"ר בכל לבו הנה מיד אחר התפלה חולפת ועוברת ההתפעלות לגמרי מכל וכל עד שיוכל לימשך אחר תענוגי עוה\"ז הגשמיי' כשרואה אותם והרי בחי' כחות המדות שבלבו היו לקדושה האלקית בשעת התפלה הוא שנמשך בהם אחר תענוגי עוה\"ז והיינו לפי שאת<sup data-n=\"955\">55</sup> זה לעומת זה עשה כו', ויש מדות דקליפה שיונקים ממדות דקדושה וגם שנתפעל באהבה לה' מ\"מ יוכל להתפעל באהבה זרה ג\"כ אח\"כ כו', ואמנם כל זה במדות בלבד לפי שבמדות עליונות דקדושה האלקית ג\"כ מדות רעות דקליפה דאבי\"ע מלבישים אותם מטעם סיבת השבירה כנ\"ל אבל בבחי' חב\"ד שלמעלה מהולדת המדות לא הי' ענין שבירה כלל וכלל ואין שם נפילה לדבר רע כלל, והרי אנו רואים גם באדם התחתון שכאשר הוא בא לאותה ההשגה שאין ביכולתו להכילה וגם בלבבו לא יכילנה כו' אזי תשאר אותה ההארה מן אותה ההתפעלות גם כל היום ולא תעבור מכל וכל לעולם כי נגע הדבר אצלו בבחי' עצמיות הנפש וכמ\"ש כל עצמותי תאמרנה כו' עד שאינה נשכחת כלל והיא אשר",[["952","52","<b>החכמה. . אין והבינה. . יש</b>: נסמן לעיל ע' עב."],["953","53","<b>ימותו ולא בחכמה</b>: איוב ד, כא."],["954","54","<b>ז' מדות. . ז' פרות</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תת, ב. תקס\"ט ע' רמג. וראה ג\"כ תו\"ח מקץ רטו, ג. ובהערה 33 שם בהמ\"מ."],["955","55","<b>שאת זה לעומת זה עשה</b>: קהלת ז, יד."]]],[2100490229,"נשמרת לגמרי מיניקת החיצונים מפני שגם מים רבים לא יכבוה, והטעם לפי שאור המקיף דוחה החיצונים כידוע מפני שאין להם יניקה להתקרב שם כלל וכלל, וזהו רגלי<sup data-n=\"956\">56</sup> חסידיו ישמור מפני בחי' או\"מ דבינה שעל המדות כנ\"ל, ומבואר למעלה דהמקיף הזה נעשה מבחי' הארת אור אבא כו' שהוא האור אשר איננו נגבל בבחי' כלי כלל ולכך נק' כ\"ח מ\"ה כו', וע\"כ הוא תמיד בקיום נצחי ולא יופסק אורו גם בהיות האדם טרוד בכל עניני עוה\"ז כי רחוק הוא שיודבק בו דביקות זר מטעם שאינו בבחי' שכחה כלל וכמ\"ש בפ' קדש ולזכרון<sup data-n=\"957\">57</sup> בין עיניך לפי שפ'<sup data-n=\"958\">58</sup> קדש הוא בבחי' אור החכמה והזכרון הוא במוח אבא דוקא כידוע בע\"ח בענין ג'<sup data-n=\"959\">59</sup> חללי גלגלתא כו', פי' המוח שבו כח הזכרון שורה והזכרון הוא ענין אור נצחי שאין בחי' הזמן מכלה כחו להיות שוכח מחמתו כו' הוא מוח החכמה ולהיותו למעלה מבחי' כלי וגבול ע\"כ גם בחי' הזמן לא יגביל כחו כו' וכמ\"ש במ\"א. משא\"כ המדות להיותם מסתעפים רק מבחי' או\"פ שנמשך מבינה הנגבל דוקא בכלי כנ\"ל ע\"כ יש בהם דוקא בחי' השכחה שהרי מיד אחר התפלה יכול לשכוח לגמרי ונסתלק ההארה שלהם עד שיכול לידבק בדביקות זרות כנ\"ל, וזהו שנאמר במלחמת עמלק לא<sup data-n=\"960\">60</sup> תשכח להורות על בחי' אור אבא שמלובש עד למטה מטה גם בסיום חג\"ת כנ\"ל, לפי שבוקע או\"פ דאימא שמסתיים בחזה דז\"א כו' מפני שאור אבא ארוך משל אימא ע\"כ יורד ונמשך עד למטה מטה והוא גם בסיום בחי' יסוד דז\"א כו' כמ\"ש בע\"ח ולכך נא' לא תשכח וד\"ל.\n<b>וזהו</b> שנאבק שר של עשו למטה ששרשו ז' מדות דקליפה עם יעקב דוקא, להיות כי יעקב<sup data-n=\"961\">61</sup> הוא מובחר שבאבות והאבות<sup data-n=\"962\">62</sup> הן המרכבה שהוא בחי' חג\"ת<sup data-n=\"963\">63</sup> דז\"א ויעקב<sup data-n=\"964\">64</sup> בחי' ת\"ת הכולל הכל, ומפני שלנגד המדות דקדושה יש לעומתם ממש מדות דקליפה להלבישם כנ\"ל ע\"כ נאבק עמו כדרך המתאבקי' יחד שכל א' מחבק ידיו על אחורי כתפיו של חבירו, כך השר של עשו הלביש לאחורי המדות דיעקב שהן בחי' הכתפיי' בידי עשו שהן חג\"ת דקליפ' לדבק במדות דיעקב, ואמנם החיבוק הזה לא הי' ענין קירוב ודביקות מצד עצמו אלא בשביל ענין ניצוח מלחמה, והענין הוא שהי' חפץ להשפילו ליעקב דהיינו שיהיו המדות דיעקב נמשכים ויורדים אחרי בחי' המדות דקליפה ולהיות בהיפוך שהמדות דקדושה יקבלו ע\"י סט\"א כענין גלות",[["956","56","<b>רגלי חסידיו ישמור</b>: שמואל-א ב, ט."],["957","57","<b>ולזכרון בין עיניך</b>: בא יג, ט."],["958","58","<b>שפ' קדש. . אור החכמה</b>: בא יג, ב. תו\"א תשא פו, ג. ויקהל פז, ב. מג\"א צב, ד. תו\"ח וארא [הוצאת קה\"ת — תשס\"ג] נו, ג."],["959","59","<b>ג' חללי גלגלתא</b>: באוה\"ת שמות כרך ז ע' ב'תצא מציין: ועיין מזה בזח\"ג נשא דק\"מ ע\"א. ואתחנן דרס\"ב ע\"א ובת\"א פ' תצוה בביאור ועשית ציץ וכן הוא בספרי הניתוח בשבילי אמונה נתיב רביעי שביל הראשון ובספר הברית מאמר י\"ז פ\"ד. וצ\"ע בכוזרי מאמר ה' סי' י\"ב בפי' האוצר נחמד שם [ד\"ה והכח הזוכר] ודע שהקדמונים."],["960","60","<b>לא תשכח</b>: תצא כה, יט."],["961","61","<b>יעקב הוא מובחר שבאבות</b>: ראה ע\"ח שער (לח) לאה ורחל פ\"ב. לקו\"ת להאריז\"ל תולדות כז, כה. לקו\"ש ח\"ג ע' 832. וש\"נ."],["962","62","<b>והאבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב ו."],["963","63","<b>והאבות. . חג\"ת</b>: ראה זהר בראשית מז, ב. וראה פרדס שער (כב) הכינויים פ\"ד."],["964","64","<b>ויעקב בחי' ת\"ת</b>: ראה זהר (סתרי תורה) ויצא קנז, ב. שם ח\"ג (תוספות) שב, א."]]],[2100490230,"השכינה הנ\"ל דרישא שכיבת לעפרא וזנבא סליק כו' והוא שהקליפה תגביה א\"ע כנשר לקבל למעלה כו', וזהו כללות ענין המלחמה שהיתה למטה להשפיל למדות דיעקב בתחלה ואזי ממילא יגביה א\"ע כנשר אח\"כ למעלה וזהו ויאבק איש עמו וד\"ל.\n<b>אך</b> לא יכול ליעקב לנצחו ולהשפילו מטעם שיעקב הוא יו\"ד עק\"ב הוא בחי' הארת יסוד אבא שבוקע יסוד אימא כנ\"ל ויורד עד למטה גם בסיום חג\"ת כנ\"ל וכל מקום שאור אבא מגיע אין שם אחיזה ויניקה כלל לחיצוני' להיותו בבחי' הביטול בבחי' עצמיו' כו' וכנ\"ל והיינו הטעם שאנו מוצאים ז' היכלות דנוגה לנגד ז' היכלות דקדושה, אבל לנגד היכל ק\"ק להיותו בבחי' כחב\"ד כידוע אין לנגדו שום שרש למציאת שכל בקליפ' וד\"ל. וכל זה מפני שבמדות זלע\"ז עשה כו' אבל בחב\"ד אין זלע\"ז כלל וכמ\"ש ימותו ולא בחכמה כנ\"ל. וזהו וירא כי לא יכול לו ומ\"מ ויגע בכף יריכו כו', פי' בכף יריכו הן בחי' נה\"י דיעקב וידוע דבחי' נה\"י הן רק בחי' התולדה של המדות הנק' חג\"ת, והענין הוא בעבודת ה' שלאחר שנתפעל האדם באוי\"ר בתפלה הגם שחולפת ועוברת מעיקר הארת ההתפעלות מ\"מ בחי' רשימו מן אותה ההארה נשארה עדיין והוא הנק' מוחין דקטנו' או מוחין דיניקה והיינו מה שיולד מהן התולדה של המדות הנק' נו\"ה דהיינו בחי' ההשפעה דלבר מגופא והוא לעשות מצוה כמו צדקה מפני שנשאר בו רשימו מן המוחין דמדות לאהוב ה' באהבה ולעשות מצותיו כו' הגם שבשעה זו אינו בבחי' אותה הארת ההתפעלות באהבה מ\"מ הוא מנצח א\"ע מסיבת אותו אור בחי' הרשימו דמוחין שנשארו כו', ולכך נק' בשם ענפי המדות כענף היוצא מן הבד כו' וכמ\"ש במ\"א וד\"ל. שהן בחי' הכלים שמבשלים הזרע בכליות (ושם הוא שנעשו' טפות זרע גשמיות ולא קודם שבא השפע לכליות מטעם שהכליות הן בחי' הכלי' לזה ומהם יורד עוד לבחי' הירכיי' שהן חיצוני' הכלים דנו\"ה כו' וכמ\"ש במ\"א וד\"ל) ונקראים בחי' כלי ההשפעה מפני שהמה משפיעים מעילה לעילה שחוץ מגופא כו' וד\"ל. ולהיות שהארת המוחין מצומצם מאד בנה\"ב ע\"כ יוכל להיות בחי' הנפילה במדות רעות וכמארז\"ל צרכי<sup data-n=\"965\">65</sup> עמך מרובים ודעתם קצרה, פי' מפני שדעתם קצרה בקטנות המוחין כנ\"ל ע\"כ צרכיהם מרובים לתאוה יבקש נפרד ברבוי עושר וכבוד ולכך הצטרכותם מרובה וד\"ל.\n<b>ולהיות</b> שבבחי' הירכיי' דיעקב שהן רק בחי' חיצוני' הכלים דנה\"י כו' אין בהם רק בחי' רשימו בעלמא מהארת המוחין שבמדות (הגם שנבנה מזה פרצוף שלם דנוק' כו') ע\"כ יכול שר של עשו ליגע בכף יריכו והיינו שיכול להיות בהם יניקות החיצונים ג\"כ כנ\"ל מפני ששם תכלית מיעוט האור והארת אור אבא כבר נסתיים שם ואינו מאיר כ\"כ כמו בחג\"ת, וזהו ויגע בכף ירך יעקב בהאבקו עמו, פי' בהאבקו עמו בחג\"ת שלו לא יכול לו כי טעה השר ולא הכיר בהארת אור אבא שבחג\"ת וסבור הי' שיעקב אינו אלא בחי' מרכב' לחג\"ת ושם גם לו יש שרש מציאות כי את זלע\"ז כו', אבל באמת אור אבא שביו\"ד דיעקב שהוא מוח הזכרון ע\"ז נא' לא תשכח ולא יש",[["965","65","<b>צרכי עמך מרובים</b>: ראה ברכות כט, ב."]]],[2100490231,"לחיצוני' ממנו יניקה כלל אלא בכף ירך יעקב שכבר כלה שם כח בחי' אור אבא ע\"כ נגע בו והוא מ\"ש בפרד\"ס בשער ירך יעקב שפגם בבחי' נצח דז\"א שממנו הנבואה שופע כי שרש כל הנביאים*<sup data-n=\"966\">*65</sup> אינו אלא בבחי' נצח כמו יחזקאל<sup data-n=\"967\">66</sup> בנצח דיצי' וישעי'<sup data-n=\"968\">*66</sup> בנצח דבריאה כו' משום דמבואר למעלה שבחי' נו\"ה שהן לבר מגופא הענין שהמה דוקא המשפיעים לעילה שחוץ ולבר מגופא אבל בגופא עצמו עדיין אין ענין השפעה לחוץ אלא כלולה השפע בעצמותו כו' וכן בנבואה להיותה בחי' גילוי אור אלקי' על הנשמות דלבר מגופא דמלכא כו' א\"א שיקבלו ההארה האלקי' רק מבחי' נו\"ה שבכל עולם ובדרך כלל העיקר והמקור של הנבואה הכללי' שופע רק מבחי' נצח דז\"א דאצי' והוא בחי' כף ירך יעקב בכלל כידוע וע\"ז אמר ויגע בכף יריכו כו'.\n<b>ובכ\"ז</b> מתורץ הקושיא הנ\"ל איך יתכן ענין מלחמה בסט' דקליפה נגד הקדושה אחרי אשר אין להם מציאות חיות ושפע רק מן הקדושה כו', דהלא מבואר מכל הנ\"ל דאע\"פ שזה אמת שאין להם יניקה רק מבחי' אחוריי' דקדושה, זהו דוקא לאחר שנעשה זה ע\"פ אתדל\"ת מיעקב בעל עולם האצי' וכיוצא, אבל מראשית ההשתלשלות שהי' חפץ חסד כמ\"ש כי<sup data-n=\"969\">67</sup> אמרתי עולם חסד יבנה כו' היו הכל מקבלים בהשווא' אחת כי מפני עוצם רוממות אור חסדו של המאציל אין תופסים מקום כנ\"ל, ולזה הדרך הי' חפץ סט' דקליפה כדי שיקבל גם הוא בהשוואה א' כו', וא\"כ לא יקבל עוד ע\"י הקדושה ויכול להיות שיהי' להם מציאות שפע וחיות מלמעלה שלא ע\"י הקדושה, אך וירא כי לא יכול לו כנ\"ל הטעם לא נגע רק בכף יריכו ופגם אורו וגם זה הפגם נתתקן ע\"י שמואל הנביא וכמ\"ש שמואל וגם<sup data-n=\"970\">68</sup> נצח ישראל כו' וכנ\"ל וד\"ל.\n<b>וזהו</b> שארז\"ל במס' חולין<sup data-n=\"971\">69</sup> ויאב\"ק איש עמו, אריב\"ל מלמד שהעלו אבק ברגליהם עד כסה\"כ כו'. דהנה ענין שנים המתאבקים יחד הנה כמו שהאחד מחבק לחבירו כנ\"ל, כך השני מחבק אותו, וא\"כ בשעה ששר של עשו חבק את יעקב בידיו אחורי כתפיו הרי גם יעקב חבק לשר של עשו בידיו אחורי כתפיו, והענין הוא דמאחר שהיתה ענין מלחמה וכתי' וירא כי לא יכול לו כו', והיינו מפני שאור אבא שמלובש בחג\"ת כנ\"ל, ולא עוד שלא יכול לו אלא בהכרח שיעקב נצחו כי מאחר שהיתה ענין מלחמה בהכרח שינצח א' מהם. והנה מבואר למעלה דמדות דיעקב לא נשפלו למטה מפני הלבשת מדות דקליפה אע\"פ שגברו בכח להשפילם כו' והיינו שלא יצא מהם אהבה רעה כלל וכלל, וכשנאמר עוד שיעקב נצח למדות דקליפה הענין הוא כך דמלבד שלא הושפלו למטה בחיצוני' אלא עוד זאת שכאשר עלה בחי' הכחות הרעות של המדות הרעות להתגבר באדם וכידוע מארז\"ל דיצרו<sup data-n=\"972\">70</sup> של אדם",[["966","*65","<b>כל הנביאים אינו אלא בבחי' נצח</b>: ראה אגה\"ק סי\"ט."],["967","66","<b>יחזקאל בנצח דיצי'</b>: ראה תקו\"ז בהקדמה ד, א. ע\"ח שער (מט) קליפות נוגה פ\"ב."],["968","*66","<b>וישעי' בנצח דבריאה</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. לקוטי הש\"ס להאריז\"ל יבמות מט, ב ד\"ה משנה. סידור שער הק\"ש עט, א."],["969","67","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["970","68","<b>וגם נצח ישראל</b>: שמואל-א טו, כט."],["971","69","<b>במס' חולין</b>: נסמן לעיל בתחלת המאמר."],["972","70","<b>דיצרו של אדם מתגבר עליו</b>: סוכה נב, א."]]],[2100490232,"מתגבר עליו בכל יום כו' כמו ע\"ד דוגמא באיזה ענין הרהור תאוה רעה וכיוצא והמדות דקדושה מתגברים לנגדה ומנצחים אותה עד שחולפת ועוברת כו' הנה מלבד שחולפת ועוברת התאוה הרעה אלא דמה שנשאר מכחה הרי נתהפך לקדושה ותתן תוס' כח ואומץ למדות דקדושה וכידוע שזהו כל עיקר ענין הבירורים וההעלאות ניצוצי' מקליפה לקדושה וכמ\"ש אם<sup data-n=\"973\">71</sup> רעב שונאך כו' כי גחלי' אתה חותה על ראשו כו' שבהתברר הטוב מהרע יתן תוס' וכח עוז לקדוש' האלקי' וכמ\"ש בזוהר ע\"פ בכל<sup data-n=\"974\">72</sup> לבבך בשני יצריך דא הוא רזא כו', פי' כי מה שניתוסף האור בקדושה ע\"י התבררות הטוב מן הרע דקליפ' כאשר מנצחין אותו הוא ענין יתרון<sup data-n=\"975\">73</sup> האור שבא מן החושך ודא הוא רזא כו' משום דטוב מא\"ד נאמר ביצה\"ר שהוא מאד בלי גבול וכמארז\"ל טוב מאד<sup data-n=\"976\">74</sup> זה מה\"מ וכמ\"ש במ\"א הטעם וד\"ל. וגם כאן כאשר נתגבר יעקב בהאבקו לשר של עשו ונצחו שיומשך כחו אליו הרי בירר ממנו כל כחו שבבחי' הטוב ונתן תוס' כח ועוז ליעקב עד שנעשה בחי' יתרון האור במדות דקדושה וכמו שידוע דבמקום<sup data-n=\"977\">75</sup> שבע\"ת עומדים צ\"ג א\"י לעמוד מזה הטעם וכמ\"ש בזוהר משום דמשכין<sup data-n=\"978\">76</sup> לי' בחילא יתיר וכו' והכל שרש וענין א' משום דברייתו<sup data-n=\"979\">77</sup> של עולם ברישא חשוכא והדר נהורא כו' וד\"ל. וזהו שארז\"ל על מלחמה זו שהעלו אבק כו' לשון שהעלו משמע דשניהם העלו לפי שבאמצעו' שניהם דוקא נעשה יתרון האור ועלי' גדולה היתה מגעת מהם עד כסה\"כ מטעם הנ\"ל וד\"ל.\n<b>אך</b> הנה עדיין י\"ל מה שארז\"ל שהעלו אב\"ק, אבק זה אין ענינו לכאן כלל, כי פי' ויאבק לפרשו בל' אבק מה ענינו כאן. וגם מה שאמרו שהעלו עד כסה\"כ דוקא כו'. אבל כ\"ז יובן בהקדי' לפרש דברי המאמר הנ\"ל בזוהר ע\"פ זה ויאב\"ק איש כו', ר\"ש אמר מה בין אב\"ק לעפר כו', הנה ידוע דיש ד' מדרגו' ד' יסודות ארמ\"ע<sup data-n=\"980\">78</sup> והם נגד דצח\"מ כידוע, והנה העפר הוא בחי' התחתונה שבכולם כידוע, ולכאורה יש להפליא מאד אם העפר הוא בחי' התחתונה למה הארץ תוציא הכל מכל ד' מדרגו' דצח\"ם וכמ\"ש הכל<sup data-n=\"981\">79</sup> הי' מן העפר כו' וכנראה בחוש שהעפר מצמיח מבחי' דומם כאבן וגם מצמיח פירות ותבואות וכל מיני תענוגי מעדני מלכים הכל מן העפר, וגם נפש המשכלת כתי' בו ויצר<sup data-n=\"982\">80</sup> ה' את האדם עפר מן האדמה כו' והלא בחי' יסוד האש ויסוד הרוח ויסוד המים הם גבוהים הרבה במדרג' מיסוד העפר כידוע וכמו שנראה",[["973","71","<b>אם רעב שונאך</b>: משלי כה, כא."],["974","72","<b>בכל לבבך. . דא הוא רזא</b>: ברכות פ\"ט מ\"ב. זח\"ב כו, ב לקו\"ת ואתחנן ז, ד. וש\"נ."],["975","73","<b>יתרון האור שבא מן החושך</b>: ע\"פ קהלת ב, יג."],["976","74","<b>טוב מאד זה מה\"מ</b>: בראשית א, לא. ראה ילקוט שמעוני שם רמז טז, וש\"נ. בראשית רבא פט\"ו, י. וראה תו\"א נח ט, א. יתרו סט, ד. תשא פו, ב. ובכ\"מ."],["977","75","<b>דבמקום שבע\"ת עומדים</b>: ראה ברכות לד, ב. בסה\"מ תש\"ט ע' 183 בהערת כ\"ק אדמו\"ר זי\"ע."],["978","76","<b>דמשכין לי' בחילא יתיר</b>: ראה זהר חיי שרה קכט, ב. אגרת התשובה פ\"ח."],["979","77","<b>דברייתו. . ברישא חשוכא</b>: ראה שבת עז, ב."],["980","78","<b>ד' יסודות ארמ\"ע. . דצח\"מ</b>: בתו\"ח ויגש רלב, א מובא בשם הע\"ח, וכן הוא בהמשך תרע\"ב ח\"א ע' רפב. ראה מאורי אור ד' סכ\"ד."],["981","79","<b>הכל הי' מן העפר</b>: קהלת ג, כ."],["982","80","<b>וייצר ה' את האדם עפר מן האדמה</b>: בראשית ב, ז."]]],[2100490233,"לעין בדקות ורוחניות בתוס' החיות ביותר למה לא יולידו ויצמיחו הם פירות ותבואות וכל הדברים כמו יסוד העפר ואם יסוד המים מצמיח גם הוא הרי אינו מצמיח אלא בסיבת היניקה מעפר הארץ כידוע, וגם הנה ע\"ד הזה בבחי' ארץ העליונה נא' הכל בארץ דוקא שהיא תוליד ותצמיח את הכל וכמ\"ש ויאמר<sup data-n=\"983\">81</sup> אלקי' תוצא הארץ נפש חי' כו' וכיוצא.\n<b>אך</b> הענין יובן בהקדמת ענין אחד והוא בבחי' הכתר עליון דידוע דבחי' הכתר<sup data-n=\"984\">82</sup> הוא בחי' ממוצע בין עצמו' המאציל לנאצלים כי יש בו מבחי' התחתונה שבמאציל וגם יש בו מבחי' הנאצלים וע\"כ הוא בחי' ממוצע ונק' בחי' התחתונה לגבי עצמו' אור הא\"ס ונק' ג\"כ בחי' מקור וראש לכל הנאצלים כידוע, ולהיות כן הרי בהכרח שעל ידו דוקא תעבור אור השפע מאא\"ס לנאצלים מאחר שהוא בחי' ממוצע וא\"כ כל מה שנאצל האור מן המאציל בבחי' יש מאין עד בחי' התהוות נברא למטה יש מאין כידוע הכל הוא ע\"י בחי' הכתר דוקא להיותו בחי' ממוצע והכל ממנו דוקא נמצא והוא מקבל מעצמו' המאציל כו', וא\"כ בהכרח ג\"כ שיהיה בחי' הכתר כולל כל מה שיש בהשתלשלו' בפרט גם בפרטי פרטי' כמ\"ש<sup data-n=\"985\">83</sup> במ\"א ע\"פ ויהיו חיי שרה כו' ע\"ש וד\"ל.\n<b>והנה</b> ידוע דבקדושה כל הספי' הם בבחי' ההתכללו' שכלולים זמ\"ז עד שאמרו בס\"י<sup data-n=\"986\">84</sup> דנעוץ תחב\"ס וסוב\"ת כו', ואמנם הענין הוא דהתחלה נעוץ בסוף דוקא ולא באמצע משום דבסיום גמר ההשפעה שם ניכר ונגלה כח התחלה דוקא ולא באמצעו' ההשפעה, וזה מובן עד\"מ הכאת אור השמש<sup data-n=\"987\">85</sup> בארץ שחמימותו דוקא בארץ למטה כו' ולא באמצע אויר הארץ כידוע וכמ\"ש במ\"א וד\"ל. והנמשל מזה יובן למעלה דמטעם זה דוקא נעוץ תחב\"ס כו' וזהו בחי' ההתכללו' שכלול התחלה בסוף וכו' וד\"ל.\n<b>ולהבין</b> זה בתוס' ביאור הנה כתי' אני<sup data-n=\"988\">86</sup> ראשון ואני אחרון וידוע דתיבת אנ\"י<sup data-n=\"989\">87</sup> הוא תיבת אי\"ן ובחי' הכתר הוא הנק' אי\"ן וכמ\"ש והחכמ'<sup data-n=\"990\">88</sup> מאין תמצא שהוא בחי' הכתר כידוע דהחכ' נמצא מן הכת\"ר ובתיבת אי\"ן אותיות אנ\"י היינו בחי' מל' שנק' אני כידוע, וכתי' אני ראשון ואני אחרון היינו מפני שהכתר הנק' ראשון נעוץ תחב\"ס בבחי' מל' סופא דכל דרגין ונק' אחרון ולהיותו כלול מן בחי' הסוף ע\"כ אמר אני ראשון בבחי' כתר ואני אחרון בבחי' המל' הכל אני הוא משום",[["983","81","<b>ויאמר אלקי' תוצא הארץ נפש חי'</b>: בראשית א, כד."],["984","82","<b>הכתר. . ממוצע</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"א."],["985","83","<b>כמ\"ש במ\"א ע\"פ ויהיו חיי שרה</b>: ראה לעיל ע' סו ואילך. ד\"ה ויהיו חיי שרה (נדפס ג\"כ במאמרי אדה\"ז — פרשיות (חיי שרה) ע' קלא ואילך)."],["986","84","<b>בס\"י דנעוץ תחלתן בסופן</b>: פ\"א מ\"ז."],["987","85","<b>השמש. . שחמימותו דוקא בארץ למטה. . וכמ\"ש במ\"א</b>: ראה ג\"כ לקו\"ת תבא מג, ב."],["988","86","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["989","87","<b>אני. . הכתר. . אין</b>: ראה פרדס שער (ג) אם הא\"ס הוא הכתר. ע\"ח (שער דרושי אבי\"ע) שמ\"ב, ספ\"א. לקו\"ת שלח מז, ד."],["990","88","<b>והחכמה מאין תמצא</b>: איוב כח, יב."]]],[2100490234,"דנתחב\"ס דוקא כנ\"ל הטעם, ומאחר שמבואר למעלה דבחי' הכת\"ר הוא בחי' ממוצע ע\"כ ממנו ועל ידו דוקא נמצא כל פרטי ההשתלשלו' א\"כ כשנעוץ תחב\"ס כנ\"ל בהכרח לומר שגם בבחי' סופא דכ\"ד שהוא בחי' מל' דאצי' יהי' ממדה זו נמצא כל פרטי ההשתלשלו' בבחי' נבראים יש מאין מאחר דאני ראשון ואני אחרון כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן פי' מאמר הזוהר הנ\"ל, במה שאמר ר\"ש מה בין אב\"ק לעפ\"ר כו' עפר דכל איבין נפקין מיני' ואיהו כללא דעילא ותתא ע\"כ, פי' עפר הוא בחי' הדומם ובחי' התחתונה הוא מכל המדרגו' וכנ\"ל, ומ\"מ כל איבין נפקין מיני', שהרי מיסוד העפר דוקא כל מציאות דצח\"ם נמצא וכמ\"ש למעלה ואין ג' יסודות רמ\"א מצמיחים ומולידים כלל, והטעם הוא לפי שנעוץ תחב\"ס דוקא כנ\"ל בפי' אני ראשון ואני אחרון להיות כי בבחי' מל' דוקא מהארת בחי' הכתר, והכתר הוא בחי' ממוצע בין אא\"ס לנאצלים כו' וע\"כ גם מל' דאצי' שנק' עפר העליון והוא בחי' עפר<sup data-n=\"991\">89</sup> אשר בקרקע המשכן כידוע מיני' נפקין כל איבין דעלמא דוקא ואיהו כללא דעילא ותתא פי' שהוא בחי' ממוצע מבחי' אצי' ומבחי' בריאה כמו שבחי' הכתר הוא בחי' ממוצע מבחי' עצמו' המאציל ומבחי' הנאצלים כנ\"ל וד\"ל. אבל אב\"ק דא דאשתאר מן נורא ולא עביד איבין לעלמין, פי' דאשתאר מן נורא דוקא, יובן בהקדים תחלה בענין שבירת הכלים.\n<b>דהנה</b> ידוע בכללות ענין שבה\"כ<sup data-n=\"992\">90</sup> דז' מלכי' שמתו כו' ונסתלקו האורות ונפלו הכלים ונשברו כו', הנה ירדו הכלים ונפלו בעולם הבריאה ומהם נעשה עיקר התהוות בי\"ע, אך דרך ירידתם ונפילתם מלמעלה למטה נתברר מהם כל מה שיוכל להתברר, וסדר הבירורים הוא כסדר ההשתלשלו' דאבי\"ע דמה שנברר לפני האצי' כמו בעקודים כו' נברר ונכלל שם והמותרות מהם שלא נבררו לפני האצי' ירד באצי' ונברר שם, ומה שיוכל להתברר וליכלל באצי' נכלל שם והשאר שלא יכלו להתברר וליכלל באצי' להיותם בחי' הסיגים שאינם נכללים בבחי' אצי' ירד לעולם הבריאה, ועד\"ז הי' סדר הבירורים שלהם מבריאה ליצי' ומיצי' לעשי' עד דמה שלא נברר מהם גם בעשי'<sup data-n=\"993\">91</sup> נעשה מהם פסולת גמור והן שרש גקה\"ט לגמרי כו' וכמ\"ש ביאור זה במ\"א. והנה המשל לזה הענין הוא מה שאנו רואים עץ הנשרף באש לגמרי ולא נשאר בו רק האפר וכבר נודע<sup data-n=\"994\">92</sup> הקושי' דהלא העץ הי' כלול מד' יסודות ארמ\"ע ואם ג' היסודות אבדו והלכו להם בשריפה למה נשאר האפר שמיסוד העפר שבו ומדוע לא יאבד ויכלה גם יסוד העפר שבעץ ע\"י השריפה, והתירוץ ע\"ז פשוט הוא לפי שהאש טבעו לכלות כל דבר שנאחז בו כידוע והיותר מוכן לכליון מפני דקותו ורוחניותו הוא מכלה כחו תחלה, והנה היסוד היותר רוחני הוא יסוד",[["991","89","<b>עפר אשר בקרקע המשכן</b>: נשא ה, יז."],["992","90","<b>שבה\"כ דז' מלכי'</b>: ראה ע\"ח שער הכללים פ\"א."],["993","91","<b>בעשי'. . פסולת גמור</b>: ראה ע\"ח שער (מג) ציור עולמות בהקדמה. שער (מז) סדר אבי\"ע פ\"ז. שער (מט) קליפות נוגה פ\"ו."],["994","92","<b>נודע הקושי' דהלא העץ הי' כלול מד' יסודות</b>: ראה גם אגרת הקודש סט\"ו. לקוטי תורה חקת נו, ג. ס, ב. תו\"ח ויגש רלב, ג."]]],[2100490235,"האש שבעץ מכלה ומוציא כחו מיד ואח\"כ גם יסוד המים ויסוד הרוח שבו שואב ומכלה ואחר שכלה היותר רוחניי' ולא נשאר בו רק בחי' העפר היסוד היותר גס שאין בכחו עוד לשאוב ולכלות ע\"כ הוא נשאר והוא האבק ועפר שנשאר אך הנה מ\"מ מעט מזעיר מן היסודות הרוחניי' נמצא בו אבל הוא מן בחי' הפסולת שלהן שנשארו אחרי שביררן האש ושאב מהם מה שיוכל לשאוב ונמצא שהאפר והאבק הוא בחי' פסולת היותר אחרון מכל מה שנשאר אחר בירור הד' יסודות ארמ\"ע כי אף מיסוד העפר הוא בחי' הפסולת ואמנם גם מג' יסודות הראשונים יש בו והכל מבחי' הפסולת שאין לו בירור עוד כו' וד\"ל. והנמשל מכ\"ז יובן למשכיל למעלה בענין סדר הבירורים דרפ\"ח ניצוצין שנפלו בשבירה שהאור היותר דק בהם נברר תחלה ונכלל באור האלקי המבררם והאור שאינו דק כ\"כ נשאר ונברר אח\"כ ועד\"ז נבררו מלמעלה למטה דרך ירידתם באבי\"ע מאצי' לבריא' כו' וה\"ז עד\"מ בבירור ד' יסודות ארמ\"ע הנ\"ל עד שבעולם העשי' נשאר מהם בחי' הפסולת היותר אחרון והן היכלות החיצוני' כנ\"ל וא\"כ נמצא שמהות מציאת החיצוני' שרשם למעלה רק בבחי' אבק שהוא הנשאר מן הבירור היותר אחרון מפני שהמברר שאב הכל מה שיוכל לשאוב ולברר כו'.\n<b>וזהו</b> שאמר אבק דא דאשתאר מן נורא דוקא מפני שהאש שאב הכל והאבק הנשאר אח\"כ הוא בחי' פסולת היותר אחרון שלא נשאר בו רק חיות מעט מזעיר מאד וממנו נמצא שרש מציא' החיצוני' ונק' נוק' דז\"א דקליפה וכמ\"ש בסוף המאמר, והיינו מה שאמר מה בין עפר לאבק עפר דכל איבין נפקין מיני' שהוא בחי' מל' דקדושה שמחי' כל העולמות מאין ליש כנ\"ל ואת זלעו\"ז כו' מל' דקליפ' בהיפוך דא אבק דלא עביד איבין לעלמין כנ\"ל מפני שהוא בא אחרי כל הבירורים ולא נשאר בו שפע חיות כלל ואמנם מ\"מ מעט מזעיר מהארה אלקי' יש שם בהכרח שהרי באבק הגשמי אם זורעין בו מצמיח קצת, ולכך לענין כסוי הדם כשר לכסות באבק מפני שזורעין בו ומצמיח אלא שאין הצמיחה מרובה כמו בעפר שמצמיח פירות ותבואות הרבה, וגם בזאת עוד יתרון מעלה שהעפר מצמיח גם בלתי זריעה כמו עשבים שצומחין מאליהן וגם מה שזורעין מצמיח בתוס' מרובה עד ק' פעמים יותר מן הזריעה וכ\"ז מפני שבעפר יש בו כח חיות הרבה מצד שלמעלה ג\"כ נתחב\"ס וע\"כ הכל הי' מן העפר דוקא וכנ\"ל משא\"כ אב\"ק, ומ\"מ גם האבק מפני שלא נברר לגמרי מכל וכל ועדיין יש בו חיות מעט מזעיר ע\"כ אם זורעין בו מצמיח קצת, אבל לע\"ל דכתיב ואת<sup data-n=\"995\">93</sup> רוח הטומאה אעביר כו' אעביר לגמרי מפני שיבורר ממנו הכל ולא ישאר בו אפי' אפס קצה ההארה מההארה האלקי' וכמ\"ש חיל<sup data-n=\"996\">94</sup> בלע ויקיאנו לגמרי וכן בלע<sup data-n=\"997\">95</sup> המות לנצח וכו', וזה ידוע שאין יניקת החיצונים אלא ממה שנשאר אחרי הבירור מן הקדושה כו' וע\"כ גם לבחי' אבק לא ידמה הס\"א אז מפני שיבורר ממנו הכל ולא יהי' בו חיות כלל גם אם זורעין בו לא יצמיח כלל כו' וד\"ל.",[["995","93","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["996","94","<b>חיל בלע ויקיאנו</b>: איוב כ, טו."],["997","95","<b>בלע המות לנצח</b>: ישעי' כה, ח."]]],[2100490236,"<b>וזהו</b> שארז\"ל ויאבק איש עמו שהעלו אבק ברגליהם, פי' אב\"ק הוא בחי' נוק' דס\"מ שנק' אב\"ק דאשתאר מן נורא כמ\"ש בזוהר וענין עליי' האבק היינו שנתברר גם אותו מעט החיות ואור הנמצא בו ועלה ונכלל בקדושה האלקי' אחר שנצחו יעקב בהאבקו עמו וכנ\"ל, דלכך אמר העלו ל' רבים משום דבשני יצריך דא הוא רזא כו', ולהיכן נכלל בודאי אין העלי' וההתכללות אלא באותה המדה שהיא כנגדו בקדושה והיינו שאמרו שהעלו האבק עד כסה\"כ דוקא, פי' כסה\"כ הוא בחי' מל' דקדושה דמאחר דאת זלע\"ז כו' בירור נוק' דקליפ' עולה ודאי ונכלל בבחי' נוק' דקדושה ובירור ז\"א לז\"א כמו עליות המדות הרעות למטה הוא במדות דקדושה כנ\"ל בענין מלחמת חיבוק יעקב עם שר של עשו כו'. ומה שאמרו שהעל\"ו ברגליה\"ם כי רגלי\"ה יורדות מות כתיב ואחר שבירר והעלה כל בחי' הטוב שיש באבק דקליפ' גם היותר אחרון אשר גם תחת בחי' רגלי השר של עשו העלה כו' וד\"ל.\n<b>(וז\"ש</b> בסוף המאמר הנ\"ל) אמר לו ר' יהודה אי הכי מאי מקים מעפר דל א\"ל כמשמעו אבל בהאי גוונא מקים מעפר דל בגין דלית לי' מגרמי' כלום, ומההוא עפרא נפיק דל דלית לי' כלום, ומההוא עפר כל איבין וכל טיבין דעלמא נפקין מיני' ובי' אתעבידו כל עובדין דעלמא כמ\"ש הכל<sup data-n=\"998\">96</sup> הי' מן העפר ואפי' גלגל חמה כו', אבל אבק לא עביד איבין לעלמין ובג\"כ ויאבק איש דאתיא בההוא אבק ורכיב עלי' בגין לקטרגא לי' ליעקב עכ\"ל. הנה מ\"ש בסוף דבריו דאיש הוא דאתא בהאי אבק ורכיב עלי' כו' ר\"ל בחי' ז\"א דקליפ' דרכיב על אבק בחי' נוק' ואתא לקטרגא בי' גם בההוא אבק למטה והיינו להשפיל המדות שלו שיומשכו במדות דנוק' דקליפ' דהיינו בהאי אבק כו', ובחי' דכר דקליפ' שהוא דרכיב על האי אבק ר\"ל בחי' המלחמה העליונה דהוא מגביה א\"ע כנשר כנ\"ל ועולה עד רום המעלו' לקבל מעצמו' המאציל כו' וכשהעלו האבק עד המל' דקדושה שנק' כסה\"כ בזאת ההוראה שנצחו במלחמה העליונה שבבחי' האצי' וכמ\"ש למעלה וד\"ל.\n<b>ומה</b> ששאל ר\"י אי הכי ר\"ל אם עפר הוא בחי' מל' דאצי' למה דל משכנו בעפר דוקא, והשיבו דהמל' כלול מב' הפכי' מצד שנעוץ תחב\"ס כנ\"ל, ובחי' הכתר ג\"כ כלול מב' הפכי' הללו והיינו מצד בחי' התחתונה שבעצמו' שנק' בחי' דל דלית לי' מגרמי' כלום כ\"א מה שנותנין לו מלמעלה כו' ומצד שהוא מקור ושרש לנאצלים כל טיבין דעלמא נפקין מיני' כו', וכך הוא ג\"כ בבחי' מל' דאצי' מאחר שנעוץ תחב\"ס דוקא, וזהו שאמר בהאי גונא מקים מעפר דל, פי' בהאי גונא שסיים למעלה דאיהו כללא דעילא ותתא בבחי' הכתר כך בהאי גונא גם למטה בבחי' מל'<sup data-n=\"999\">97</sup> הוא מקים את הדל כו', ומפרש כיצד משום דדל לית לי' כלום וע\"כ היא הנותנת דוקא דכל טיבו דעלמא נפיק מיני' ובי' אתעבידו כל עובדין דלעילא כו' וזהו שאמר ומההוא עפר נפיק דל ומההוא עפר כל איבין כו' הכל ענין א' וטעם א' להם והוא",[["998","96","<b>הכל הי' מן העפר</b>: קהלת ג, כ."],["999","97","<b>מל'. . לית לי' כלום</b>: ראה תו\"ח לך לך פג, ב — כמ\"ש בזהר ע\"פ אשרי משכיל אל דל (תהלים מא, ב) — וראה ג\"כ ספר המאמרים תקס\"ד ע' רסג. ביאורי הזהר בלק קו, ד. יהל אור ע' קנח ואילך. מאמרי אדמו\"ר האמצעי קדושים ע' תקסט."]]],[2100490237,"משום שאמר למעלה דבהאי גונא מקים מעפר דל בגין דלית לי' כלום והיינו מטעם הנ\"ל וד\"ל.\n<b>ומ\"ש</b> הכל הי' מן העפר ואפי' גלגל חמה ר\"ל גם בחי' שם מ\"ה וב\"ן שבאדם דכר ונוק' נעשה מן העפר כי שרש המ\"ד נמצא גם הוא מן העפר וכמ\"ש באדם<sup data-n=\"1000\">98</sup> שנעשה מן האדמה כו' וכמו שהמטר והעננים מתהווים מן אידי הארץ כו' וכמ\"ש מעלה נשיאים כו' וזהו שגם גלגל חמה שהוא בחי' נרתק לשם הוי' כמ\"ש כי<sup data-n=\"1001\">99</sup> שמש ומגן הוי' אלקים הכל הי' מן העפר וכל זה מטעם הנ\"ל שבחי' כת\"ר שרש המל' כלול מכל המדרגו' הנ\"ל וד\"ל.\n&lt;פ&gt;",[["1000","98","<b>שנעשה מן האדמה</b>: ראה בראשית ב, ז."],["1001","99","<b>כי שמש ומגן הוי' אלקים</b>: תהלים פד, יב."]]],[2100490238,"<h3>נוסח שני: בזוהר פ' וישלח ויאבק איש עמו</h3>\n<b></b><b>בעזה\"י, ליל ש\"ק פ' וישלח, שנת תקסוא\"ו לפ\"ק</b>\n<b>בזוהר</b><sup data-n=\"1002\">1</sup> (פ' וישלח ד' ק\"ע ע\"א) ויאבק איש עמו מאי ויאבק דאמר רבי יהושע בן לוי מלמד דסליקו אב\"ק ברגליהו\"ן עד כורסי יקרא כו' ר\"ש אמר אבק תפל לעפר מה בין עפר לאב\"ק דא אב\"ק דאשתאר מן נורא ולא עביד איבין לעלמין עפ\"ר דכל איבין נפקין מיניה ואיהו כללא דלעילא ותתא כו' יע\"ש עד הכל [הי'] מן העפר והכל שב אל העפר אבל אבק לא עביד פירין ואיבין לעלמין ובג\"כ ויאב\"ק איש דאתי' בההוא אב\"ק ורכיב עליו לקטרגא לי' ליעקב כו' וכך הוא לזמנא דאתי בגין דגלותא השתא כליליא &lt;פא&gt;\nדמי' כו' ושלטא ההוא אב\"ק על ישראל ואינון שכיבי לעפרא עד דיסתלק נהורא ויתנהר יממא וכדין ישלטון ישראל כו' יע\"ש.\n<b>והענין</b> דהנה לכאורה יפלא מאד איך יתכן למעלה ענין המלחמה של יעק\"ב ושרו של עש\"ו שהוא בחי' המלחמה בין סט' דקדושה לסט\"א וכדכתיב מלחמה<sup data-n=\"1003\">2</sup> להוי' בעמלק מדור דור וזהו וירא<sup data-n=\"1004\">3</sup> כי לא יכול לו ויגע בכף<sup data-n=\"1005\">4</sup> יריכו הם נו\"ה דז\"א הוא יעקב דאצי' ששם שרש הנבואה שלכך פסקה הנבואה מישראל עד שמואל הרמתי שתיקן נו\"ה דאצי' באמרו וגם נצ\"ח<sup data-n=\"1006\">5</sup> ישראל לא ישקר כו' ולזאת תחלת דבר ה' בו הי' במלחמת עמלק פקד\"תי<sup data-n=\"1007\">6</sup> את אשר עשה לך עמלק וגו' כמשנ\"ת במ\"א.",[["1002","1","<b>בזוהר (פ' וישלח ד' ק\"ע ע\"א) ויאבק איש עמו</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (ריב, ב).\nהנחת כ\"ק אדה\"א נדפס לעיל ע' קמח.\nנוסח אחר נדפס בתו\"א כו, א."],["1003","2","<b>מלחמה להוי' בעמלק</b>: בשלח יז, טז."],["1004","3","<b>וירא כי לא יכול לו</b>: ויגש לב, כו."],["1005","4","<b>בכף יריכו. . פסקה הנבואה</b>: בתו\"א שם — וכנודע מן הפרדס [שער יז]."],["1006","5","<b>נצח ישראל לא ישקר</b>: שמואל-א טו, כט."],["1007","6","<b>פקדתי את אשר עשה לך עמלק</b>: שמואל-א טו, ב."]]],[2100490239,"<b>והלא</b> ממך<sup data-n=\"1008\">7</sup> הכל שגם שורש החיים והקיום של החצונים הוא מסט' דקדושה שיונקי' מהשפע דקדושה לצורך קיומם ואין לך דבר שחוץ ממנו ית' והראי' שלע\"ל כשיתברר מהם הטוב והחיות דקדושה שינקו לגמרי אז יתבטלו ויחזרו לאין ואפס ממש, מצד שהם בעצמם בלתי החיות דקדושה שבהם א\"א להם להתקיים אפי' רגע אחת לכך לע\"ל נאמר ואת<sup data-n=\"1009\">8</sup> רוח הטומאה אעביר מן הארץ וגו' שממילא יהי' רוח הטומאה נתבטל וכלה כשיתברר ממנו החיות דקדושה שבו, ומעתה לפי\"ז איך יתכן בחי' המלחמה לד' בעמל\"ק שיעמדו החצונים לנגד סט' דקדושה להרים ראש ולהגביה א\"ע כנשר מאחר שכל עיקר קיומם וחיותם הוא מסט' דקדושה כנ\"ל.\n<b>אך</b> הענין הוא שיש למעלה ב' בחי' ומדרגות שונות באופן ירידת השפע והחיים מחיי החיים אור א\"ס ב\"ה, והיינו בחי' סדר ההשתלשלות עילה ועלול מעולם ועד עולם בכל סדרי ההשתלשלות עולמות אבי\"ע שמתצמצמה השפע בצמצומי' רבים בכלים מכלים שונים בצמצום אחר צמצום ומיעוט אחר מיעוט עד שעולם העשי' הוא תכלית וסוף כל סדרי ההשתלשלות כולן שהוא מדרגה התחתונה שבכולן שאין למטה הימנה אשר רחוקה מאד בערך מעלת האצי' העליון בסדר ההשתלשלות כו' הנה כ\"ז הוא בחי' הא' של ירידת השפע כשיורדת בסדר והדרגות ההשתלשלות בצמצומים רבים מעילה לעלול ומעולם ועד עולם שימצא בזה בחי' יתרון העליון על התחתון לפי ערך מעלת העליון ושפלות התחתון עד שעולם העשי' היא תכלית השפלות שבמדרגות עליונות ועולם האצי' העליון והראש לכל לכך הם רחוקים זמ\"ז בתכלית הריחוק וההבדל מאד שגדול מאד היתרון של עולם האצי' הראש והעליון לגבי עשי' השפל והתחתון כו'.\n<b>והבחי'</b> השנית היא כשיורדת השפע מעצמו' אור אין סוף ב\"ה המרומם לבדו ומתנשא מימות עולם דלאו בי' מאינון מדות כלל וכולם אין ערוך אליו כלל בשוה השוה<sup data-n=\"1010\">9</sup> ומשוה קטן וגדול דכחשיכה<sup data-n=\"1011\">10</sup> כאורה שוי' קמי' בהשואה א' בלי מציאות יתרון<sup data-n=\"1012\">11</sup> האור מתוך החושך מצד שאפי' אור<sup data-n=\"1013\">12</sup> צח &lt;פב&gt;\nומצוחצח אתחשך קמי' ולזאת במה נחשב הוא יותר מן החשך וכך להיפך גם<sup data-n=\"1014\">13</sup> חשך ממש לא יחשך ממך ולילה כיום יאיר נמצא משתוים קמי' האור והחשך בבחי' הביטול בהשואה א' בלי נמצא יתרון האור מתוך החשך מצד שמעלת האור נמצא בו יתרון לגבי החשך הוא רק בסדר הדרגת ההשתלשלות היינו באורות המלובשים בתוך הכלים דע\"ס דאבי\"ע אבל לגבי עצמו' המאציל המרומם לבדו שניהם שוים בערך הביטול בהשואה א' דאפי' אור צח אתחשך קמי' ואינו תופס מקום כמו החשך ממש וכן גם חשך לא",[["1008","7","<b>ממך הכל</b>: דברי הימים-א כט, יד."],["1009","8","<b>ואת רוח הטומאה אעביר מן הארץ</b>: זכרי' יג, ב."],["1010","9","<b>השוה ומשוה קטן וגדול</b>: פיוט (ימים נוראים) האוחז ביד מדת משפט."],["1011","10","<b>דכחשיכה כאורה שוי'</b>: תהלים קלט, יב. ראה עטרת ראש לעשי\"ת ע' נא."],["1012","11","<b>יתרון האור מתוך החושך</b>: קהלת ב, יג."],["1013","12","<b>אור צח ומצוחצח</b>: ראה תקו\"ז ת\"ע (קלה, ב)."],["1014","13","<b>גם חשך. . לא יחשך</b>: תהלים שם."]]],[2100490240,"יחשך ממך וכיום יאיר וכנ\"ל. ולזאת מהשפע זאת היורדת מעצמו' אור א\"ס ב\"ה המרומם לבדו השוה ומשוה קטן וגדול יוכלו גם החצונים וס\"א לקבל ממנו ממש כמו הסט' דקדושה מאחר דקמי' כחשיכה כאורה שוי' לזאת במה נחשב יותר סט' דקדושה במציאות הביטול שנמצא בה שגם הביטול של סט' דקדושה אין תופס מקום כלל נגדו ית' כי במה נחשב הוא מאחר שמציאות הביטול נמצא מע\"ס דקדושה דאבי\"ע שאין ערוך אליו דלאו בי' מאינון מדות כלל וכמ\"ש אם<sup data-n=\"1015\">14</sup> צדקת מה תתן לו וגו' וכן להיפך בחי' הרע של החצונים וס\"א שנסתעף מהם למטה בחי' ע' אומות עע\"ז אין תופס מקום נגדו כלל שיתפעל מזה באף וחימה עליהם מצד שכלא חשיבו בלי מקום כלל וכמ\"ש במשלי שלמה המלך ע\"ה שממית<sup data-n=\"1016\">15</sup> בידים תתפש והיא בהיכלי מלך והנמשל ממילא יובן שבחי' הרע של חצוני' וס\"א אין תופס מקום נגד עצמותו ית' כלל עד שלא יתכן בהם האף והחימה לירגז עליהם כמו שאין תופס מקום בעיני המלך השממית שתתפש בהיכלו אף ששנואה היא לירגז עליו כו'. וזהו ורבו<sup data-n=\"1017\">16</sup> פשעיך מה תפעל לו וכו' דכחשיכה כאורה שוי' כנ\"ל ולכך זהו באמת צמצום גדול ועצום מאד נגדו ית' שיתצמצם השפע הפנימי' דאור א\"ס ב\"ה בכלי' מכלי' שונים דקדושה דאבי\"ע שיגיע הארתו הפנימי' רק לסט' דקדושה בלבד ולא לסט\"א כמ\"ש יאר<sup data-n=\"1018\">17</sup> ה' פני\"ו אליך אליך דייקא בהארת פנים העליון והחצוני' מקבלי' מבחי' אחורי העו\"ר דנוק' דאצי' שעו\"ר דנוק' הם בחי' צרופי האותיו' שבה שמאחורי העו\"ר בשביל יניקו' החצוני' וזהו באמת נעשה לאחר הצמצום שהי' באור א\"ס ב\"ה שנעשה חלל ומקום פנוי ובתוכו נמתח הקו והחוט דק של אור א\"ס וממנו נמשכו כל העולמות עקודים נקודים וברודים ובי\"ע שאז נתצמצם השפע בכלים מכלים שונים דסט' דקדושה שלא תגיע פנימי' השפע רק לסט' דקדושה בלבד ולא לסט\"א זולתי מבחי' אחוריי' דקדושה בלבד יונקי' החצוני', והיינו מאחר שנעשה הצמצום באור א\"ס שאז נמשכו סדרי ההשתלשלות דענ\"ב ובי\"ע אז ימצא יתרון האור לגבי החשך והעליון לגבי התחתון שאז תופס מקום מעשה התחתוני' אם ייטיבו דרכיהם או לא (ששם שרש השכר והעונש כידוע) ולכך ממילא יורחקו החצוני' שא\"א להם לקבל מפנימיות השפע דקדושה שאינה מגעת רק לבחי' הכלים שנמצא בהם בחי' הביטול שהם הכלים דקדושה בלבד משא\"כ הם בחי' י\"ש נפרדים &lt;פג&gt;\nדקרו<sup data-n=\"1019\">18</sup> לי' אלהא דאלהא כו' כנ\"ל, וכ\"ז לאחר הצמצום דאור א\"ס ב\"ה אבל קודם הצמצום הי' יורד השפע מעצמו' אור א\"ס ב\"ה המרומם לבדו בהשואה אחת לכולם בלי התחלקו' והבדל בין אור לחושך ובין ישראל לעמים כלל דכחשיכה כאורה כנ\"ל וד\"ל.\n<b>והנה</b> סבת הצמצום דאור א\"ס ב\"ה הי' ע\"י יעקב<sup data-n=\"1020\">19</sup> אע\"ה י' עק\"ב בבחי' המקלו\"ת אשר<sup data-n=\"1021\">20</sup> פיצל ברהטים כו' שכונתו הי' בזה בכדי שיהי' הצמצום באור א\"ס",[["1015","14","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["1016","15","<b>שממית בידים תתפש</b>: משלי ל, כח."],["1017","16","<b>ורבו פשעיך מה תפעל לו</b>: איוב לה, ו (מה תעשה לו)."],["1018","17","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["1019","18","<b>דקרו לי אלקה דאלקה</b>: מנחות בסופה."],["1020","19","<b>יעקב. . י' עקב</b>: ע\"ח שער ג (שער סדר אצי' למהרח\"ו) פ\"ב. פרדס שער כג (שער ערכי הכינויים) בערכו."],["1021","20","<b>אשר פיצל ברהטים</b>: ויצא ל, לח."]]],[2100490241,"להיות נעשה החלל ואח\"כ נמשך בצמצום קו וחוט דק שממנו נמשכו בחי' עולמו' עקודים נקודים וברודי' עד שנתצמצמו האורות בכלים דע\"ס דברודי\"ם הוא עולם התיקון דאצי' כמ\"ש וארא<sup data-n=\"1022\">21</sup> בחלום והנה העתודים העולים על הצאן עקודים נקודים וברודים כו' שאז ממילא בלתי אפשר להחצונים לקבל מפנימיו' השפע זולתי מבחי' אחורי' דקדושה כנ\"ל משא\"כ קודם לכן הי' יונקי' מפנימי' השפע ממש כמ\"ש וללבן<sup data-n=\"1023\">22</sup> שתי בנות וגו' שכל הפרצופי' דלאה ורחל דתיקון דאצי' עדיין נקראי' ע\"ש לב\"ן העליון שממנו הי' מגיע השפע אף להחיצוני' וכן הצאן שלמעלה הי' צא\"ן לב\"ן כמ\"ש ומאשר<sup data-n=\"1024\">23</sup> לאבינו עשה כל הכבוד הזה וגו' כמשנ\"ת במ\"א ע\"ש, וכמ\"ש ואלה<sup data-n=\"1025\">24</sup> המלכי' אשר מלכו בארץ אדום לפני מלך מל\"ך בישראל שמאחר שלא הי' עדיי\"ן מל\"ך בישראל הוא התיקון דאצי' לכך מלכו הז' מלכים קדמאי' בארץ אדום שמשם ינקו פנימי' השפע עליונה מאחר ששם כחשיכה כאורה שוי' כו' אבל לאחר שעשה יעקב את המקלו\"ת אשר פיצל ברהטים כו' והמשיך מבחי' הצמצום דאור א\"ס ב\"ה את בחי' עולמו' ענ\"ב עד שנעשה בחי' התיקון דאצי' שנתצמצמו האורו' בהכלי' דע\"ס דתיקון דאצי' שאז מלך מלך בישראל הוא עולם התיקון כנודע אז נאמר ומלך<sup data-n=\"1026\">25</sup> אין באדום נצב מלך וגו' מצד שנתחלק פנימיו' השפע בבחי' צמצום שלא תגיע רק בבחי' הכלים שנמצא בהם מציאו' הביטול והוא נימצא בסט' דקדושה לבד אבל החצונים יונקי' מאחורי עו\"ר דנוק' בלבד דהא בהא תלי' שלכך מלכו הז' מלכין קדמאין דתה\"ו באדום מצד שהי' לפני מל\"ך מל\"ך בישראל שהוא קודם שנעשה התיקון דאצי' אבל לאחר שמלך מלך בי\"שראל דתי\"קון דאצי' אזי ממילא אין [מלך] באדום נצב מלך כנ\"ל וד\"ל.\n<b>והנה</b> בקדושה ימצא כמה מדרגות שונות בבחי' מציאות הביטול דהיינו שדרך כלל מתחלקים הע\"ס דקדושה מהכתר עליון לג' חלקים והמה חב\"ד חג\"ת נהי\"מ שבחב\"ד ימצא בחי' עצמו' תכלית הביטול האמתי שבהם ישרה עצמו' אור א\"ס ב\"ה ואין אור אין סוף שורה זולתי בכלי הביטול האמיתי שהמה חב\"ד דאצי' שהם כלי הביטול העצמי' של בחי' מ\"ה ומכ\"ש בחי' הכ\"ע כנודע משא\"כ בחי' חג\"ת שהם תולדותיהן דחב\"ד שהם כיוצא בהן שימצא בהם ג\"כ בחי' הביטול אבל איננו בחי' הביטול העצמיי האמתי של בחי' מ\"ה שבחב\"ד מאחר שהם תולדותיהן, שהביטול שנמצא בהם נחשב &lt;פד&gt;\nלבחי' י\"ש ודבר מה נגד הביטול העצמיי דכח מ\"ה שבחב\"ד, ואעפ\"כ ימצא בהן הארת הביטול דכח מ\"ה אבל הארתו בלבד ולא מהותו ועצמותו ממש. ובחי' נהי\"מ שבה הם בחי' ענפיהן של המדות חג\"ת שהם לבר מגופא שאין נמצא בהן אף מהו' הביטול דחג\"ת ואעפ\"כ ימצא בהם הארת הביטול דחג\"ת כו'. שלשה חלקים אלו ימצא במציאות הביטול בע\"ס דקדושה שבכל עולם ועולם מעולם ועד עולם בכל סדרי ההשתלשלות דאבי\"ע וכמ\"כ למטה בנפש האלקית שבישראל ימצא ג' חלוקות אלו שבחי' מציאות הביטול שבחב\"ד שבנפשו הוא תכלית הביטול",[["1022","21","<b>וארא בחלום</b>: ויצא לא, י."],["1023","22","<b>וללבן שתי בנות</b>: ויצא כט, טז."],["1024","23","<b>ומאשר לאבינו עשה</b>: ויצא לא, א."],["1025","24","<b>ואלה המלכי' אשר מלכו בארץ אדום</b>: וישלח לו, לא."],["1026","25","<b>ומלך אין באדום</b>: מלכים-א כב, מח."]]],[2100490242,"של כח מ\"ה כשישכיל המשכיל בגדולת א\"ס ב\"ה איך שכלא כלא חשיבי ואין<sup data-n=\"1027\">26</sup> עוד מלבדו זהו תכלית הביטול העצמיי של בחי' ונחנו מ\"ה שהוא בקרירו' ונחת כנודע ותולדותיהן כיוצא בהן הם המדו' אהוי\"ר שנסתעפו מהתבוננות השכל וההשגה שהם בחי' יש ודבר נגד הביטול העצמי דבחי' מ\"ה כו' שיש מי שאוהב כו' כנודע ובחי' נה\"י שבנפשו הוא מדריגה התחתונה שבכולן שהוא בחי' מעשה המצות כולן שכללותן הוא מעשה הצדקה<sup data-n=\"1028\">27</sup> שכנגד כולן שימצא בהם ג\"כ בחי' הארת הביטול דחג\"ת אבל אינן כמהו' הביטול דחג\"ת כנ\"ל, ואעפ\"כ בכל המדריגות חלוקות שונות באיכות הביטול דקדושה תתלבש השפע פנימי' של אור א\"ס ב\"ה בכל עולם מעולם ועד עולם ובכל הנבראי' פרטיים שונים ומשונים זמ\"ז באיכות הביטול פרטיי של כל חד וחד לפום שיעורא דילי' אבל החצונים שאין נמצא בהם בחי' הביטול דקדושה כלל אף לא מבחי' ומדרגה תחתונה שבהן לכך אא\"ל לקבל זולתי מאחוריים דקדושה מאחורי עור דנוק' בלבד כנ\"ל וד\"ל.\n<b>וזהו</b> ענין המלחמה להוי' בעמלק מדור דור וכן ענין המלחמה דיעק\"ב ושרו של עשו בהאבק\"ו עמו בהיות כמו שהשפע נתצמצמה בסדר ההשתלשלות דאבי\"ע בכלי' מכלים שונים דקדושה שנמצא בהן בחי' מציאות הביטול דוקא כמ\"ש יאר ה' פניו אלי\"ך דוקא אזי א\"א להחצוני' לקבל זולתי מתמצית דקדושה לבד מאחורי עור דנוק' כנ\"ל ולזאת מתנשאים ומגביהים א\"ע למעלה מעלה בעזות וחוצפה נגד סט' דקדושה שאינם רוצים להיות כפוף אליה ולקבל התמצית שלה זולתי התנשאות למעלה מסט' דקדושה אל עצמות אור א\"ס ב\"ה שלמעלה מסדר ההשתלשלות דכחשיכה כאורה שוי' קמי' שמשם יוכלו לקבל מפנימי' השפע כמו סט' דקדושה ממש, ולכך מגביהי' א\"ע כנשר למרוד בה' הוא סט' דקדושה שבסדר ההשתלשלות להיות כפוף אליה לקבל התמצית שלה זולתי להתנשא למקור שרשם שלמעלה מסט' דקדושה שבסדר ההשתלשלות שהוא עצמות אור א\"ס דכחשיכה כאורה שוי' קמי' כנ\"ל. וזהו מ\"ש אם<sup data-n=\"1029\">28</sup> תגביה כנשר משם אורידך נאום הוי' פי' אם תגביה א\"ע כנשר שדרך הנשר הגבה למעלה בשמים להיותך מתנשא למעלה אל עצמו' אור א\"ס ב\"ה דכחשיכה כאורה שוי' קמי' שמשם תוכל לקבל החיות מפנימיות השפע כמו סט' דקדושה ממש משם אורידך נאום הוי\"ה פי' הוי' הוא כללות סדר ההשתלשלות י'<sup data-n=\"1030\">29</sup> הוא חכמה ה' בינה ו' ז\"א ה' נוק' כו' שבכל עולם ימצא בחי' הוי' מריש כל דרגין ועד סוף כל דרגין שאף &lt;פה&gt;\nבעולמת עקודי' נקודים וברודי' ימצא בחי' הוי' שמורה על המשכת השפע בסדר והדרגת ההשתלשלות כו' ולכך משם<sup data-n=\"1031\">30</sup> אורידך נאום הוי\"ה דוקא שבחי' ש' הוי' שבסדר ההשתלשלות דקדושה הוא עצמו המורד את הסט\"א מלהתנשא ולהגביה א\"ע כנשר לעילא לעילא אל עצמו' אור א\"ס ב\"ה שמאחר שנמשך בחי' ש' הוי' שמורה על המשכת השפע בסדר והדרגת ההשתלשלות להתצמצם בכלים דע\"ס דקדושה אזי ממילא מוריד את הסט\"א שאז",[["1027","26","<b>ואין עוד מלבדו</b>: ואתחנן ד, לה."],["1028","27","<b>הצדקה שכנגד כולן</b>: ב\"ב ט, א."],["1029","28","<b>אם תגביה כנשר</b>: עובדי' א, ד."],["1030","29","<b>י' הוא חכמה</b>: ראה זהר (אדרא זוטא) האזינו רצ, ב. אגה\"ת פ\"ד."],["1031","30","<b>משם אורידך</b>: ירמי' מט, טז. עובדי' א, ד."]]],[2100490243,"לא יוכלו לקבל רק מאחוריים ותמצית דקדושה ומוכרחים להיות כפוף אליו מפני שכל כונתם בהגבהתם א\"ע כנשר הוא להגיע לפני הוי' אל בחי' עצמו' אור א\"ס דלאו בי' מאינון מדות כלל שאף הביטול דע\"ס דקדושה אין תופס מקום כלל ובמה נחשב הוא מאחר שלאו בי' מאינון מדו' כלל ולזאת כחשיכה כאורה שוי' אבל כיון שנמשך בחי' הוי\"ה שהוא כלליות סדר ההשתלשלות דע\"ס דאבי\"ע וענ\"ב אזי ממילא ימצא יתרון של האור מתוך החשך שלא תגיע פנימי' השפע רק להכלי' דע\"ס דקדושה שנמצא בהם בחי' הביטול משא\"כ החשך של הקליפות שמקבלי' רק מתמצי' דקדושה כנ\"ל, ולכך משם אורידך נאום הוי\"ה דוקא כנ\"ל וזהו מלחמה להוי\"ה דוקא בעמל\"ק שהיא סט\"א מדור דור שלאום מלאום יאמץ שלפעמים מתגבר סט' דקדושה בהמלחמה כמ\"ש משם אורידך נאום הוי\"ה ולפעמים להיפך ח\"ו וזה תלוי במעשה התחתונים של ישראל כנודע.\n<b>וזהו</b> ויאב\"ק<sup data-n=\"1032\">31</sup> איש עמו וגו' שהוא שרו של עשו בחי' הס\"א שהוא הדכר דקליפה בחי' ז\"א דסט\"א שעשה מלחמה את בחי' יעק\"ב הוא ז\"א דקדושה דאצי' שהוא הדכר דקדושה כנודע.\n<b>והענין</b> הוא דהנה ידוע ששרש השבירה דז' מלכים קדמאי' דתה\"ו הי' רק בז\"ת בלבד ולא בג\"ר שהוא רק בחי' פנים בלבד כמ\"ש בע\"ח ומז\"ת דתה\"ו שנפלו דרך שבירה למטה הוא שרש התהוות המדות הרעות דקליפה הוא בחי' הס\"מ שרו של אדום הדכר דקליפה כי את<sup data-n=\"1033\">32</sup> זה לעומת זה עשה האלקים דכמו שיש בקדושה בחי' המדו' עליונות דז\"א דאצי' בחי' ומדרגת יעקב<sup data-n=\"1034\">33</sup> אע\"ה שהי' המובחר שבאבות<sup data-n=\"1035\">34</sup> הן הן המרכבה דאצי' כללא דאבהן שהוא בריח<sup data-n=\"1036\">35</sup> התיכון עמודא דאמצעיתא הכולל כל המדו' דאצי' כנודע, כך לעומת זה בקליפה בחי' הס\"מ שרו של אדום בחי' ז\"א דקליפה ששרש יניקותם מז\"ת דתהו ששם הי' השבירה ממש במלכים דאדום שמתו כנ\"ל. וכמ\"ש בזוהר דכמו שיש ז' היכלות דקדושה כך ימצא לעומת זה תמורתן בקליפה לבד מהיכל ק\"ק דבריאה שבו מתלבשים בחי' כחב\"ד דבריאה שלא ימצא כנגדו תמורה בקליפה מצד ששרש התהוות הקליפו' ושרש יניקתם הוא רק מז\"ת בלבד אבל בג\"ר אינם יכולי' לאחוז ולינק כלל מצד ששם הוא תכלית הביטול של בחי' מ\"ה שלא הי' בשבירה מעולם כנ\"ל. וזהו ענין המלחמה שהי' בין יעקב ושרו של אדום בהאבקו עמו כמשל ב' בני אדם כשרוצים להלחם זב\"ז בגבורתן שהגבור יפיל החלוש ממנו לארץ כו' &lt;פו&gt;\nשמתאבקי' זב\"ז בזרועותיהם בהתחבקות ונלחמים עד שהא' גובר על חבירו להמשיכו ולהפילו על הארץ כו' כך עד\"מ למעלה ממש שהס\"מ הדכר דקליפה רצה להלחם נגד יעקב הדכר דקדושה",[["1032","31","<b>ויאבק איש עמו</b>: וישלח לב, כה."],["1033","32","<b>את זה לעומת זה עשה האלקים</b>: קהלת ז, יד."],["1034","33","<b>יעקב. . המובחר שבאבות</b>: ראה ע\"ח שער (לח) לאה ורחל פ\"ב. לקו\"ת להאריז\"ל תולדות כז, כה. לקו\"ש ח\"ג ע' 832. וש\"נ."],["1035","34","<b>שאבות הן הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה סידור שער נפ\"א צב, ד."],["1036","35","<b>בריח התיכון</b>: ראה זהר תרומה קעה, ב."]]],[2100490244,"להיותו מתאבק עמו דהיינו שהמדו' הרעות שלו נתאבקו ונתחבקו בהמדו' הטובו' דיעק\"ב בכדי להמשיך המדו' דקדושה דיעקב למטה אליו אל החצוני' ודעתו הי' שיוכל לנצח מצד ששרש יניקות החצונים הוא מז\"ת ואת זה לעומת זה עשה אלקים ממש לכך במה ימצא כח יותר גדול בהמדות דקדושה מהמדו' דסט\"א ההפכיי' שישתוו במדריגה א', והיינו כמו עד\"מ למטה בנפש האלקית כשיתבונן המשכיל בגדולת א\"ס ב\"ה בשעת תפלה שיוליד מזה בחי' אהוי\"ר לה' ית' דהנה בשעת התפלה בעודנו עומד לפני<sup data-n=\"1037\">*35</sup> מעוטף בטלית ותפילין אשר על ראשו ועיניו לשמים נטלי' ומנדעא עלי' יתוב אזי יהי' באמת כך שיתפעל באהוי\"ר אליו ית' אך לאחר התפלה כשפנה א\"ע לעה\"ז ונסתלק ממנו בחי' הרחבת הדעת ההוא ונשאר רק בחי' החמימות וההתפעלות שבלבבו בלבד אזי יוכל להתאוה תיכף בכח האהבה ההיא ממש לתאות גשמיים גופניים של עה\"ז לחפוץ יקר וכבוד ומאכלי' מעדנים וכל מילי פרנסה ודומיהן, והיינו מצד שזלע\"ז עשה האלקים שכנגד המדו' דקדושה יש בחי' המדו' שבנפשו הבהמית ולכך יוכל להסתעף תיכף ממדו' הטובו' דקדושה המדות הרעות באין מעצור לרוחו מצד ששרש יניקתם הוא מהמדו' דקדושה כמארז\"ל דלא<sup data-n=\"1038\">36</sup> כאברהם שיצא ממנו ישמעאל ודלא כיצחק וכו'. כך ממש עד\"מ למעלה בחי' המלחמה דיעקב ושרו של אדום שכל כונתו הי' להיותו מתאבק עמו יעקב לחבקו בזרעותיו שעי\"ז יהי' המדו' שלו מקיפי' וסובבים המדות של יעקב בכדי להמשיכם אליו וינקו מהם. אך באמת לא יכו\"ל לו פי' הגם שעפ\"י דעתו הי' באפשר שיכו\"ל לו מצד שרש יניקתם מז\"ת וזלע\"ז ממש עשה האלקים ובמה יוגדל הכח בהמדות דקדושה יותר להתחזק כנגדם לנצח המלחמה, אך הענין הוא שבאמת כן הוא שמצד המדות דקדושה עצמן לא הי' בהם כח לנצח המלחמה והי' יכו\"ל ל\"ו להמשיכו אליו לינק מהם כנ\"ל אך בהיות יעקב המובחר שבאבות הן המרכבה דאצי' הוא בחי' י' עקב דהיינו שימצא הארת יסוד אבא דז\"א דאצי' שזהו בחי' יעקב י' עקב שיסוד אבא הוא פנימיו' החכמה דאצי' שנק' י' הוא בעקב שמסתיים הארתו ביסוד דז\"א דאצי' וזאת ידוע שפנימיו' חכמה נעשה מקיף לבינה והמקיפים דאימא דוחי' ומסמי' עיני החיצונים שלא יוכלו לינק רק מז\"ת דאימא מבחי' הפנימיות דאימא ולא מהמקיפי' לכך לא יכול לו.\n<b>וביאור</b> הענין מבשרי<sup data-n=\"1039\">37</sup> אחזה אלו\"ה דהנה יש ב' בחי' ומדרגות שונות בעבודת ה' באהוי\"ר שבתפילה דכאשר האהוי\"ר נולדה מהתבוננות השכל בגדולת ה' ב\"ה ממה שנתפס בגדר ההשגה ורוח בינתו ממש כו' אזי אין להמדות אהוי\"ר קיום ושמירה מהחיצונים שתיכף אחר התפילה יוכל להתאוה תאוות זרות של עוה\"ז מצד שמא\"פ שבמדות דקדושה יוכלו החיצונים לינק כמשנת\"ל. אך יש עוד מדרגה גבוה למעלה מאוד נעלה מזו &lt;פז&gt;\nדהיינו כשיתפעל מההשכלה בגדולת ה' מה שלמעלה מגדר שכלו ורוח בינתו רק שמבריק בהברקת שכלו בחי' איכות מציאות גדולת הא\"ס ב\"ה",[["1037","*35","<b>לפני</b>: אוצ\"ל: לפני ממה\"מ."],["1038","36","<b>דלא כאברהם שיצא ממנו ישמעאל</b>: ראה פסחים נו, א. וראה סה\"מ תקס\"ה ח\"ב ע' תתכט."],["1039","37","<b>מבשרי אחזה אלוקה</b>: לשון הכתוב — איוב יט, כו."]]],[2100490245,"שאין<sup data-n=\"1040\">38</sup> לו תחלה ואין לו תכלה מה שמוח שכלו קטן מהכיל ההשכלה ההיא וכן הלב לא יסבלנו ולא יכילנו כ\"א נשארה בבחי' מקיף על מוחו ולבו מלמעלה זה יהי' קיום ניצחי שאף לאחר התפילה שנסתלק הרחבת ההתבוננות נשאר בחי' רשימו מבחי' המקיף שלמעלה משכלו ומדותיו להגין עליו מיניקת החיצונים שלא יוכלו לשלוט בו מצד המקיף דחכמה כ\"ח מ\"ה שעל מוחו ולבו שהוא תכלית הביטול האמיתי שאינן יכולי' לשלוט בו כלל כ\"א אדרבה הוא דוחה החצונים ומסמא עיניהם ולכך אף במדותיו אינן יכולים לשלוט מצד הארת המקיף דחכמ\"ה שעליהן וד\"ל.\n<b>ועד\"ז</b> יובן בפשיטו' למעלה היטב שלא יכו\"ל לו ליעקב מצד הארת יסוד אבא שבחז\"ה דז\"א דאצי' הוא יעקב י' עק\"ב שפנימיו' חכמה נעשה מקיף לאימא והמקיפי' דאימא דוחי' ומסמי' עיני החצוני' כנ\"ל ולכך גדול א\"ע כח המדו' דז\"א דאצי' מצד הארת יסוד אבא שבהן שלא יהי' יכו\"ל ל\"ו בשום אופן כלל וכלל וזהו וירא כי לא יכול ל\"ו ויגע בכף יריכ\"ו וגו' פי' במדות חג\"ת דז\"א דאצי' לא הי' יכול ליגע כלל מצד הארת המוחי' דאבא תכלית הביטול בהן כנ\"ל אבל בכף יריכו הם בחי' נו\"ה דז\"א שהם כלי ההשפעה לזולתו שהם לבר מגופא שכליות יועצות כנודע שם יוכל ויגיע בהם להמשיך השפע לחצוני' שלכך פסקה הנבואה מישראל עד ימי שמואל הרמתי שחזר ותקנ\"ם באמרו וגם נצ\"ח ישראל לא ישקר כו', והענין הוא כמו עד\"מ למטה בנפש האלקית שבשעת שמדותיו דאהוי\"ר הם למעלה שישים אליו לבו באהוי\"ר שאז הארת המוחין בהבדלה ממש אזי לא יוכלו החצונים לשלוט בו אבל כיון שנשפלו המדו' להתלבש בבחי' נה\"י שבנפשו להשפיע השפע לזולתו במעשה המצות ומעשה הצדקה שכנגד כולם אזי נתמעט האור של הארת הביטול שבחכמ\"ה שהי' מאיר בהמדו' עצמן ולא בענפיהן שאינו מאיר כ\"כ בבחי' גדולות זולתי בבחי' צמצום וקטנות ולכך יוכלו לשלוט בהם כו' כנ\"ל וד\"ל.\n<b>והנה</b> המלחמה דיעקב עם האיש הנ\"ל הי' בשני אופנים למעלה ולמטה, והיינו כנודע דאתערותא דלתתא אתערותא דלעילא לזאת הייתה המלחמה בשני דרכים אלו בבחי' אתערותא דלתתא ובבחי' אתערותא דלעילא למעלה, והיינו כי מתחלה הי' המאציל חפץ<sup data-n=\"1041\">39</sup> חסד להיות נעשה הצמצום באור אין סוף ב\"ה בכדי שיהי' שרש לכל סדרי ההשתלשלות דענ\"ב ובי\"ע שיתצמצמו האורו' בכלי' מכלי' שוני' דקדושה שאליהם דייקא יגי\"ע פנימיו' השפע כמ\"ש יאר ה' פניו אליך וגו' שאז החצונים אין יכולים לקבל רק מאחורי עור דנוק' מתמצית דקדושה כנודע, והיה זה מתחלה מצד שחפץ חסד הוא בלתי אתערותא דלתתא כלל. אך עתה מצטרך להמשיך זאת ע\"י אתערותא דלתתא של ישראל, ולכך בזמן הגלות כשאין נמצא בחי' אתערותא &lt;פח&gt;\nדלתתא אזי או\"ה מושלי' הגם דכתיב ואת<sup data-n=\"1042\">40</sup> עש\"ו שנאתי הנה זהו מצד הצמצום של השפע בכלים מכלים שונים דקדושה דוקא שאז נאמר ואוהב<sup data-n=\"1043\">41</sup> את יעקב",[["1040","38","<b>שאין לו תחילה</b>: ראה חובת הלבבות שער היחוד פ\"ה. המשך תרס\"ו ע' כ."],["1041","39","<b>חפץ חסד</b>: ראה ע\"ח (שער דרושי נקודות) ש\"ח, ספ\"ו."],["1042","40","<b>ואת עשו שנאתי</b>: מלאכי א, ג."],["1043","41","<b>ואוהב את יעקב</b>: שם א, ב."]]],[2100490246,"שיגיע לכלי' דקדושה פנימיות השפע ואת עשו שנאתי שאינו מקבל רק מתמצית דקדושה מאחורי' בלבד כנ\"ל אבל בזמן הגלות נאמר קולה<sup data-n=\"1044\">42</sup> כנחש ילך וכמ\"ש ע\"ז דזנבא<sup data-n=\"1045\">43</sup> שליט לעילא ורישי' שכיבית לעפרא כו' ע\"ש פי' זנבא שליט לעיל\"א ממש כמ\"ש אם<sup data-n=\"1046\">44</sup> תגביה כנשר וגו' שמגביהים החצוני' א\"ע לקבל חיות מעצמו' אור א\"ס המרומם לבדו אשר קמי' כחשיכה כאורה כנ\"ל וזהו שליט לעיל\"א בהגבהה והתנשאו' ממש וכ\"ז מצד העדר ההעלא' מ\"ן שלמטה.\n<b>ולכך</b> היה המלחמה בב' פנים הא' הוא למעלה בבחי' אתערותא דלעילא בין יעק\"ב הוא ז\"א דאצי' ובין שרו של אדום הוא הס\"מ הדכר דקליפה בחי' ז\"א דקליפה שלא יגביה א\"ע כנשר לקבל מעצמו' אור א\"ס ב\"ה למרוד בהוי\"ה הוא ז\"א דאצי' כנ\"ל. והשנית הוא למטה בבחי' אתערותא דלתתא בין בחי' הנוק' דז\"א דקדושה הוא בחי' מלכות דעשי' שהיא סוף כל המדרגות ההשתלשלות דאבי\"ע ובין הנוק' דס\"מ שהיא סוף כל דרגין דסט\"א, וזהו בחי' ואב\"ק שנז' בזוהר הנ\"ל שעפ\"ר הוא בחי' מל' דקליפה כו' וכדמפ' הזוהר מה בין אבק לעפר דא אבק דאשתאר מן נורא ולא עביד איבין כו' עפר דכל איבין נפקין מיניה ואיהו כללא דלעילא ותתא ע\"ש.\n<b>והענין</b> דהנה כמו העפר הארץ הגשמיי הגם שה א הפחות שבד' יסודות ארמ\"ע אעפ\"כ נמצא בו מעשה יתירה יתר על כולן דהיינו מה שמצמיח כל מיני מעדנים כל הפירות הטובות וכל עשב למינו וכל מיני בושם וכל טוב הארץ כל עץ נחמד ופריו המתוק כולם יפריחו מן עפר הארץ משא\"כ בג' יסודו' אר\"מ שאינן מגדלים ומצמיחים כלל זולתי עפר הארץ תוצא צמחה כנ\"ל, כך ממש עד\"מ למעלה שמל' דאצי' היא התכלית וסוף כל דרגין דאצי' שאין למטה הימנה במדרגה דאצי' נקראת בשם עפר כמ\"ש ומעפר<sup data-n=\"1047\">45</sup> אשר בקרקע המשכן וכתיב הכל<sup data-n=\"1048\">46</sup> הי' מן העפר וגו' והיינו שאעפ\"י שהיא סוף כל דרגין דאצי' נמצא בה מעלה יתירה על הכל שהיא מקור דבי\"ע ומחדש חדשים לבקרים רבו מאד המה הנבראים המחודשים מאין ליש ממש שמתחדשים בכל יום ובכל עת ובכל שעה שמקורם הוא מל' דאצי', והיינו מפני שבקדושה נאמר בס\"י נעוץ<sup data-n=\"1049\">47</sup> תחלתן בסופן וסופן בתחלתן דייקא ולכך במלכות דאצי' שהיא סוף כל דרגין דאצי' נעוץ בה דוקא התחלה והראש לכל הנמצאים הוא בחי' הכת\"ר דאצי' הממוצע בין המאציל לנאצלי' שהיא בחי' תחתונה שבמאציל ושרש הנאצלי' ומאחר שיש בו מבחי' התחתונה שבמאציל שאין לו סוף ותכלה כלל ומאיר הארתו במל' דאצי' לכך נמצא הכח הגדול והיכולת בה לחדש חדשים אין קץ ואין מספר בתמידו' ממש משא\"כ בהשאר כו' כנודע ולכך נק' בחי' עפ\"ר דעביד איבין ופירין והוא כללא דלעילא ותתא פי' שהוא סוף כל דרגין דאצי' ובו נעץ התחלה והראש לכל הנאצלי' הארת הבי\"ע כנ\"ל וד\"ל.\n&lt;פט&gt;",[["1044","42","<b>קולה כנחש ילך</b>: ירמי' מו, כב."],["1045","43","<b>דזנבא שליט לעילא</b>: זח\"ג קיט, ב."],["1046","44","<b>אם תגביה כנשר</b>: עובדי' א, ד."],["1047","45","<b>ומעפר אשר בקרקע המשכן</b>: נשא ה, יז."],["1048","46","<b>הכל הי' מן העפר</b>: קהלת ג, כ."],["1049","47","<b>נעוץ תחלתן בסופן</b>: ס' יצירה פ\"א מ\"ז."]]],[2100490247,"אך זלע\"ז<sup data-n=\"1050\">48</sup> עשה האלקים דכמו שיש בקדושה בחי' מלכות דאצי' שהיא סוף כל דרגין דאצי' כך יש לעומת זה בקליפה וסט\"א בחי' נוק' דס\"מ שהיא סוף כל דרגין דלהון דקליפה והיא נק' בחי' אב\"ק ולא עפ\"ר בהיות בקדושה דוקא נעוץ תחלה וסוף להיות הארת הכת\"ר במל' לתת בה כח הא\"ס לחדש חדשים כנ\"ל אבל בקליפה אינו כן כ\"א הסוף כל דרגין דלהון הוא הסוף ממש שאין בו חיות עוד כלל והיינו אבק דאשתאר מן נור\"א דלא עביד איבין לעלמין פי' שהסוף שלהם נמשל לאפר הכירה נדמה שהאש שרף כל ג' היסודו' שבעץ שכלו ונשרפו ונסתלקו למקורם ונשאר רק בחי' יסוד העפר הוא האפ\"ר שאינו מצמיח כלל מצד שאין בו עוד חיות כלל שכבר נסתלקו ממנו כל הכוחות כנ\"ל, וכך ממש בחי' מל' דעשיה בקליפה נק' אב\"ק דאשתאר מן נורא דלא עביד אבין לעלמין כו' בהיות ידוע ששרש הקיום של החצונים הוא מבחי' הניצוצין דתה\"ו שנפלו דרך שבירה אליהם, אך מה שאפשר להתברר מהם ולהתכלל בסט' דקדושה של כל סדרי ההשתלשלות דאבי\"ע מתברר ונכלל בקדושה דהיינו שמה שאפשר להתכלל בטוב דאצי' מתברר באצי' והפסולת דאצי' נכללי' ומתבררים בבריאה בטוב שבו והפסולת דבריאה ביצירה ודיצירה בעשי' כו' כמ\"ש במ\"א עד שהסיגי' דעשי' מה שא\"א ליכלל בסוף כל דרגין דעשי' הוא בחי' מל' דקדושה דעשי' לבחי' טוב אזי נתפשט בעמקי הקליפות עד מל' דקליפה דעשי' שהוא סוף כל דרגין דלהון שנתמעט החיות במיעוט אחר מיעוט עד שבהסוף שלהם לא נשאר בחי' חיות דקדושה כלל וזאת ידוע שעיקר חיותם הוא מקדושה לכך נק' אב\"ק דאשתאר מן נורא שכבר כלו ונשרפו ונתבררו כל הכחות דקדושה ממנה (ונשארה כמצולה<sup data-n=\"1051\">49</sup> שאין בה דגים כו') שהוא הסוף והתכלית באמת שאין בה חיות כלל.\n<b>אך</b> הנה אם הי' מתברר ממנה החיות דקדושה לגמרי לא הי' לה קיום כלל כמו שיהי' לע\"ל בגמר כל הברורין שיבולע המות כו' ואת<sup data-n=\"1052\">50</sup> רוח הטומאה יעביר כו' כנ\"ל לזאת מוכרח להיות נשאר שמץ מנהו חיות דקדושה אף באב\"ק לצורך קיומו והיינו כמשארז\"ל בעפר המכסה הדם שמותר לכסות באפר מפני כשזורעים בו מצמיח והיינו שיש בו מעט חיות אף לאחר שנשרף באש ונסתלקו כל הכחו' שלו באופן שאם מזריעים בו יצמח כל שהוא ואינו בערך העפר שמצמיח כמה אילנות ודשאים בלתי זריעה כלל ועוד כשמזריעים בו יצמיח בהגדלה בתוספ' מרובה כהנה וכהנה מאה פעמי' וכו' משא\"כ האב\"ק כשיזרעו בו יצמח כ\"ש כנ\"ל והיינו מצד שנצרך להיות בו מעט חיות לצורך קיום החיצוני' משא\"כ לע\"ל כשיתברר הטוב והחיות דקדושה לגמרי אזי יבולע המות לנצח ואת רוח הטומאה יעביר וגו' וד\"ל.\n<b>וזהו</b> ויאב\"ק איש עמו שהיתה המלחמה בב' פנים הא' יעק\"ב עם האיש שהוא המלחמה בין ז\"א דקדושה לז\"א דקליפה והשנית בין נוק' דז\"א דקדושה לנוק' דז\"א דקליפה והיינו בין אב\"ק ועפ\"ר אך הנה סט' דקדושה &lt;צ&gt;\nנצח המלחמה בכל מכל",[["1050","48","<b>זלע\"ז עשה האלקים</b>: קהלת ז, יד."],["1051","49","<b>כמצולה שאין בה דגים</b>: פסחים קיט, א."],["1052","50","<b>ואת רוח הטומאה יעביר</b>: זכרי' יג, ב."]]],[2100490248,"כמ\"ש וירא כי לא יכול לו ומאחר שיעק\"ב נצח המלחמה בהאבק\"ו עמו שלא הי' יכול להמשכו אליו (אף לא מבחי' העפ\"ר אל האב\"ק להמשיך תוספ' חיים ממל' דקדושה דעשי' למל' דקליפה דעשי' כו') מוכרח להיות שיעקב העליהו אלי\"ו כי גם יעקב חבקו בזרעותיו וכיון שהוא ניצחו העלה עי\"ז את בחי' האבק למעלה מעלה דהיינו שבירר את בחי' הטוב שבאב\"ק והעלה אותו לשרשו הוא בחי' מל' דאצי' כי כל דבר כשמתברר חוזר לשרשו אם במל' או ביסוד כו' וכיון ששרשו של אב\"ק הוא בחי' מל' לכך חזר ונכלל הטוב שבו במל' דאצי' מקורו וזהו כונת הזוהר מלמד שהעלו אב\"ק עד כס\"א הכבו\"ד מקום המשפט היינו בחי' מל' דאצי' כנ\"ל ולכך אמר העלו לשון רבים מצד שהאב\"ק נתברר מהקליפה ע\"י יעקב דקדושה וזהו העלו שניהם האב\"ק עד כסא הכבוד כו' כנ\"ל וד\"ל, וה\"ז כמו עד\"מ בנפש האדם כשנופל לו איזה מחשבה זרה במוחו אזי העצה היעוצה להתחזק כנגדה בהעמקות הדעת בגדולת ה' ב\"ה ויוסף אומץ הלב בגבורות רשפי אש באהבה אליו ית' כי במקום<sup data-n=\"1053\">51</sup> שבע\"ת עומדין כו' מצד דמשכי לי' בחילא<sup data-n=\"1054\">52</sup> יתיר כו' וכמ\"ש בזוהר ע\"פ בכל<sup data-n=\"1055\">53</sup> לבבך בשני יצרך דא רזא כו' ע\"ש וזהו ענין התבררו' האב\"ק מקליפה להתכלל במקורו בקדושה וכנ\"ל וד\"ל.",[["1053","51","<b>במקום שבע\"ת עומדין</b>: ראה ברכות לד, ב."],["1054","52","<b>בחילא יתיר</b>: ראה זהר חיי שרה קכט, ב. אגה\"ת פ\"ח."],["1055","53","<b>בכל לבבך בשני יצרך דא רזא</b>: ואתחנן ו, ה. זח\"ב כו, ב. לקו\"ת ואתחנן ז, ד. וש\"נ."]]],[2100490249,"<h3>להבין מאמר הזהר פ' וישב ר\"ש פתח אך אל הפרוכת</h3>\n<b></b><b>בעז\"ה ליל שבת פ' וישב.</b>\nליל שבת פ' וישב\n<b>להבין</b><sup data-n=\"1056\">1</sup> מאמר הזהר פ' וישב (דקפ\"א ע\"א) ר\"ש פתח אך אל הפרוכת לא יבא כו' כי מום בו, ת\"ח בההיא שעתא דההוא נהר דנגיד ונפיק מן קדמוהי אפיק כל אינון נשמתין ואתעברת נוק' כולהו קיימין כו', וכד סיהרא אתפגים בההוא סט' דחויא בישא כדין כל אינון נשמתין דנפקין אע\"ג דכולהו דכיין וקדישין הואיל ונפקי בפגימו בכל אינון אתרי דמטו אינון נשמתין אתברו ואתפגמו בכמה צערין וכאבין",[["1056","1","<b>להבין מאמר הזהר כו' אך אל הפרוכת</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מהכת\"י 1156 פב, א. נמצא ג\"כ בכת\"י 33 עג, א. 68 ל, ב בכותרת: בעז\"ה ליל שבת פ' וישב (ובסופו רשום: מוגה מגוף כי\"ק אדמו\"ר נבג\"מ זי\"ע). 609 נד, א ובראשו רשום: בס\"ד פ' וישב יעקב כת\"י אדמ\"ו האמצעי נ\"ע [ר\"ל שנעתק מגוכי\"ק אדהאמ\"צ]. 1049 קכז, ב בכותרת הנ\"ל. בהכתבי-יד הנ\"ל נמצא אחר המאמר קיצורי והגהות אדהצ\"צ שנדפסו בביאוה\"ז (הנסמן להלן).\nהנחת ר' משה בן אדה\"ז נדפס לקמן ע' קפט.\n(נוסח ג' נמצא בכת\"י 633 ריב, ב (ועוד) ומתחיל: לה\"ע מיעוט הלבנה. ונוסח ד' נמצא בכת\"י 412 קעח, ב).\nקיצורים והגהות למאמר זה נדפסו בביאוה\"ז להצ\"צ ע' קלה ואילך. קיצור נוסף נמצא בכת\"י 21 מג, א (ויודפס בעז\"ה בהוספות לביאוה\"ז להצ\"צ). תוכן המאמר נמצא ג\"כ בדרמ\"צ מצות איסור עבודת בע\"מ (לא, א ואילך).\nמאמר זה נזכר ג\"כ ברשימת אדהצ\"צ (נד' באוה\"ת על מארז\"ל וענינים ע' שלד) ד\"ה: ענין קידוש הלבנה המקומות המדברים מזה.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז על מארז\"ל ש\"ס זוהר ותפלה ע' רטו."]]],[2100490250,"כו' רזא דמלה שריין כגוונא דלעילא גופא אתפגים ונשמתא לגו כגוונא דלעילא ובג\"כ אלין אינון דבעיין לאתחדתא בחדתותי דסיהרא ועליהם אמר והי' מדי חדש כו' יבא כל בשר ודאי ואינון בשיתופי חדא בסיהרא פגימין בההוא פגימו דילה ובג\"כ איהי שרייא בגווייהו תדיר כד\"א ואת דכא ושפל רוח כו' להחיות לב נדכאים, עכ\"ד המאמר בקצרה.\n<b>והנה</b> כדי להבין מאמר זה תחלה י\"ל מהו ענין מולד הלבנה ומיעוטה ומילואה בכל חדש כו'. וילה\"ק תחלה ענין מ\"נ ומ\"ד הנז' בכ\"מ. בהיות ידוע ענין התהו והתיקון שבחי' עגולים דתהו יצא האור בבחי' נפש לבד והוא בחי' מל' כמו מל' דחכ' מל' דבינה כו' וע\"כ יצאו האורות דתהו זת\"ז דהיינו מפורדי' כמ\"ש וימלוך<sup data-n=\"1057\">2</sup> תחתיו כו'. וביאור הדברים הנה בחי' מל' ידוע ענינו שהוא בחי' ההתגלות של כל איזה מציאות ומהות דבר מה וע\"כ בחי' ההתגלות בכלל וכל ההשתלשלות נק' בשם בחי' מל' כידוע, ובד\"פ בחי' הגילוי של כל מציאות פרטי נק' בשם מל'. וע\"כ מצינו כמה שמות לבחי' מל' דאצי' דלפעמים נק' בשם עפר או אבן ולפעמים בשם אתרוג או שושנה ולפעמים בשם קול או דבור או כח וכיוצא. וזהו מפני שיש בכלל ד' מדרגות ארמ\"ע<sup data-n=\"1058\">3</sup> והן ד\"י גשמיי' לנגד ד' עולמות אבי\"ע ובפרט הם דצח\"מ שבכל עולם ועולם ובכל בחי' מד' חלקים הללו יש בחי' המל' וכמו בחלק הדומם בחי' המל' הוא עפר או אבן דוקא ולא מתכת וכיוצא, והטעם מבואר בפרד\"ס בשער המציאות ע\"ש, ובחלק הצומח בחי' המל' הוא אתרוג או שושנה דוקא וכיוצא ובחלק החי בהמה דוקא ובחלק המדבר בחי' דבור או קול וכיוצא והכלל הוא רק מפני שכל אלה הוא בחי' ההתגלות שבכל חלק מד' חלקים דדצח\"מ וארמ\"ע כו'. ומזה יובן בדוגמא גם למעלה מעלה והיינו בבחי' ענין ז' מלכים דתהו דכתי' בהו וימלוך תחתיו וימת כו' דהענין הוא בחי' ההתגלות מה שנראה ליש וניכר לדבר מה מורגש במציאות כו'.\n<b>וביאור</b> הדבר יובן ע\"ד דוגמא ממה שאנו רואים למטה באיש חכם כשנראה וניכרת חכמתו ליש ודבר מה היינו כשמרגיש ויודע היטב איך שהוא חכם ביותר שהרגשה זאת שמרגיש בחכמתו הוא בחי' היש והגילוי יתירה מאמיתי' מהות חכמתו ועליו אמר ראית<sup data-n=\"1059\">4</sup> איש חכם בעיניו תקוה לכסיל ממנו שהכסיל טוב הימנו או שיש תקוה ויניקה לכסיל ממנו, כי בחי' השרש יניקה לסכלות הוא בא מסיבת הרגשת החכ' בבחי' יש ודבר מאד והוא כשהאיש החכם בעיניו כו', משא\"כ כשאינו מרגיש כלל מחכמתו וא\"י ממנה כ\"כ עד שתהא נחשבת בעיניו לדבר מה אזי אין בחי' יש בחכמתו שיוכל להסתעף ממנו הסכלות לכסיל כו'. וכך הדוגמא למעלה בע\"ס דתהו כמו בחי' מל' שבחכ' לפי שניכר ונגלה אור החכ' מן המאציל בבחי' יש ודבר מה כו' ע\"כ נאמר וימלוך וימת שנפל בבחי' מיתה ושבירה למטה להיות מסתעף מזה בחי' נפרד ויש גמור הנק' כסיל העליון והוא בחי' נוגה דבי\"ע כידוע וד\"ל. וע\"כ יצאו האורות דתהו בבחי' פירוד זת\"ז כמ\"ש וימלוך תחתיו כו' והוא ג\"כ מזה הטעם לפי",[["1057","2","<b>וימלוך תחתיו</b>: וישלח לו, לג."],["1058","3","<b>ארמ\"ע. . ד' עולמות אבי\"ע</b>: ראה סידור שחרית לג, א. לקו\"ת פינחס עה, ד."],["1059","4","<b>ראית איש חכם בעיניו</b>: משלי כו, יב."]]],[2100490251,"שענין המלוכה הוא בחי' הגילוי ליש מאד וע\"כ כ\"א יוצא לדבר ויש בפ\"ע ואין לו חיבור עם זולתו כי כל בחי' יש ודבר לא יתאחד מפני שענין האחדות באה דוקא מבחי' הביטול מן ההרגש כו'. וד\"כ מכל בחי' המלכיות דתהו בירידתן למטה נעשה ג\"כ ריבוי בחי' החשבון והמספר וכמ\"ש עיניך<sup data-n=\"1060\">5</sup> ברכות בחשבון דידוע שהוא בבחי' המל' שנק' חשבון כי נמצאו בה בחי' ההתגלות לכמה רבבות אופנים שונים עד שיתכן לומר במדה זו שכוללת כמה מספר בחי' שמות עליונים וכמ\"ש לכו<sup data-n=\"1061\">6</sup> חזו מפעלות אלקים אשר שם שמות בארץ א\"ת שמות כו' ולכך נק' חשבון, וכתיב ומשם<sup data-n=\"1062\">7</sup> יפרד וכו' משם דוקא והיינו בחי' היכלות דנוגה שהן נפרדי' לגמרי כידוע וד\"ל. והנה בחי' התיקון הוא להיות הפך בחי' הגילוי ליש ודבר כו' אלא אדרבה יהי' בחי' הביטול של היש והגילוי הנ\"ל. וביאור ענינו יובן ע\"ד מה שאנו רואים למטה במ\"ש הולך<sup data-n=\"1063\">8</sup> את חכמים יחכם כו' שהענין הוא דגם מי שאינו חכם בעצם אלא שהולך תמיד אחר חכמים ושומע תדיר דברי חכ' שמדברים גם הוא יחכם וחכם יקרא גם הוא. ולכאורה האיך יקרא חכם מאחר שאינו חכם בעצם ואע\"פ ששמע והלך אחר חכמי' מ\"מ בודאי אין לו ערוך ויחוס עמהם כלל כמו שאין ערוך לתלמיד עם הרב גם באותו שפע אור השכל שהשפיע לו כידוע. אלא הענין הוא דאע\"פ שאינו דומה לחכמים באמת להיות כמוהם ממש מ\"מ מפני הליכתו בתמידות אחריהם גם בו נמשך קצת הארת החכ' מן החכמים. ויובן דוגמת זה למעלה בענין התיקון שהענין הוא כך שאע\"פ שהע\"ס דתהו נתגלו לבחי' יש ודבר מה מ\"מ ע\"י ההארה מבחי' שם מ\"ה דחכ' דהיינו מבחי' שם מ\"ה המאיר במצחא דא\"ק כו' בא בהן בחי' הביטול במציאות להיות בבחי' אין דמ\"ה דחכ' ע\"ד הולך את חכמים יחכם גם הוא כנ\"ל דאע\"פ שלא יוכלו להיות בבחי' מ\"ה ממש באור שם מ\"ה המאיר כו' מ\"מ אפס קצהו מתקבל בהם ונעשי' גם הם בבחי' הביטול דאין שהוא הפך בחי' היש והגילוי הנ\"ל. וז\"ע השם מ\"ה שמברר ב\"ן דתהו כי כל זמ\"ל דתהו הוא בשם ב\"ן כמ\"ש וימלוך וכל מלוכה בבחי' שם ב\"ן הוא, ומלך הח' הוא מלך<sup data-n=\"1064\">9</sup> הדר ושם אשתו מהטבאל בת מטרד כו' שהוא שם מ\"ה החדש הנ\"ל שמברר אותם ומתקן אותם כנ\"ל וד\"ל.\n<b>ולהבין</b> איכות אופן התיקון הזה בתוס' ביאור יובן ממה שאנו רואים בדוגמא זאת למטה בנבראי' ומתוכו נבין בנאצלים כו'. כי הנה כתיב המשל<sup data-n=\"1065\">10</sup> ופחד עמו עושה שלום במרומיו וידוע שהן מיכאל<sup data-n=\"1066\">11</sup> וגבריאל למעלה שהן שר של מים ושר של אש למטה ואין מכבין זא\"ז כו' והוא משום דהמשל ופחד עמו. וביאור זה ידוע לפי שהארה אלקית מתחלת הבריאה מצומצמת היא מאד בכל חד לפום שע\"ד בלבד ע\"פ",[["1060","5","<b>עיניך ברכות בחשבון</b>: שה\"ש ז, ה."],["1061","6","<b>לכו חזו. . שמות בארץ א\"ת שמות</b>: תהלים מו, ט. ברכות ז, ב. תו\"א מג\"א צו, א."],["1062","7","<b>ומשם יפרד</b>: בראשית ב, יוד."],["1063","8","<b>הולך את חכמים יחכם</b>: משלי יג, כ."],["1064","9","<b>מלך הדר ושם אשתו מהטבאל</b>: וישלח לו, לט."],["1065","10","<b>המשל ופחד עמו עושה שלום במרומיו</b>: איוב כה, ב."],["1066","11","<b>מיכאל וגבריאל. . שר של מים ושר של אש</b>: ראה במדבר רבא פי\"ב, ח. תנחומא ויגש ו. וראה מאמרי אדה\"ז פרשיות התורה ח\"ב ע' תרמה ובהנסמן שם."]]],[2100490252,"בחי' קו המדה כו' וכשניתוסף ההארה האלקי' עליהם יתר מכפי המדה הראשונה אזי ממילא המה מתבטלים ממציאותם הראשון לגמרי ולא יתכן אז כלל לומר בהם שהם ב' הפכיי' אש ומים כי אבדו עיקר מציאותם מפני שנכללו כמו הנר בפני האבוקה כו'. וזהו המשל ופחד עמו דהיינו מפני שמתגלה בחי' גילוי אור ביותר לכך נמצא הפחד ביותר כידוע ואז ממילא עושה השלום כו' שאין מכבין זא\"ז כו'. וכך יובן הדוגמא למעלה בבחי' הנאצלים מן המאציל דגם הם נאצלו בבחי' ג' קוין חח\"נ מימין ובג\"ה משמאל כו' וכידוע. וה\"ז ממש כדוגמת מיכאל וגבריאל למטה בנבראי' וגם שם הוא האור השופע ע\"י צמצום דקו כו'. וכאשר נתוסף איזה הארה מעצמות המאציל על הע\"ס דאצי' על היות שהוא מרומם ומובדל בערך מהם ע\"כ בא בהם בחי' הביטול וההתכללות בתכלית כנר בפני אבוקה כנ\"ל מפני שהעלול בטל בעילתו, ואז ג\"כ אינם מפורדים זמ\"ז זת\"ז כנ\"ל אלא מתייחדים ומתכללי' זב\"ז והיו לאחדים והיינו בחי' התיקון דנעשה ע\"י הארת שם מ\"ה שעי\"ז מתכללי' כל האורות זב\"ז היפך בחי' הפירוד דתהו. וזהו מ\"ש יקוו<sup data-n=\"1067\">12</sup> המים כו' מים דתהו יהיו בבחי' קוין דהיינו בבחי' חיבור הקוין והתכללותם מזה לזה כו' ומ\"מ אין בהם בחי' הביטול ממש אלא ע\"ד הנ\"ל בענין הולך אחר חכמים יחכם כו' דהיינו מה שגם בבחי' הפירוד שלהם בא בחי' הביטול דשם מ\"ה כו' וד\"ל.\n(ב) <b>אך</b> הנה עדיין י\"ל בבחי' התיקון הנ\"ל דבשלמא בבחי' אורות דאצי' יתכן להיות ביטול היש שלהם ע\"י שם מ\"ה דמלך הח' הדר כו' שיצא ממצחא דא\"ק לפי שבבחי' האצי' הרי הכל עדיין בבחי' אלקות ממש שהרי ידוע דבאצי' איהו<sup data-n=\"1068\">13</sup> וחיוהי וגרמוהי חד כו', אבל בנבראים ונוצרים כו' שהם נק' עולמות הנפרדים בבחי' גבול ממש ואינם בחי' אלקות כלל האיך יתכן שם בחי' התיקון הנ\"ל דהיינו עד שיוכללו להיות בבחי' אלקות ממש דזה א\"א שיהי' מבחי' נברא בחי' אלקות כו'. אמנם הענין יובן בהקדים עוד קושיא א' והיא קושיא חזקה ביותר ממה שאנו מוצאים בזהר<sup data-n=\"1069\">14</sup> וע\"ח בכמה דוכתי דמל' דאצי' הוא בחי' שם ב\"ן שיורד לברר בירורים דרפ\"ח בבי\"ע למטה וכמ\"ש ותקם<sup data-n=\"1070\">15</sup> בעוד לילה ותתן טר\"ף כו' וזה סותר למ\"ש בכמה דוכתי דעיקר הבירור הוא דוקא בשם מ\"ה דחכ' כמאמר הידוע דבחכ'<sup data-n=\"1071\">16</sup> דוקא אתברירו וגם בע\"ח תמיד מוזכר דעיקר הבירור הוא במ\"ד דדכורא. והנה התי' לזאת הקושיא דאינם תרתי דסתרי אהדדי כלל דשניהם אמת מפני שיש ב' מיני בירורים הא' בירור שלמטה שבבחי' שם ב\"ן והוא בבחי' מ\"נ והבירור השני הוא הבירור שאח\"כ יתברר עוד פ\"ש והוא הבירור שע\"י מ\"ה דחכ' והוא בבחי' מ\"ד כו' וה\"ז כמשל המ\"ד גשמי למטה שמברר מ\"ן גשמי עד שממנו נוצר הולד דוקא כי האודם שמן האשה לא הי' הולד נוצר ממנו כלל אלא ע\"י בירור שמברר המ\"ד במ\"נ נוצר בברור שבו כו' וכידוע פרטי הענין בספרי הרפואה.",[["1067","12","<b>יקוו המים</b>: בראשית א, ט."],["1068","13","<b>איהו וחיוהי וגרמוהי חד</b>: ראה ת\"ז ג, ב."],["1069","14","<b>וע\"ח. . דמל' דאצי'. . בירורים דרפ\"ח</b>: ראה ע\"ח (שער רפ\"ח) שי\"ח, פ\"ב.\nוראה פרי עץ חיים שער (טז) ק\"ש שעל המטה פ\"ה ומקבילו בשער הכוונות ענין דרושי הלילה דרוש ז."],["1070","15","<b>ותקם בעוד לילה</b>: משלי לא, טו."],["1071","16","<b>דבחכמה דוקא אתברירו</b>: ראה זהר (היכלות) פקודי רנד, סע\"ב."]]],[2100490253,"<b>אך</b> להבין זה למעלה יובן בהקדים לזה ענין אחר שהוא כדוגמא של ענין זה בב' הבירורים הנ\"ל במ\"ן ומ\"ד. דהנה בבחי' הביטול דמ\"ה דחכ' כו' יש בה כמה רבבות מדרגות זו למעלה מזו וד\"כ יש בה ב' מדרגות לבד ואותן ב' מדרגות נבין מב' נשמות גבוהות שכבר היו לעולמים והן משה ואלי', בהיות ידוע דמשה<sup data-n=\"1072\">17</sup> ואלי' שניהם היו בבחי' הביטול במציאות כידוע ועכ\"ז יש הפרש ביניהם ולא ראי זה כראי זה כו'. דהנה אלי' הי' מלאך ממש גם בהיותו בגוף גשמי שהרי הי' טס באויר ממדינה למדינה כמ\"ש ורוח<sup data-n=\"1073\">18</sup> ה' ישאך כו', וכמו שידוע ומבואר ג\"כ בכתוב דבמעט רגע הי' בצרפתה ובמעט רגע רוח ה' נשאו למק\"א וה\"ז כמו בחי' מלאך ממש שהמלאך טס באויר העולם כולו ברגע קטן כידוע המאמר מיכאל<sup data-n=\"1074\">19</sup> בא' כו', ואלי' בד' והיינו בד' פריחות לפי שהי' טס בבחי' שם י\"ב והיינו בד' כמבואר בסה\"ק. והנה גם לבושיו של אלי' היו מורין שלא הי' גופו חומרי כשאר בני האדם כי הי' משונה בלבושיו מכל שאר בנה\"א והוא במה שהי' מלובש באדרת ואזור<sup data-n=\"1075\">20</sup> עור במתניו כו' ובזה הי' מובדל מכל בנה\"א גם במראי' העין וכ\"ז להורות על עוצם הזדככות גופו עד שפרח וטס באויר כו'. ועיקר הענין למעלה ומדרגה כזו שיהי' גוף חומרי פורח וטס באויר כו' הוא לפי שהי' בו בחי' הביטול במציאות בתכלית ולא הי' תופס מקום כלל וכלל כו'. אך עכ\"ז י\"ל הלא הי' כמה צדיקי' גדולים ממנו כמו האבות<sup data-n=\"1076\">21</sup> שהן המרכבה כידוע וכמו משה ואהרן וכיוצא ואעפ\"כ לא הי' גופם פורח באויר כו'. וביותר תמוה ממה שמצינו במשה שהי' בו בחי' הביטול במציאות ביותר וכמ\"ש ונחנו<sup data-n=\"1077\">22</sup> מ\"ה ואעפ\"כ לא הי' גופו פורח וטס באויר ולא עלה בגופו<sup data-n=\"1078\">23</sup> השמים כאלי' אלא נקבר בקבר כידוע. אך הענין הוא דהנה יותר יפלא מזה במה שמצינו באלי' שהי' שליח בכ\"מ גם לצדיקים שנמוכים הרבה במדרגה, וגם ברשב\"י<sup data-n=\"1079\">24</sup> שאע\"פ שהי' שרש נשמתו גבוה מאד ואעפ\"כ א' על פומא דאלי' אתגזר כו'. ומ\"מ הרי אמ\"ל אלי' מילך אתחתקן לעילא ומילי אתחתקן לתתא וא\"כ הי' אלי' נמוך ממנו. אמנם עיקר ושרש הענין הוא כך כי הנה ידוע דבכ\"מ יש בחי'<sup data-n=\"1080\">25</sup> פנימי' ובחי' חיצוני' וזה נק' בחי' מ\"ה וב\"ן. והנה משה ונחנו מ\"ה היינו לפי שהי' מבחי' פנימי' דהיינו מבחי' מ\"ה דחכ' כמו שהוא בעצם וע\"כ הי' בו בחי' הביטול בבחי' פנימי' ביותר הרבה מאלי' וע\"כ הי' כבד<sup data-n=\"1081\">26</sup> פה וכבד לשון שלא הי' יכול לבוא לבחי' גילוי יש ודבר מה בדבור וכיוצא והוא להיותו בבחי' אין כמו שהוא מבלתי יוכל לירד ולהתלבש בלבוש חיצוני כלל להיות נגלה ליש ודבר מה כו'. אבל אלי'<sup data-n=\"1082\">27</sup> הי' ג\"כ מבחי' הביטול דשם מ\"ה",[["1072","17","<b>דמשה ואלי'. . הביטול במציאות</b>: ראה ג\"כ מאמרי אדה\"א דברים ח\"ב ע' תקנד, וש\"נ. נר מצוה ותורה אור (שער האמונה) ק, ב."],["1073","18","<b>ורוח ה' ישאך</b>: מלכים-א יח, יב."],["1074","19","<b>מיכאל בא'</b>: ראה ברכות ד, ב."],["1075","20","<b>ואזור עור במתניו</b>: ראה מלכים-ב א, ח."],["1076","21","<b>האבות שהן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב ו. ראה סדור שער נפ\"א צב, ד."],["1077","22","<b>ונחנו מה</b>: בשלח טז, ז-ח."],["1078","23","<b>בגופו השמים כאלי'</b>: ראה מלכים-ב ב, יא. פרדס שער (כד) היכלות פי\"ג-ד."],["1079","24","<b>ברשב\"י. . שרש נשמתו גבוה מאד</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפז. תורת חיים ויצא קעח, ג. ובכ\"מ."],["1080","25","<b>בחי' פנימי' ובחי' חיצוני'</b>: ראה ג\"כ תו\"א מקץ לד, ג."],["1081","26","<b>כבד פה</b>: שמות ד, י."],["1082","27","<b>אלי'. . ב\"ן דמ\"ה</b>: ראה פע\"ח (שער הק\"ש) ש\"ח פ\"ח. וראה תורת חיים ויצא קעח, ג ובהערה 33."]]],[2100490254,"דחכ' אך לא מבחי' הפנימי' אלא דוקא מבחי' החיצוני' דהיינו ב\"ן דמ\"ה. והענין הוא שהי' בחי' אין שלו נמשך למטה בבחי' חיצוני' הנגלה ליש שיהא גם הוא בבחי' אין וע\"כ הי' גם גופו טס באויר מפני שהי' יכול להמשיך בחי' מ\"ה ואין גם בבחי' יש הנפרד שיהא גם הוא בטל במציאות ויהי' בו ג\"כ בחי' אין. ובזאת המדרגה להמשיך בחי' אין ביש ג\"כ הי' אלי' נבדל במעלה זו גם ממשה והאבות וכיוצא לפי שבבחי' היש המשיך בחי' אין דמ\"ה יותר מכולם וע\"כ בעודו בגופו הי' כמלאך ממש. משא\"כ משה שלא הי' בגופו בחי' אין כ\"כ ע\"כ הוצרך ליקבר בקבר אע\"פ שמצד נשמתו הי' בבחי' הביטול בבחי' פנימי הרבה יותר מאלי' כנ\"ל. אך ורק כשהי' משה בהר מ' יום לחם<sup data-n=\"1083\">28</sup> לא אכל כו' אזי הי' גם בגופו מבחי' אלי' והוא כמו בחי' מלאכים העליונים ממש. אבל מלבד אותן המ' יום לא הי' בגופו בחי' הביטול כ\"כ כמו באלי' מטעם הנ\"ל ששרש אלי' הוא מבחי' המ\"ה שבחיצוני' דוקא. והוא הטעם עצמו שהי' אלי' בחי' שליח בכ\"מ וכמ\"ש לרשב\"י מילך אתחקק לעילא ומילי אתחקק לתתא משום דהי' נמשך ומתלבש למטה מטה דוקא כמו מלאכים העליונים שנתלבשו למטה מטה גם במראה גוף גשמי לאברהם וכמ\"ש והנה<sup data-n=\"1084\">29</sup> שלשה אנשים כו' וע\"כ הי' לבושי' של אלי' באדרת ואזור עור כו' לעוצם בחי' הביטול שנמצא בגופו דוקא וד\"ל. וע\"פ דוגמא זאת יובן למעלה בכללו' ענין מ\"ה וב\"ן שהם ב' מיני בירורים הנ\"ל דמ\"ן ומ\"ד כו'. דהנה ע\"ד הדוגמא באלי' שהי' רק ביטול היש החיצוני' בגוף כנ\"ל זהו משל להבין ענין בחי' הבירור דמ\"ן דנוק' שמבררת בבי\"ע והוא להיות בחי' ביטול האין דאלקות נמצא בבחי' יש נפרד שהן הנבראים והנוצרים כו' ויהיו גם הם נכללים בבחי' אין דאלקי' חיים ומלך עולם הוא בחי' מל' דאצי' והיינו שם ב\"ן שיורד בבי\"ע לברר בירורים כנ\"ל<sup data-n=\"e28\">*</sup>. ואמנם עדיין אין נכללי' באלקות ממש להיות מהותם ממש כמהות אור האלקי כי האיך אפשר שיהי' מהות נברא יש נפרד בחי' אין ממש דאלקות אלא הענין הוא ע\"ד דוגמ' מבחי' האין שהמשיך אלי' בגופו שהי' רק הארת אין מתלבשת בחיצוני' ולא שהי' גופו ממש בבחי' האין כמו שהוא כנ\"ל וכמ\"כ ענין ביטול של המלאכי' למעלה כשמתבררי' ומתבטלים והיינו במה שמקבלים עליהם עומ\"ש באימה ופחד גדול מפני גילוי שכינה שביראה ופחד מתבטלים מבחי' היש הנפרד בלבד אבל עדיין לא נכללו ממש באין דאלקי' חיים כו'. וזהו ומשמיעים ביראה דא\"ח כו' אלא אחר שנמצא בהם ביטול זה בחיצוני' שלהם אזי מתבררים עוד בירור השני והוא בחי' הבירור דמ\"ה והיינו שיוכלו להיות נכללים באלקות ממש להיות עצם א' ומהות א' כו'. וזה א\"א כ\"א ע\"י בירור הראשון דמ\"נ תחלה להיות מציאת הביטול בהם בבחי' החיצוני' עכ\"פ וא\"ל איך יהיו נכללים באלקות מאחר",[["1083","28","<b>לחם לא אכל</b>: תשא לד, כח."],["1084","29","<b>והנה שלשה אנשים</b>: וירא יח, ב."],["e28","*","<b>כנ\"ל</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ: כי כדי להגיע בחי' הביטול ולהמשיכו למטה מטה בבחי' נוגה אינו אלא ע\"י בחי' שם ב\"ן שבו וע\"י הוא המשכת הביטול בחיצוני' ע\"ד מציאת הגעת והמשכת הביטול בגופו של אלי' שהוא לפי ששרשו משם ב\"ן דוקא."]]],[2100490255,"שאין ערוך כלל נברא עם הבורא ית' כו'. ובירור זה השני היינו בירור המ\"ד שמברר המ\"ן וה\"ע בירור אחר בירור כו'. והיינו כדוגמ' שהי' במשה בחי' הביטול דאין דמ\"ה כמו שהוא ממש והיינו בבחי' פנימי' דמ\"ה כמ\"ש ונחנו מ\"ה מ\"ה ממש כנ\"ל ובו יאיר אוא\"ס כמו שהוא מבלתי התלבשות וצמצומי' כידוע הכלל שאין<sup data-n=\"1085\">30</sup> אוא\"ס שורה אלא בחכ' דוקא וע\"כ שכינה<sup data-n=\"1086\">31</sup> הי' מדברת מתוך גרונו של משה כו'. וכך יובן הדוגמא למעלה דהיינו מ\"ש בכמה דוכתי טובא דשם מ\"ה דחכ' הוא המברר דוקא והוא בחי' מלך<sup data-n=\"1087\">32</sup> הח' הנק' הדר דשרשו נמשך ממצחא<sup data-n=\"1088\">33</sup> דא\"ק והוא דוקא בבחי' האצי' להיות כי שם אין דבר נפרד כמא' דאיהו וחיוהי וגרמוהי חד כו'. אך אין בירור זה דמ\"ד אלא אחר בירור הראשון דמ\"נ שבבי\"ע תחלה מטעם הנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יתורץ גם הקושיא הנ\"ל וגם איך יתכן בנברא שיוכלל באלקות ממש, דבאמת א\"א זה כ\"א ע\"י שיהי' בהם בחי' הבירור בבחי' חיצוני' משם ב\"ן תחלה כנ\"ל ואח\"כ הם באים לידי בירור השני והוא בבחי' המ\"ד דאצי' ושם נכללים באלקות ממש כנ\"ל וד\"ל. ובזה יובן משרז\"ל מיכאל<sup data-n=\"1089\">34</sup> מקריב נשמות ע\"ג המזבח כו' דהיינו ב' מיני בירורים הנ\"ל הא' עליי' הנשמות בהקריב אותן במזבח והוא בחי' ביטול היש בלבד במל' דאצי' הנק' מזבח ואח\"כ עולין עוד לאחר ההקרבה ע\"ג המזבח שיורד אש שלמעלה ואוכל אותן כדוגמא של אש שלמעלה שירד ע\"ג המזבח שלמטה<sup data-n=\"1090\">35</sup> והיינו מ\"ש בזהר לאשתאבא<sup data-n=\"1091\">36</sup> בגופא דמלכא וכמ\"ש במ\"א שהוא בחי' ההתכללות ממש בבחי' האצי'. ומ\"ש עוד בזהר<sup data-n=\"1092\">37</sup> ע\"פ מצמיח חציר לבהמה דאלף טורין דשתת לון בגמיעה חדא כו' היינו בבחי' שם ב\"ן שנק' בהמה והוא בחי' בירור הראשון דמ\"נ כנ\"ל. ומ\"ש מיכאל מקריב נשמות ע\"ג המזבח כנ\"ל וכן ענין המאמר הושיט<sup data-n=\"1093\">38</sup> אצבעו הקטנה ביניהם ושרפם הו\"ע בירור השני דבחי' מ\"ד כנ\"ל (ויש עוד מדרגה ג' והוא הארת והמשכת מ\"ד ליתן כח למטה להיות העלאת מ\"נ וזה מבואר במ\"א). ועם הנ\"ל יובן עוד דמ\"ש במד\"ר<sup data-n=\"1094\">39</sup> ע\"פ והאיש משה עניו מאד יכול ממלאכי השרת ת\"ל מכל אדם דהגם שמשה מצד נשמתו הי' מבחי' מ\"ה עצמו כמו שהוא כנ\"ל, אבל מפני שבגופו לא הי' הארת בחי' המ\"ה כמו באלי' שהי' מלאך כנ\"ל ע\"כ מצד בחי' זו דהיינו הארת האין בכלי דוקא בזאת הי' מדרגת המלאכים נעלה ממדרגת משה בבחי' הענוה שהוא בחי' הביטול דשם מ\"ה כידוע, וזהו יכול ממה\"ש ת\"ל מכל אדם כו' וד\"ל.",[["1085","30","<b>שאין אוא\"ס שורה אלא בחכמה דוקא</b>: ראה תניא פי\"ח. פל\"ה בהג\"ה."],["1086","31","<b>שכינה הי' מדברת מתוך גרונו של משה</b>: נסמן לעיל ע' יג."],["1087","32","<b>מלך הח' הנק' הדר</b>: ראה וישלח לו, לט."],["1088","33","<b>ממצחא דא\"ק</b>: ראה ע\"ח שער התיקון פ\"ב-ד."],["1089","34","<b>מיכאל מקריב נשמות ע\"ג המזבח</b>: ראה חגיגה יב, ב. מנחות קי, א תוד\"ה ומיכאל."],["1090","35","<b>אש שלמעלה שירד ע\"ג המזבח שלמטה</b>: ראה תו\"כ ויקרא א, ז. עירובין סג, א."],["1091","36","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב."],["1092","37","<b>בזהר ע\"פ מצמיח חציר לבהמה</b>: תהלים קד, יד. זהר בראשית יח, ב. וראה סידור שחרית סב, ב."],["1093","38","<b>הושיט אצבעו הקטנה</b>: ראה סנהדרין לח, ב. וראה מאמרי אדה\"א ויקרא ח\"א ע' קסא, וש\"נ."],["1094","39","<b>במד\"ר ע\"פ והאיש משה עניו</b>: ראה ספרי בהעלותך יב, ג."]]],[2100490256,"(ג) <b>ובכל</b> הנ\"ל יובן ענין הלבנה במילואה ומיעוטה בכל חדש כו', דהנה ידוע בענין מיעוט הלבנה שהוא מפני שקטרגה<sup data-n=\"1095\">40</sup> ואמרה א\"א לב' מלכים כו' וא\"ל לכי<sup data-n=\"1096\">41</sup> ומעטי א\"ע. והנה אע\"פ שברשות ה' מיעטה א\"ע אעפ\"כ א' הקב\"ה הביאו עלי כפרה על שמיעטתי את הירח, בהיות ידוע בחי' הלבנה למעלה הוא בחי' מל' דאצי' כי שמש ולבנה ה\"ע מ\"ה וב\"ן למעלה וכידוע. וענין מיעוט הלבנה היינו מה שיורדת המל' בחי' שם ב\"ן למטה בבי\"ע עולמות הנפרדים להיות שם ראש לשועלים. ולהיות כי ירידה גדולה היא זאת להיות ראש לנבראים בע\"ג ותכלית ע\"כ א\"א שירד האור לצמצום גדול כזה כ\"א אחרי הסתר והעלם עצמו' המאור ולא תשאר באור רק כמו נקודה חדא קטנה מאד והוא מיעוט הלבנה שממנו נעשה בחי' ראש ומקור לנבראים, אבל מעצמות בחי' מל' דאצי' כמו שהיא בבחי' אצי' לא היו העולמות יכולים לקבל כלל אלא דוקא אחרי מיעוט אחר מיעוט ולא נשאר רק קו קטן זעיר בתכלית כו' והוא הנק' בחי' מל' שבמל' (ויש ב' אופנים הא' בבחי' חיצוני' שבמל' שאז בחי' מל' שבמל' יורד למטה ובחי' ט\"ס דבוקים למעלה בהעלם ואמנם בבחי' הפנימי' שבמל' נהפוך הוא שבחי' כתר שבמל' יורד וט\"ס עולין וזהו דרישא<sup data-n=\"1097\">42</sup> שכיבת לעפרא בגלותא כמ\"ש<sup data-n=\"1098\">43</sup> במ\"א ע\"פ קולה כנחש ילך). והנה מבואר למעלה בענין ב' הבירורים דמ\"נ ומ\"ד שבירור המ\"נ הוא תחלה ואח\"כ בא יבא המ\"ד לברר שנית כו'. וכך הוא בענין חידוש מולד הלבנה וכמ\"ש והי'<sup data-n=\"1099\">44</sup> מדי חדש בחדשו כו' שזהו התחלת בנין המל' ובתחלה נתעלמה ונתכסה אורה לגמרי ותחלת עלייתה מעולמות הנפרדים הוא ע\"י בחי' ביטול היש לאין שהוא בחי' בירור המ\"נ ואח\"כ עד חצי החדש מאיר בה אור השמש מעט מעט כו' היינו ענין בירור השני דמ\"ד דז\"א שנק' שמש והוא בחי' שם מ\"ה כידוע וכנ\"ל והוא מלוי הלבנה וע\"כ מביאים קרבן בר\"ח שהוא תחלת מולד<sup data-n=\"1100\">45</sup> הלבנה בבחי' נקודה בלבד והקרבן הוא קרבן מוסף ר\"ח ונק' עולה ריח ניחוח לה' כו' מפני שאז עולין מ\"נ דנוק' בשלימות הבירור ואח\"כ יוכל לשכון אור המדות על המ\"נ והוא ריח ניחוח כו' וכן חוזר חלילה שהלבנה חוזרת וממעטת א\"ע עד שבכל חדש יש ריחוק וקירוב כידוע כי אין יחוד מ\"ה וב\"ן אלא מדי חדש בחדשו וכמ\"ש והי' מדי חדש בחדשו יבא כל בשר כו' וד\"ל. ובזה יובן תחלה כללות ענין המאמר הנ\"ל בזהר באמרו בשעתא דההוא נהר דנגיד ונפיק כו' ואתעברת נוק' כו' דההוא נהר הוא בחי' מ\"ד דז\"א שמתייחד עם מ\"ן דנוק' בכל חדש כנ\"ל.",[["1095","40","<b>שקטרגה. . לב' מלכים</b>: ראה פרש\"י בראשית א, טז. חולין ס, ב."],["1096","41","<b>לכי ומעטי א\"ע</b>: חולין ס, ב. ראה גם שעה\"י קמב, א ובהערה 24. ביאוה\"ז לאדה\"א עח, א. אוה\"ת בראשית לח, א-ב. פינחס ע' א'קעב ואילך. נתבאר בארוכה בלקו\"ש ח\"ל ע' 8 ואילך."],["1097","42","<b>דרישא שכיבת לעפרא</b>: ראה זהר במדבר קיט, ב. ע\"ח (שער מיעוט הירח) של\"ו, פ\"ב. וראה מאמרי אדה\"ז אתהלך ע' קמו. אמרי בינה שער הק\"ש ספצ\"ג. דרך חיים מו, ד."],["1098","43","<b>כמ\"ש במ\"א ע\"פ קולה כנחש ילך</b>: ירמי' מו, כב. וראה פירוש המילות נח, א. תו\"ח שמות מב, א."],["1099","44","<b>והי' מדי חדש</b>: ישעי' סו, כג."],["1100","45","<b>מולד הלבנה בבחי' נקודה</b>: ראה תו\"א קט, ב. סידור עם דא\"ח שחרית לשבת קפב, ד ואילך. סה\"מ תקס\"ז ס\"ע קנ ואילך. דרך מצותיך לא, א. אוה\"ת יתרו ע' תשצה."]]],[2100490257,"(ד) <b>אך</b> הנה תוכן ענין כוונת המאמר ובפרט מ\"ש כד סיהרא אתפגים כדין כל אינון נשמתין דנפקין נפקין בפגימו כו' עד רזא דמלה גופא אתפגים ונשמתא לגו כגוונא דלעילא כו', להבין זה הענין בכלל צריך תחלה להקדים מהו ענין פגימת הלבנה עם מה שארז\"ל הביאו עלי כפרה על שמיעטתי את הירח. דהנה ידוע בסדד ההשתלשלות היכלות החיצוני' מאחר דאת<sup data-n=\"1101\">46</sup> זלעו\"ז עשה האלקי' הרי יש גם בהם רבבות מדרגות זו למעלה מזו, וד\"כ הן הנה ד' עולמות ג\"כ בדוגמת הקדושה והוא קליפה דאצי' וקליפה דבריאה ודיצי' ועשי'. והנה ביאור ענין קליפה דעשיי' היינו השרים של האומות עוכומ\"ז, והשר מתלבש ממש באומה ומלוכה לעשות בהם כרצונו וכמו בשר של מצרים דכתי' ויאמר<sup data-n=\"1102\">47</sup> אל עמו ולא כתיב מי הוא שאמר לעמו אלא הוא שר של אומת מצרים ומה שנא' ויאמר אל עמו מבואר דאעיל מחשבתי' בלבייהו כי כל כחות ההשפעה במחדו\"מ ושכל ומדות וכה\"ג באומה ומלכה הוא נמשך ובא מכח הרוחני הוא בחי' השר דאותה אומה וכל גזירות מלך הכל מן השר דאעיל מחשבתי' בלבייהו לעשות כך או כך ואותו השר הוא בחי' מלאך נברא ומעורב טו\"ר להיותו מבחי' סיגים ופסולת דמל' דעשיי' דקדושה ובכל סיג ופסולת מעורב טו\"ר, וענין הטוב שבו הוא רק בידיעה שיודע את רבונו וקרא לי' אלקא<sup data-n=\"1103\">48</sup> דאלקייא בלבד, אבל בחי' הביטול רצון אין לו ויכול לעשות נגד רצון ה' כמו לשעבד ישראל ולעשות עצמו ע\"ז וכיוצא, וכמ\"ש<sup data-n=\"1104\">49</sup> בתיקוני' שגוערי' בס\"מ שאין לו בושת משכינה וקוב\"ה דבראשי' ירא בושת והוא אין לו בושת דמשמע שמורד הוא לעשות עצמו יש ודבר כע\"ז ממש עד שיוכל לומר לי<sup data-n=\"1105\">50</sup> יאורי וכיוצא. וזהו בחי' קליפה דעשיי' שהוא נגד מל' דמל' די\"ס דעשיי', והיינו ג\"כ הנק' יראה רעה ומקבלת מפסולת יראה דקדושה שהוא קעומ\"ש בקדושה והוא בחי' מל' דעשי'. והנה זאת הקליפה נק' אשת<sup data-n=\"1106\">51</sup> זנונים וכמה שמות הנז' בזהר כמו לילית<sup data-n=\"1107\">52</sup> ואגרת כו' והוא בחי' נוק' דס\"מ דעשיי' והיינו מה שמבואר<sup data-n=\"1108\">53</sup> למעלה במא' הזהר ע\"פ ויאבק כו' דאבק הוא דאשתאר מן נורא כו', פי' קליפה זו היא היותר אחרון שאין למטה ממנה עוד ולכן נמשלה לאבק דוקא וכמש\"ש הטעם דכמו שאבק הוא הנשאר אחרון אחר שנברר הכל ממנו ונכלל באש השואב כו' כך למעלה הנה ידוע דמבירורי הסיגי' והפסולת דקדושה מזה נעשה שרש לקליפה. והנה מה שנברר באצי' ונשאר פסולת נפל להיות בבחי' קלי' דאצי' והנשאר מבירורי' דקדושה בבריאה נעשה קלי' דבריאה ועד\"ז מבירורי סיגים שנשאר בעולם יצי' נעשה קלי' דיצי' ומה שנשאר מבירורי הסיגי' בעולם העשי' נעשה קלי' דעשיי' נמצא קלי' דעשיי' היותר אחרון בבחי' הפסולת והסיג ולכך הוא יכול לעשות עצמו כע\"ז ממש כאלו אינו מכיר את בוראו כלל. וזהו אבק שהוא נוק' דס\"מ הנק' אשת זנונים שקשה מכולם להיותה היותר אחרון מכולם וד\"ל.",[["1101","46","<b>דאת זלעו\"ז עשה האלקי'</b>: קהלת ז, יד."],["1102","47","<b>ויאמר אל עמו</b>: ראה שמות א, ט."],["1103","48","<b>אלקא דאלקייא</b>: מנחות בסופה."],["1104","49","<b>וכמ\"ש בתיקונים</b>: ראה ת\"ז ת\"ח."],["1105","50","<b>לי יאורי</b>: יחזקאל כט, ג."],["1106","51","<b>אשת זנונים</b>: ראה הושע א, ב."],["1107","52","<b>לילית ואגרת</b>: ראה רעיא מהימנא פנחס רל, א. ובכ\"מ."],["1108","53","<b>מבואר למעלה במא' הזוהר</b>: לעיל ע' קמח ואילך."]]],[2100490258,"<b>וענין</b> קלי' דיצי' ודבריאה איך שהמה בודאי אינם קשים כ\"כ כמו קלי' דעשיי', יובן מתוך דרז\"ל, דהנה אמרו רז\"ל נתן<sup data-n=\"1109\">54</sup> עיניו במקדש ראשון כו', ומשמע דנתן עיניו במזיד מפני רשעתו וקנאתו ע\"ד קנאה<sup data-n=\"1110\">55</sup> של נחש הקדמוני ולפעמים אמרו בהיפך כמו שדרש ר' אחא שטן<sup data-n=\"1111\">56</sup> ופנינה לש\"ש נתכוונו ואתא שטן ונשקי' אכרעי' הרי שדרש ר\"א שכוונת השטן בקטרוגו על ביהמ\"ק הי' לש\"ש לבד ולא בשביל רשעתו וקנאתו ונראים המאמרים כסותרים זא\"ז. אך הענין הוא דבאמת אינם סותרים זא\"ז כלל דמ\"ש נתן עיניו בבחי' רע גמור הוא בחי' ס\"מ דיצי' ומכש\"כ דעשיי' ששם חצי רע גמור, ומ\"ש לש\"ש נתכוין מיירי בס\"מ דבריאה<sup data-n=\"1112\">57</sup> שמיעוטו רע אך אעפ\"כ שמץ מיני' לרע ע\"כ קטרג לרע, אבל כוונתו אינו לרע אלא לש\"ש בלבד כי בטל הוא לגבי הקדושה ביותר והיינו ענין שטן שבעולם הבריאה ומכש\"כ באצי' עצמו דשם לא<sup data-n=\"1113\">58</sup> יגורך רע כתיב אין שם בשטן אפי' שמץ מן הרע אך ורק ענין הרגשת עצמותו בלבד וכמ\"ש ופלגשו<sup data-n=\"1114\">59</sup> ושמה ראומה וכמ\"ש במ\"א. אבל מ\"מ הנה אחר הבירורי' הנ\"ל ובהשתל' מעילה לעילה הרי נעשה קלי' בעשיי' בבחי' רע גמור כנ\"ל וד\"ל.\n<b>והנה</b> ידוע דבחי' המל' דאצי' היא היורדת לברר בירורים דרפ\"ח בבי\"ע בכל לילה וכמ\"ש ותקם<sup data-n=\"1115\">60</sup> בעוד לילה ותתן טרף והבירור הזה הוא נמשך ובא עד למטה מטה דהיינו גם בגקה\"ט לגמרי כמו קלי' דעשיי' הנ\"ל היותר תחתוני' מכולם. ואמנם הנה ענין הבירור בד\"כ הוא בא למטה בדרך מלחמה עד\"מ, וכמ\"ש כי<sup data-n=\"1116\">61</sup> תצא למלחמה על אויביך ושבית כו' דקאי למעלה בבחי' מל' דאצי' שמבררת בירורי דרפ\"ח ניצוצין מהיכלות הקלי' בדרך מלחמה וניצוח דוקא. והנה המלחמה הגשמי' כמו בב' מלכים גשמי' כמו אדום ויון וכיוצא הנה ידוע לכל מבין בענין מלחמה שלפעמי' יש בעצם המלחמה שיהי' עושה א\"ע כנרדף מפני שונאו וינוס מפניו בכדי שהשונא יזוז ממקומו ואז יוכל לסבבנו בחיל אחר מכל צד ופינה ויכנו עד בלי השאיר לו שריד או לאיזה כוונה אחרת יעשה א\"ע כנרדף מפניו, וזה ידוע שהמנוסה הזאת ודאי לא טובה לפי שעה שהרי השונא ינוס בשעה שנרדף מפניו והוא רודף אחריו, אלא שמניח א\"ע שיכנו שונאו בשביל התועלת הגדול שיהי' לו אח\"כ, ועד\"ז יש כמה מיני עצה בעניני המלחמה שיניח א\"ע יותר לסבול נצחון של השונא תחלה בשביל הנצחון שיצא מזה אח\"כ. והנמשל מזה יובן למשכיל למעלה דלפעמים ענין המלחמה שלמעלה ג\"כ ע\"ד הזה וה\"ע סוד גלות השכינה למטה לסבול שעבוד ועול הע\"ש בכדי שיצא אח\"כ מזה",[["1109","54","<b>נתן עיניו במקדש ראשון</b>: סוכה נב, סע\"א."],["1110","55","<b>קנאה של נחש</b>: ראה סנהדרין נט, ב."],["1111","56","<b>שטן ופנינה לש\"ש נתכוונו</b>: בבא בתרא טז, א."],["1112","57","<b>דבריאה שמיעוטו רע</b>: ראה ע\"ח (שער ציור עולמות) שמ\"ג בהקדמה. (שער סדר אבי\"ע) שמ\"ז, פ\"ד. (שער הקליפות נוגה) שמ\"ט, פ\"ו. ספר המאמרים תקס\"ג ח\"ב ע' תצא"],["1113","58","<b>לא יגורך רע</b>: תהלים ה, ה. ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתכט ובהנסמן לשם. מאמרי אדה\"א דברים ח\"ב ע' תרצא."],["1114","59","<b>ופלגשו ושמה ראומה</b>: וירא כב, כד. וראה מאמרי אדה\"א דברים ח\"ד ע' א'תצג, וש\"נ. תו\"ח נח נא, א ובהערה 5. אוה\"ת נח כרך ג' ע' 1202 בשם מבוא שערים שער הקליפות [ש\"י ח\"ב פ\"ה]."],["1115","60","<b>ותקם בעוד לילה</b>: משלי לא, טו."],["1116","61","<b>כי תצא למלחמה על אויבך</b>: כי תצא כא, י."]]],[2100490259,"נצחון גדול בהארת הקדושה האלקי' ומגיע תגבורת ההארה להפוך גם הרע דע\"ש לטוב ולהכניעם בתכלית אח\"כ ואע\"פ שעכשיו הוא בהיפך דרישא שכיבת לעפרא. וזהו מ\"ש עת<sup data-n=\"1117\">62</sup> אשר שלט האדם באדם לרע לו, דהשליטה דאדם בליעל באדם דקדושה עכשיו הוא לרע לו אח\"כ מפני שיבא מזה ניצוח גדול בתגבורת הקדושה על הסט\"א לאכפייא לון מן הקצה לקצה וכמשל הנ\"ל בעצת המלחמה להניח א\"ע להיות נסבל מניצוח שונאו בתחלה כו' וד\"ל. ועד\"ז יובן עוד למעלה מעלה עד רום המעלות דגם בעולמות העליונים יותר ג\"כ יוכל להיות ענין מלחמה וניצוח דקדושה עם ס\"א ע\"ד הזה, והוא מ\"ש מי<sup data-n=\"1118\">63</sup> זה בא מאדום כו' דקאי על בחי' ז\"א דאצי' שנלחם נגד הקלי' דאצי' איש בליעל וכמ\"ש ביעקב ויאבק<sup data-n=\"1119\">64</sup> איש עמו וכמש\"ל וד\"ל.\n(ה) <b>והנה</b> בעת אשר שלט האדם באדם כו' אזי נק' פגימת הלבנה שהלבנה חשך אורה לגמרי ובשעה שהנשמות יוצאות ממנה בעת ההיא לפעמי' יגבירו עליהם החיצוני' עד שיקומו בידיהם לגמרי. והדוגמא לזה במה שמצינו בפסל מיכה שנשמת מיכה זה הי' מן הנשמות שיצאו בעת פגימ' הלבנה למעלה והוא אשר השכינה למעלה אז מוסתרת ונעלמת להיות כמו מניצוח לפני שונאו, וע\"כ נגבר חלק הרע על נשמת מיכה וכשבאה לגוף בגלות מצרים הי' יוצא ממנו תולדות רעות הרבה וכשראוהו למשה שחמל על הילדים הנאבדים הוציאו לו נשמה זו דמיכה שיתקיים בכדי שיראה משה שאין בכל אלה טוב רק רע וכמו שהי' שעשה פסל ע\"ז כו'. ואמנם זהו מהחלק ממה שנותנים לחיצונים, אבל מה שיצא מהניצוח הזה לרע להם אח\"כ יובן מהדוגמא מה שמצינו במעשה<sup data-n=\"1120\">65</sup> דיהודה ותמר דהנה יהודה בודאי לא כיון לתאוה רעה שבודאי הי' נשמר מכחות החיצוני' שגברו אז וגם תמר שהלבישה א\"ע בכוונת תאוה רעה ידוע שכוונתה לש\"ש הי' וגם ביהודה לא הי' הכוונה רק לש\"ש בלבד כי הרי הי' צדיק גמור אך שירד יהודה מאחיו בהתלבשות עניני מלחמה כאלו לברר הטוב מן הרע והוא ע\"י שילבישו א\"ע בתאוה רעה ויצאו מזה תולדות בקדושה ביתר שאת. ואמנם אם לא הי' תגבורת עוצם כוונת יהודה ותמר לש\"ש לא הי' ביכולתם לעמוד במלחמה זו כי הרי מ\"מ הי' מושלת בהם תאוה רעה אלא שכוונתן דקדושה דבקה וגברה עליה עד שאע\"פ שבחיצוני' הי' שליטת הרע הרי מ\"מ יצא מיהודה משיח וגם מלכים ונביאי' רבים ונשמות גבוהות דקדושה וכידוע והרי אנו רואים להדי' שיוכל להיות נתינה מועטת לחיצוני' שמרויח בנתינה זו בכפלי כפלים לאין שיעור כו' וה\"ז ממש כמשל העצה במלחמה ליתן א\"ע לשונא קצת, אך לתכלית הדבר יהפך עליו ואז יגביר עליו בניצוח גדול יותר הרבה מכמו שהי' מנצח אותו בתחלת המלחמה כו'. ואמנם זהו הכלל שאין נותני' לחיצוני' בתחלת בשביל ההרווחה שתהי' אח\"כ רק בחי' הפסולת והחיצוני' בלבד ולא מבחי' פנימי' כלל כדי שלא יצא שכרו בהפסדו ח\"ו. וגם במשל המניח א\"ע להיות נרדף משונאו הרי לא יניח א\"ע רק במה שיהי' רודף אחריו מעט ולא שיכנו הרבה וכיוצא",[["1117","62","<b>עת אשר שלט האדם</b>: קהלת ח, ט."],["1118","63","<b>מי זה בא מאדום</b>: ישעי' סג, א."],["1119","64","<b>ויאבק איש עמו וכמש\"ל וד\"ל</b>: ראה לעיל ע' קמח ואילך."],["1120","65","<b>במעשה דיהודה ותמר</b>: ראה וישב לח, ו ואילך."]]],[2100490260,"שא\"כ מה ירויח אח\"כ. וכך המשל למעלה בעת אשר שלט האדם כו' אין נותנים לו שליטה רק בבחי' החיצוני' בלבד והוא מ\"ש מי זה בא מאדום חמוץ בגדים כו' בגדי' לבד כמ\"ש וכל<sup data-n=\"1121\">66</sup> מלבושי אגאלתי שהלבושי' שלו בלבד הוא שגעלו ומאס אותן בהניחו לשלוט בהם יניקת החיצונים כו'. וכן הענין בכ\"מ שהזכירו רז\"ל ענין יניקת הס\"א בקדושה אינו רק בבחי' חיצוני' בלבד וכמו ענין המאמר בא<sup data-n=\"1122\">67</sup> נחש על חוה והטיל בה זוהמא אין הענין רק בבחי' לבושים שנפגמו בחי' הלבושים ע\"י הזוהמא של נחש כו' כאשר מקבלת ממל' דקדושה הנק' חוה כי היא היתה אם<sup data-n=\"1123\">68</sup> כל חי כידוע שהוא רק בחי' אחוריים דשם ב\"ן דקדושה כו' וד\"ל.\n<b>וזהו</b> שארז\"ל אמר הקב\"ה הביאו עלי כפרה על שמיעטתי את הירח, דהנה בחי' מיעוט הירח מבואר למעלה דהיינו מה שבחי' מל' דאצי' היא בכל חדש בתכלית הירידה להיות ראש לשועלים בבי\"ע ובהיותה שם היא מתלבשת כדי לברר רפ\"ח ניצוצי' עד למטה מטה גם בגקה\"ט לגמרי כמו באשת זנונים הנ\"ל. ואמנם בהלבשה זאת אינו אלא רק בבחי' חיצוני' בלבד כנ\"ל וא\"כ גם בי\"ס דעשיי' שהמל' דקדושה מברר מל' דקלי' בדרך הלבשה כנ\"ל התלבשות זו אינו אלא בבחי' חיצוני' בלבד דהיינו שנותני' לה כח ועוז מבחי' לבושי' וחיצוני' מי\"ס דקדושה שזה בלבד הוא הנמשך ומתלבש בנוגה אבל אין נותני' לה מבחי' הפנימי' דקדושה דעשיי' כלל וכלל וכמ\"ש וכבודי<sup data-n=\"1124\">69</sup> לאחר לא אתן ואין לחיצוני' כח כלל לקבל משם מטעם הנ\"ל שאין נתינה זאת ענין אמיתי או אפי' שיהי' בהכרח דבר אלא רק מצד הכוונה שיהי' התועלת אח\"כ לרע לו כו', א\"כ אין נותנים לו רק בחי' חיצוני' דחיצוני' בלבד והיינו רק כדי לברר ממנו אח\"כ פנימי' הקדושה הרבה בכפלי כפליים לאין שיעור (וכמעשה דיהודה ותמר והגם שלאחר שנתנה התורה אסור לנו לעשות כענין זה אפי' באיסור קל של ד\"ס וכידוע, אך בדברים המותרים לגמרי מצד הדין אלא שהוא מ\"מ בחי' רע מצד התאווה כמו תאוות היתר באכילה ושתי' וכיוצא גם עכשיו יוכל להיות בצדיקים בדוגמא זו בנתינה חיצוני' ולא בבחי' פנימי' כלל. והדוגמא מזה הוא מ\"ש בלק\"א הגדול דבהעלות מ\"ז באדם גם מתאווה מותרת כממון וכיוצא זה ההרהור מ\"מ בחי' רע הוא וכאשר מגביר עליו האהבה האלקי' דקדושה ומתבטלת ה\"ז ענין ניצוח הנ\"ל שבא לקדושה ביתר שאת אחר שהניח עצמו תחלה, וענין ההנחה אינו שיחשוב מ\"ז בתחלה ח\"ו אלא שאם נפלה פתאום אל יפול לבו פתאום אלא יגביר עליה האה' לה' וע\"י שמתבונן בה איך להעלותה כו' ה\"ז כמתאבק<sup data-n=\"1125\">70</sup> עם המנוול שיתנוול גם הוא בהאבקו עמו מפני שיש באיבוקו עמו קצת ניצוח המנוול לפי שעה כו'. ואמנם לא כל אדם יוכל ללחום בהניצוח ויכול ליפול הנופל לפי שעה גם בהיות שדעתו קצרה, וע\"כ ע\"ה<sup data-n=\"1126\">71</sup> אסור לאכול בשר וזהו אל<sup data-n=\"1127\">72</sup> יאמר אי אפשי",[["1121","66","<b>וכל מלבושי אגאלתי</b>: ישעי' סג, ג."],["1122","67","<b>בא נחש על חוה</b>: שבת קמו, א. זח\"א נב, ב."],["1123","68","<b>כי היא היתה אם כל חי</b>: בראשית ג, כ."],["1124","69","<b>וכבודי לאחר לא אתן</b>: ישעי' מב, ח."],["1125","70","<b>כמתאבק עם המנוול</b>: ראה תניא פכ\"ח."],["1126","71","<b>ע\"ה אסור לאכול בשר</b>: פסחים מט, ב. וראה לקו\"ש ח\"ב ע' 455."],["1127","72","<b>אל יאמר אי אפשי</b>: ראה תו\"כ ס\"פ קדושים. שע\"ת ש' התפלה עא, סע\"ד ואילך."]]],[2100490261,"בבשר חזיר אלא אפשי אבל אבי שבשמים גזר עלי). וזהו הביאו עלי כפרה על שמיעטתי את הירח דהיינו ליתן מקום לס\"א בבחי' חיצוני' דחיצוני' והוא קרבן שעיר דמוסף ר\"ח וכמ\"ש ושעיר עזים כו' והוא נעשה לכפרה על השכינה שמלבישה א\"ע בלבוש זר דקלי' לברר כו' והשעיר הוא חלק הס\"א בכדי שיצא מזה תוס' אורה בקדושה כמ\"ש בזהר<sup data-n=\"1128\">73</sup> בענין הקוצי דשערי שמניחין בתפילין לצאת לבר כו'. והטעם שבר\"ח צוה להביא כפרה הוא מפני שאז זמן עליי' המל' מבי\"ע ומתחלת להאיר מעט מעט מהארת אור השמש שהוא בחי' שם מה כו' וכנ\"ל ועד הנה היתה אפילה מאופל יניקת החיצונים אשר שלטו בלבושי' שלה כו' וד\"ל.\n<b>ולהבין</b> שרש ענין היניקה והפגם בלבושי' בלבד כמ\"ש וכל מלבושי אגאלתי כנ\"ל, הנה יובן ע\"פ הידוע בכתבי האריז\"ל דלפעמים מקבלת המל' מבחי' פלא עליון ואז אין מקום ושרש כלל וכלל ליניקת החיצונים גם מבחי' הלבושים בלבד ע' מזה בע\"ח של\"א הוא שער הארת המוחין שם פ\"ז, אבל כשהמל' היא בבחי' אלקי' וכמ\"ש מלך<sup data-n=\"1129\">74</sup> אלקים על גוים כו' אזי גם הע\"ש מקבלים כי יש ק\"כ צירופי' באלקי' דקדושה וע\"ב הם דקדושה ממש ומ\"ח צירופי' אלקי' האחרונים מקבלים מהם החיצוני', וזהו מ\"ש ואותות<sup data-n=\"1130\">75</sup> ומופתים באדמת בני חם, ומאותן המ\"ח צירופי' נמשך יניקה לבחי' אלקי' אחרים שמקבלים מבחי' אחוריים דאלקי' דקדושה כו', אבל כשהמל' מקבלת מבחי' פלא אין שם צירופי אותיות דאלקי' כלל, וזהו ומום<sup data-n=\"1131\">76</sup> אין בך מום<sup data-n=\"1132\">77</sup> גימט' אלקי' שמשם יש יניקה כו', וא\"כ אין אחיזה ויניקה לחיצוני' רק בבחי' הלבושי' בהיכלות דקדושה בלבד ולא בבחי' או\"כ כלל וכלל אפי' בבחי' חיצוני' הכלים שהרי ידוע דענין הכלים הם בחי' צירופי אותיות והם מקבלים מנקבי החללים שבין צירוף לצירוף בלבד כידוע בענין זיעתן<sup data-n=\"1133\">78</sup> של חיות שנעשה נהר דינור כו' שהוא כמו הזיעה שיוצאה מנקבי העור בלבד וכמ\"ש במ\"א וד\"ל.\n(ואו) <b>ועתה</b> יתבארו דברי המאמר' הנ\"ל בפרטיות. בההוא שעתא דההוא נהר דנגיד ונפיק אפיק כל אינון נשמתין ואתעברת נוק' כולהו קיימין לגו כו'. פי' נהר דנגיד הוא בחי' יסוד ז\"א שמשפיע מבחי' המ\"ד שלו כל אינון נשמתין והוא ע\"י יחוד דמ\"ה וב\"ן כידוע והיינו ואתעברת נוק' כו'. והנה מבואר למעלה שבכל חדש יש מילוי הלבנה ופגימת הלבנה, המילוי שלה הוא באמצע החדש דוקא והפגימה שלה הוא בסוף חדש ובתחלת החדש בהיותה רק כנקודה חדא כו' הנה היא מוסיף אורה מאור השמש מעט עד שהיא במילואה. והמשל בזה למעלה יובן שבחי' מל' דאצי' שנק' לבנה כשהוא בענין מיעוט האור מכל וכל בסוף החדש אזי היא",[["1128","73","<b>בזהר בענין הקוצי דשערי</b>: ראה זהר פקודי רלז, ב. מאמרי אדה\"א דברים ח\"ב ע' תרח, וש\"נ."],["1129","74","<b>מלך אלקים על גוים</b>: תהלים מז, ט."],["1130","75","<b>ואותות ומופתים באדמת בני חם</b>: ע\"פ ברכת אמת ואמונה (תפלת ערבית)."],["1131","76","<b>ומום אין בך</b>: שה\"ש ד, ז."],["1132","77","<b>מום גימט' אלקי'</b>: מאו\"א אות מ' י\"ז. וראה גם אוה\"ת חנוכה שטז, ב. תשא ע' א'תתמד. אמור ע' קנו."],["1133","78","<b>זיעתן של חיות. . וכמ\"ש במ\"א</b>: ראה חגיגה יג, סע\"ב. וראה לקו\"ת שה\"ש מב, ד. ובכ\"מ."]]],[2100490262,"בבחי' ענין הניצוח מלחמה הנ\"ל לברר רפ\"ח כו' מהיכלות הקליפות כנ\"ל, ואז הוא בתכלית החשך כדי שאח\"כ יהי' מוסיף אורה ע\"י הניצוח כנ\"ל, וע\"כ כשמקבלת השפע אז מבחי' מ\"ד דהיינו אור השמש דהנה עד\"מ הלבנה שלמטה מפני שבקירובה מאד לשמש בסוף החדש הוא הסיבה שנחסר אורה ותחשך וכל מה שהיא מתרחקת מעט מעט מן אור השמש יותר תאיר אור כי לא תוכל לקבל האור מן השמש כ\"א מרחוק ולא מקרוב כידוע. והנמשל מזה גם למעלה דבחי' מל' דאצי' בהיותה מתקרבת מאד בסוף החדש אזי תחשך אורה ותרד אז ללחום ולנצח כי ע\"י פגימת אורה יוכלו החיצונים להתדבק בה כנ\"ל ע\"כ כשמקבלת אז שפע נשמות עליונות ממ\"ד דז\"א גם הן הן שבאים ונמשכים למטה באותו בחי' הפגם שנפגמה המל' אז בהעדר אור השמש ממנה ונהפוך הוא שנדבקו בה אורות זרים. והנה מבואר למעלה שאין אחיזתם בה אז רק בבחי' הלבושי' בלבד ולא בבחי' הפנימי' כו' ע\"כ אמר כאן וכד סיהרא אתפגים בההוא סט' דחויא בישא דהיינו מה שבא נחש על חוה והטיל בה זוהמא שאינו אלא בבחי' לבושי' כנ\"ל כדין כל אינון נשמתין דנפקין בפגימו אע\"ג דכולהו דכיין הואיל ונפקין בפגימו כו'. פי' מצד בחי' הפנימי' שלהם הם דכיין וקדישין מפני שאין לחיצוני' אחיזה ויניקה בפנימי' כלל וכמש\"ל אבל מ\"מ מפני אחיזתם ויניקתם בחיצוני' הלבושי' דמל' אף גם הנשמות שמקבלת המל' אז נפגמו גם הם בבחי' חיצוני' שלהם באותה השעה כו'. וז\"ש עוד בכל אתר דמטו אינון נשמתין אתברו ואתפגימו באינון צערין וכאבין כו'. פי' בכל אתר דמטו היינו רק בבחי' מקום והיכל שנק' אתר וידוע שבחי' היכלות העולמות הן בחי' החיצוני' של העולמו' ולא מבחי' הפנימי' כלל. וע\"כ אמר בכל אתר דמטו כלומר כשיורדין להתלבש למטה בעולמות החיצוני' באיזה לבוש גופני או באיזה היכל מן ההיכלות החיצוני' דבי\"ע שם הם שנפגמו דהיינו בלבושיהם בלבד. ופי' דמטו שיורדין ונמשכי' בהתלבשות למטה ויש בזה כמה רבבות מדרגות זה למטה מזה מהיכל להיכל עד היותר אחרון הוא לבוש גופני בעוה\"ז השפל דאפגים הגוף בצער וכאב היסורי' גשמיי', אבל הנשמה מצד בחי' פנימיותה היא אינה נפגמת כלל באותם היסורים מטעם הנ\"ל דלא הי' עיקר סיבת הפגם בתחלה גם במל' שרש כל הנשמות אלא רק בבחי' חיצוני' בשביל טעם הניצוח כנ\"ל והיינו שמסיים שריין כגוונא דלעילא גופא אתפגים ונשמתא לגו כו'. פי' כמו בחי' מל' דאצי' שנפגמו הלבושים שלה בלבד ולא נפגם בחי' הפנימי' כלל כנ\"ל והיינו כגוונא דלעילא.\n<b>ומש\"ע</b><sup data-n=\"1134\">79</sup> ובג\"כ אינון דבעון לאתחדתא בחדתותי דסיהרא וכמ\"ש והי' מדי חדש כו' יבא כל בשר ודאי ואינון בשותפתא חדא בסיהרא עד הה\"ד למען אחי כו' רצונו בזה המאמר על לעתיד דוקא ולא עכשיו שהרי עכשיו אין אור ללבנה כ\"א מה שמקבלת מאור השמש ובהכרח הוא שיהי' לה השינוי הזה בפגימה ומילוי בכל חדש מטעם הנ\"ל והפגימה עכ\"פ בבחי' הלבושים וא\"כ איך יאמר עכשיו יבא כל בשר שר\"ל גם בחי' החיצוני' דלבושי' שנפגמו גם הם יבאו להיות בבחי' הפנימי' לפני ה', אלא הכוונה בזה המאמר הוא על העתיד דוקא דכתי' אז והי'<sup data-n=\"1135\">80</sup> אור הלבנה",[["1134","79","<b>ומש\"ע</b>: ומה שאמר עוד."],["1135","80","<b>והי' אור הלבנה</b>: ישעי' ל, כו."]]],[2100490263,"כאור החמה שיהי' בחי' זו\"נ שניהם שוין בקומתן ולא תצטרך הלבנה לקבל מהשמש ואז לא יהי' בה כלל אותו השינוי הנ\"ל בפגימה ומילוי משום דלא תצטרך גם לניצוח המלחמה לברר הפנימי' ע\"י שתניח לפגום החיצוני' כנ\"ל מפני שכבר יבורר אז בחי' הרע לגמרי מכל וכל כמ\"ש ואת<sup data-n=\"1136\">81</sup> רוה\"ט אעביר מן הארץ, וע\"כ אמר יבא כל בשר ודאי ר\"ל גם בחי' החיצוני' שנפגמו יחזור הכל לקדושה וכמ\"ש חיל<sup data-n=\"1137\">82</sup> בלע ויקיאנו כו' ואותן הנשמות ג\"כ יושלמו בלבושיהן שנפגמו מצד שרשן בפגימת הלבנה, וע\"כ א' ובג\"כ אינון דבעיין כו' אינון דוקא כי יהי' חברי' משותפי' בהדה וכמ\"ש בסוף המאמר עד הה\"ד למען אחי להיותם משותפי' בהדה בבחי' שלימות הניצוח ע\"י פגימת לבושים שלהם עם המל' וד\"ל.\n(ז) <b>אך</b> הנה גם אחר כל הנ\"ל בפי' המאמר עדיין י\"ל באותו הפסוק שהתחיל בו ר\"ש אותו מאמר הנ\"ל והוא אך אל הפרוכת כו' כי מום בו, מה ענינו לענין המאמר שאמר עליו ולפי משמעות ענין המאמר לא הי' לו להתחיל רק בפסוק והי' מדי חדש כו' דמיירי בענין חידוש הלבנה אבל פסוק זה דאך אל הפרוכת דמיירי בכהן מה ענינו לענין פגימת הלבנה ומילואה. אך הענין יובן בהקדים ענין הכהן מהו, דהנה כתי' ובת<sup data-n=\"1138\">83</sup> איש כהן כי תהי' לאיש זר כו' וידוע בזהר<sup data-n=\"1139\">84</sup> ורע\"מ דקאי על הנשמה האלקי' שנק' בת כהן דלעילא כי באה מלמעלה בבחי' חלק אלוה ממעל כמו בת לאב, ומה שנק' בת כהן כי הכהן<sup data-n=\"1140\">85</sup> נק' אב כי הוא מסט' דחסד הוא קו הימין חח\"נ והכל ענין א' כי החסד<sup data-n=\"1141\">86</sup> ענף החכ' וע\"כ נק' הנשמה ג\"כ בתו של אברהם כמ\"ש בת<sup data-n=\"1142\">87</sup> נדיב ונק' ג\"כ בת כהן והכל א' מטעם הנ\"ל. ועד\"ז יובן בכללות נש\"י שהוא בחי' מל' דאצי' למעלה כידוע, הנה ג\"כ נק' ברתא והוא בת כהן דלעילא דהיינו מאור אבא דאבא<sup data-n=\"1143\">88</sup> יסד ברתא או בת איש כהן והכל א' כנ\"ל. והנה מבואר למעלה דבחי' מל' דאצי' הוא שנפגמה בבחי' פגימת הלבנה בלבושי' בלבד כו' וע\"כ אמר בבת כהן הנ\"ל ג\"כ דאם יהי' בכהן מום כמו יבלת או שאר מום באברים דאל הפרוכת לא יבא ואל המזבח לא יגש כי מום בו, אבל לחם אלהיו מקה\"ק יאכל, והטעם הוא לפי שאין הפגם שלו רק בבחי' הלבושים והוא בבחי' החיצוני' בלבד כמו כלי הגוף החיצוני' כיבלת וכיוצא, אבל לא שנפגמה נשמתו בבחי' פנימי' כלל וכלל וא\"כ הגם שיש בו מום באבריו החיצוני' זה לא מזיק כלל לבחי' פנימי' שבנשמתו, וע\"כ לחם אלקיו גם מקה\"ק יאכל כמו כל הכהנים התמימי' שהכהנים אוכלים ובעלים מתכפרי' כידוע גם הוא יאכל הקרבן והבעלי' מתכפרי' באכילתו לפי שיוכל להעלות הנפש החוטאת באכילתו הקרבן כשאר הכהנים כי יש לו כח ההעלאה באכילתו קדה\"ק בשלימות שהרי לא",[["1136","81","<b>ואת רוה\"ט אעביר מן הארץ</b>: זכרי' יג, ב."],["1137","82","<b>חיל בלע ויקיאנו</b>: איוב כ, טו."],["1138","83","<b>ובת איש כהן. . לאיש זר</b>: ראה אמור כב, יב."],["1139","84","<b>בזהר וברעיא מהימנא</b>: ראה זח\"ב צה, א. רעיא מהימנא נשא קכד, א."],["1140","85","<b>הכהן. . מסט' דחסד</b>: ראה זהר נשא קמה, ב. צו כז, א."],["1141","86","<b>החסד ענף החכמה</b>: ראה זהר ואתחנן רסב, סע\"א. לך צד, א. תרומה קעה, ב. במדבר קיח, ב."],["1142","87","<b>בת נדיב</b>: שה\"ש ז, ב."],["1143","88","<b>דאבא יסד ברתא</b>: זח\"ג רמח, ב. רנו, ב. ועוד."]]],[2100490264,"נפגמה נשמתו בבחי' פנימי' כלל וההעלאה שבאכילת כהן תלוי' דוקא בבחי' פנימי' הנשמה שהוא כמו הכוונות והיחודים כו' כמ\"ש במ\"א שאכילת כהנים הי' בעמידה כמו תפלת שמו\"ע דעכשיו בבחי' ביטול במציאות דמ\"ה דחכ' ומ\"ה דחכ' שיש בכהן מצד שרש נפשו הרי לא נפגמה כלל וכלל ע\"כ לחם אלקיו יאכל אבל אל הפרוכת לא יבא ואל המזבח לא יגש כו' דהיינו לעבוד עבודה של המזבח בתיקוני הקרבן שלפני אכילת כהנים (וה\"ע בירור הראשון דמ\"ן דנוק' כנ\"ל) לפי שנפגם בבחי' חיצוני' מצד פגימת הלבנה ביניקת החיצוני' וע\"כ יש בו מום חיצוני בעין ואוזן וכיוצא ולעבודה חיצוני' דכפרת מזבח מזיק בחי' המום החיצוני ג\"כ כי שם יש גם להם שרש אחיזה ויניקה. וזהו ממש כענין הנ\"ל בפי' המאמר באינון נשמתין דנפקין בפגימו כו' דשריין כגוונא דלעילא גופא אתפגים ונשמתא קיימא לגו כך הכהנים בע\"מ נשמתא קיימא לגו כו' שלם בשלימות בתכלית עד שבאכילתו מכפר על הבעלים ככהן תמים ממש, אך מפני דגופא אתפגים לכן אל המזבח לא יגש להקריב מטעם הנ\"ל עד שיאיר אור הלבנה כאור החמה דכתיב במל' כולך<sup data-n=\"1144\">89</sup> יפה רעייתי ומום אין בך כו' וד\"ל, והיינו שהתחיל ר\"ש בפסוק זה דאך אל הפרוכת כו' ואמר עליו אותו המאמר הנ\"ל באינון נשמתין דאפגימו בבחי' חיצוני' ולא הוצרך לפרש אחר שמסיים המאמר בפסוק זה דאך אל הפרוכת כי ממילא מובן אחר שלא פסלו הכתוב רק לעבודת מזבח אבל לחם אלקיו יאכל וכמ\"ש אך כו' שהוא מיעוט כלומר רק לאותו דבר, א\"כ ממילא מובן שהוא כמו ענין פגימת הלבנה בבחי' החיצוני' בלבד וכנ\"ל וד\"ל.",[["1144","89","<b>כולך יפה רעייתי</b>: שה\"ש ד, ז."]]],[2100490265,"<h3>נוסח שני: בזוהר פ' וישב ר\"ש פתח אך אל הפרוכת</h3>\n<b></b><b>בעזרה\"י, ליל ש\"ק פ' וישב (בזוהר פ' וישב ד' קפ\"א ע\"א)</b>\n<b>ר\"ש</b><sup data-n=\"1145\">1</sup> פתח אך אל הפרוכת לא יבא וגו' ת\"ח בההיא שעתא דההוא נהר דנגיד ונפיק מעדן אפיק כל אינון נשמתין ואתעברת נוק' כלהו קיימין לגו כו' וכד סיהרא אתפגים בההוא סט' דחויא בישא כדין כל אינון נשמתין דנפקין אע\"ג דכלהו דכאין וכלהו קדישין הואיל ונפקי בפגימו, בכל אינון אתרי דמטו אינון נשמתין כולהו אתברו ואתפגימות בכמה כאבין כו' ואילן אינון דאתרעי בהו קב\"ה לבתר דאתברו כו' רז\"א דמלה שריין כגוונא דלעילא גופא אתפגים ונשמתא לגו כגוונא דלעילא ובג\"כ אילין אינון דבעיין בחדתותי דסיהרא ועל אלין כתיב והי' מדי חדש וגו' יבא כל בשר להשתחות לפני וגו' ע\"ש בארוכה.\n<b>ויובן</b> כ\"ז היטב בהקדים לבאר ענין מילוי הלבנה ופגימתה כמ\"ש<sup data-n=\"1146\">2</sup> בע\"ח בשער מיעוט הירח כו' ע\"ש והיינו כי לבנה היא בחי' מלכות דאצי' דלית לה",[["1145","1","<b>ר\"ש פתח אך אל הפרוכת</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (רכב, ב).\nהנחת כ\"ק אדמו\"ר האמצעי נדפס לעיל ע' קעד."],["1146","2","<b>כמ\"ש בע\"ח בשער מיעוט הלבנה</b>: ספ\"א ופ\"ב. ראה תו\"א וישלח כו, ג."]]],[2100490266,"מגרמה כלום זולתי מה שמקבלת מן השמש הוא בחי' ז\"א דאצי'. והענין בהיות ידוע שיש כמה שמות וכינויים למלכות דאצי' כמ\"ש בפרד\"ס &lt;צא&gt;\nבשער המציאו' שלפעמים נק' בחי' עפר כמ\"ש ומעפר<sup data-n=\"1147\">3</sup> אשר בקרקע המשכן וגו' (וכמשנת\"ל<sup data-n=\"1148\">4</sup> בדרוש דעפר ואב\"ק ע\"ש) ולפעמי'<sup data-n=\"1149\">5</sup> בחי' אבן כמ\"ש אבן<sup data-n=\"1150\">6</sup> מאסו הבונים וגו' וכן בצומח נק' אתרוג<sup data-n=\"1151\">7</sup> בחי' מלכות ובמדבר נק' הדבור בחי' מלכות וכיוצא בזה כל הכנויים דמלכות דאצי' מרמזים על מציאותה ומהותה ואיכותה שנקראת בחי' עלמא דאתגליי' ולכך נק' בשם דבור ולזאת כל המספרי' דשמו' דאצי' הוא במל' דאצי' עד שהיא בחי' תחתונה ולכך כל המספרי' בה וד\"ל מצד שטבע מדת מלכות לגלות הנעלם בבחי' גילוי שיתראה ויתגלה בבחי' יש ודבר מה מצד היותה בחי' ומדרגה תחתונה שבאצי' לכך נק' בכנויים דאבן ועפר שהם ממדרגה התחתונה שבד' יסודו' ארמ\"ע<sup data-n=\"1152\">8</sup> שהם כנגד ד' עולמות אבי\"ע (שאף באצי' ימצא ד' בחי' אבי\"ע ודצח\"ם).\n<b>וביאור</b> הענין דהנה כתיב אלה<sup data-n=\"1153\">9</sup> המלכים אשר מלכו בארץ אדום וגו' וימלך בלע וגו' וימת וגו' וימלוך כו' וימת כו' כנודע שזהו ענין השבירה<sup data-n=\"1154\">10</sup> והמיתה דז' מלכים קדמאין דתה\"ו שעיקר השבירה של הכלי' דתה\"ו הי' במדת מלכות דוקא שכיון שנתגלו בבחי' גילוי מדת המלכות אזי נתראו בבחי' יש ודבר מה ולכך נשברו פי' כי בתה\"ו הי' הספי' זתח\"ז בבחי' פרוד ולא הי' מחוברי' ונכללי' זב\"ז כאחד כמו עתה בעולם התיקון והיינו מצד שלא הי' מתגלה בחי' תוספת אור א\"ס ב\"ה בתוך הכלים הקטנים דתהו שלא יכלו לסבול רוב אורו מצד קטנו' הכלים ומאחר שהי' בהם מיעוט גילוי אור א\"ס ב\"ה לכך לא הי' נמצא בהן בחי' מציאו' הביטול כ\"כ עד שיוכללו ויתחברו כאחד ממש כ\"א כאו\"א נעשה יש נפרד בפ\"ע כמו בחי' החסד דתה\"ו נתראה ונתגלה בבחי' יש ודבר מה בפ\"ע בבחי' מלכות שבחסד שהוא הגורם סבת הגילוי שתתראה בבחי' יש ודבר מה בפ\"ע שזהו המלך הראשון כמ\"ש וימלוך<sup data-n=\"1155\">11</sup> בלע וגו' ומאחר שנתראה ונתגלה ספי' החסד דתה\"ו בבחי' יש ודבר מה של המלוכה שהוא גרם העיקרי של הגילוי לכך וימת בבחי' מיתה ושבירה, וכן הגבורה שתחתיה שהיא נתגלה בבחי' מל' שבגבורה להיות נתראה למהות ודבר בפ\"ע שלכך אין לה חבור והתכללות בספירת החסד מצד היותה מתפשט' בבחי' גילוי המל' שבה",[["1147","3","<b>ומעפר אשר בקרקע המשכן</b>: נשא ה, יז — ומן העפר אשר יהיה בקרקע המשכן."],["1148","4","<b>(וכמשנת\"ל בדרוש דעפר ואבק ע\"ש)</b>: ראה לעיל ע' קסד ואילך."],["1149","5","<b>ולפעמים בחי' אבן</b>: ראה פרדס שער (כג) ערכי הכנויים מערכת אבן."],["1150","6","<b>אבן מאסו הבונים</b>: תהלים קיח, כב."],["1151","7","<b>נק' אתרוג בחי' מלכות</b>: ראה תיקוני זהר בהקדמה ב, ב. תי\"ג (כט, א). תכ\"א (נו, רע\"ב). פרדס שער (כג) ערכי הכינויים מערכת אתרוג. פרי עץ חיים שער (כט) הלולב פ\"א-ג. מאורי אור מערכת אתרוג סק\"ע. ספר המאמרים עטר\"ת ע' כד ואילך."],["1152","8","<b>ארמ\"ע שהם כנגד ד' עולמות אבי\"ע</b>: ראה סידור שחרית לג, א. לקו\"ת פינחס עה, ד. מאמרי אדה\"א במדבר ח\"ה ס\"ע א'תרמג."],["1153","9","<b>אלה המלכים אשר מלכו בארץ אדום</b>: וישלח לו, לא."],["1154","10","<b>השבירה והמיתה דז' מלכים קדמאין דתהו</b>: ראה גם מאמרי אדה\"א דברים — ד\"ה אל תצר את מואב — ע' א ואילך. פירוש המלות פקכ\"ו."],["1155","11","<b>וימלךוך בלע</b>: ראה וישלח לו, לב — וימלוך באדום בלע."]]],[2100490267,"להתראות ליש ודבר מהו' בפ\"ע לכך עומדת תחת ספי' החסד כו' ועד\"ז כל הז' מדו' דתה\"ו נתגלו במלכיות שבהן בבחי' גילוי ויש ודבר כאו\"א בפ\"ע לכך הם מתפרדין זמ\"ז שהם עומדים זתח\"ז שאין להם התחברו' והתכללו' זב\"ז, ועיקר הגורם לסבת התחלקותן וההתגלות שלהם בבחי' יש ודבר במלכיות שלהן הוא מצד מיעוט האור א\"ס ב\"ה שבהכלי' הקטנים דתה\"ו כנ\"ל וכן מלכות שבחכמה שמאין תימצא שכאשר נמשכה החכמה מאי\"ן טרם התפשטותה בגילוי המל' שבה הוא בחי' תחתונה שבה אזי היא בחי' אי\"ן ממש בחי' כח מ\"ה תכלית הביטול האמיתי בלי הרגשה כלל, וכיון שנתגלה ונתפשטה בבחי' מלכות שבה אזי נתראה בבחי' יש ודבר מה, והיינו עד\"מ למטה כמ\"ש שלמה המלך במשלי ראית<sup data-n=\"1156\">12</sup> איש חכ\"ם בעיניו תיקוה לכסיל ממנו פי' דכאשר הוא חכם ואינו יודע &lt;צב&gt;\nבעצמו מזה שאינו חכם בעיניו מצד שהחכמה<sup data-n=\"1157\">13</sup> אינה נרגשת אצלו בבחי' יש ודבר מה אזי זהו עיקר ואמיתית החכמה אבל כשראית איש חכם בעיניו שנרגשת אצלו בבחי' יש ודבר שמחזיק לעצמו חכם מצד הרגשתו בבחי' יש ודבר ממש איך הוא חכם אזי תקוה לכסיל ממנו כמשמעו, ועוד י\"ל תיקוה לכסיל ממנו הוא המלך זקן וכסיל שיש לו תיקו\"ה ממנו פי' שי[ו]נקי' אז החצוני' מהחכמה מאחר שנתפשטה בבחי' יש ודבר ממש עד שהוא חכם בעיניו שאז יש מקום להחצוני' לינק כנודע שעיקר יניקת החצונים הוא מבחי' היש דוקא היפך הביטול דחכמה<sup data-n=\"1158\">14</sup> כ\"ח מ\"ה שאין להם יכולת לינק משם ולכך ראית איש חכם בעיניו תקו\"ה לכסיל ממנו כנ\"ל.\n<b>כך</b> ממש עד\"מ למעלה במל' שבחכמה דתה\"ו שהי' הפנים באחוריים דאו\"א מצד שנתגלה החכמה בבחי' המלכות שבה אזי נתגלה ונתראה בבחי' יש והרגשה שאז לא נמצא בה תכלית הביטול דעצמו' החכמה כ\"ח מ\"ה כנ\"ל, נמצא העולה מזה שמל' הוא סבת הגילוי של העצם להיותו נתראה בבחי' יש ודבר מה בבחי' גילוי והרגשה ממש הן בחי' המל' שבחכמה שגורם סבת הגילוי של חכמה<sup data-n=\"1159\">15</sup> שמאי\"ן תמצא לבחי' יש והן מל' שבחסד גורם סבת הגילוי של החסד כו' כנ\"ל שזה היה הגרם והסבה של השבירה דז\"ת דתה\"ו שעיקר השבירה הי' מצד שנתגלו ונתראו בבחי' יש ודבר מה במלכו' שלהן כמ\"ש וימלוך כו' וימת כו' וימלוך כו', ועיקר הסבה לזה שנתגלו ונתראו בבחי' יש ודבר במלכיות שלהן הוא מצד מיעוט אור א\"ס ב\"ה שבהכלי' קטנים דתה\"ו שעי\"ז נתפרדו זמ\"ז להיות זתח\"ז כאו\"א מהות יש ודבר מה בפ\"ע המתגלה במל' שבו בפ\"ע ואין להם חבור והתכללות כלל כנ\"ל וד\"ל.\n<b>אך</b> הנה בהתיקון דאצי' נתתקנו ונתבררו הניצוצים דתה\"ו ע\"י ש' מ\"ה דתיקון עיקר המברר כל הברורים בהיות ש' מ\"ה הוא תכלית הביטול האמיתי שבו מלובש אור א\"ס ב\"ה בתוספת גילוי מאד לכך הוא עיקר המתקן עולם התיקון דאצי'",[["1156","12","<b>ראית איש חכם</b>: משלי כו, יב. וראה מאמרי אדה\"ז על מארז\"ל ע' רטז."],["1157","13","<b>שהחכמה אינו נרגשת אצלו</b>: ראה ג\"כ תו\"א קיא, א. לקו\"ת אחרי כז, ג. חוקת סו, ג. בלק סט, א. תו\"ח [הוצאת קה\"ת — תשס\"ג] בא קכה, ב. דרך מצותיך לא, ב. ועוד."],["1158","14","<b>דחכמה כח מה</b>: זח\"ג לד, א."],["1159","15","<b>חכמה שמאין תמצא</b>: איוב כח, יב."]]],[2100490268,"שיתייחדו כל הע\"ס דתיקון בהתכללות וחבור אמיתי ויתחלקו לבחי' קוי\"ן ימין ושמאל ואמצע והיינו כמשארז\"ל ע\"פ<sup data-n=\"1160\">16</sup> המשל ופחד עמו עושה שלום במרומיו וגו' בין מיכאל שר המים וגבריאל שר האש עושה השלום שאין מים מכבים אש וכו' וכמשנ\"ת בכמה מקומות שמצד תוספת גילוי עליהם בחי' עצמו' אור א'ס ב\"ה המרומם לבדו נתבטלו שניהם ומתחברי' ב' הפכיי' אלו כאחד ביחוד אמיתי ונעשה שלו' ביניהם כך באצי' במדו' חו\"ג שהם הפכיי' ומנגדי' זל\"ז שש' מ\"ה עשה השלום ביניהם להיותם נכללי' ומתחברי' כאחד מצד עוצם הביטול שלהם מפני ש' מ\"ה שבו מתגלה בתוספת ורבוי אור א\"ס ב\"ה לכך הם בלי מ\"ה ויתבטלו להתמזג במזג השוה בהתכללות אמיתי וכמ\"ש במ\"א ע\"ש.\n<b>והנה</b> ידוע סדר הברורין דש' מ\"ה דתיקון דאצי' הוא שתחלה נשפלת מדת מלכות דאצי', שכח בחי' ש' ב\"ן, דאצי' בחי' הדבור עליון בחי' תחתונה &lt;צג&gt;\nדאצי' שהיא ראש ומקור לבי\"ע לעולמות בי\"ע לברר הניצוצין דתה\"ו שנפלו לשם כמ\"ש ותקם<sup data-n=\"1161\">17</sup> בעוד לילה ותתן טר\"ף לביתה וגו' (טר\"ף הוא הברורין דרפ\"ח ניצוצין שרפ\"ח עם הכולל גי' טרף וכתיב מצמיח<sup data-n=\"1162\">18</sup> חציר לבהמ\"ה וגו' הוא בחי' בהמה<sup data-n=\"1163\">19</sup> רבה ש' ב\"ן דאצי' שגדלה לה אלף טורין ואכלה לון בכל יומא כמ\"ש בזהר פי' <sup data-n=\"1164\">20</sup>המה יוצר משרתים המלאכי' המתחדשי' בכל יום וחוזרים ומתבטלי' ונבלעי' במל' דאצי' בכל לילה כשנשפלת לבי\"ע ללקט הניצוצין שהמה נפעלי' ממעשה הברורי' דהניצוצין דתה\"ו שבבי\"ע ולכך נבלעים בה ונעשה מהם בה בחי' העלא' מ\"ן דא\"ח למעלה לז\"א בעלה דאצי' ואח\"כ נמשך המ\"ד דש' מ\"ה דז\"א דאצי' וכיון ששורה המ\"ד על המ\"ן המתבררין אז הוא עיקר הבירור שלהם שנכללים בקדושה ואלקות דאצי' דהיינו שאף בחי' המ\"ן דב\"ן נתהפך למהו' המ\"ד דמ\"ה דאצי' פי' שבהדרגת ההשתלשלות עילה ועלול אזי העלול למטה מהעילה שהוא המקבל השפע והעילה המשפיע לו אבל כיון ששורה המ\"ד של ש' מ\"ה על המ\"ן דב\"ן אזי נכלל ונתעלה בחי' המ\"ן דב\"ן שהוא העלול בעילתו ש' מ\"ה המברר וזהו כמ\"ש הולך<sup data-n=\"1165\">21</sup> עם חכמים יחכם שאף שלא היה חכם אך כיון שנתחבר לחכמי' ומתאביק בעפר רגלי חכמים והולך עמהם תמיד אזי יחכם גם הוא מהם ואעפ\"כ יש חילוק בין החכם עצמו למי שנתחבר ע\"י ההליכה עמהם שזה הרב המשפיע והוא התלמיד המקבל ממנו ואעפ\"י כן נק' ג\"כ חכם כך עד\"מ בהברורין דמ\"ן דב\"ן שנכללי' במ\"ד דמ\"ה להתהפך למהותו ואיכותו ממש מצד השראתו עליהם כי הולך עם חכמים",[["1160","16","<b>ע\"פ המשל ופחד עמו עושה שלום במרומיו</b>: איוב כה, ב. ראה במדבר רבה פי\"ב, ח. מאמרי אדה\"ז פרשיות התורה ח\"ב ע' תרמה ובהנסמן לשם. מאמרי אדה\"א קונטרסים ס\"ע שס, וש\"נ."],["1161","17","<b>ותקם בעוד לילה. . טרף הוא הבירורין. . שרפ\"ח. . גי' טרף</b>: משלי לא, טו. ראה ספר המאמרים תרס\"ג ע' נא בהערת כ\"ק אדמו\"ר שמציין: מק\"מ לזח\"ג ס, א. (וראה ג\"כ טעמי המצות להרח\"ו פ' משפטים). הוספות לתו\"א קי, א. וראה ג\"כ לקו\"ת אמור לו, ב.\nוראה גם פרי עץ חיים שער (טז) ק\"ש שעל המטה פ\"ה ומקבילו בשער הכוונות ענין דרושי הלילה דרוש ז. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרפה בשם הע\"ח. תקס\"ז ע' עד־ פרשיות התורה ח\"א ע' שנא [מקביל לתו\"א הנ\"ל]. ח\"ב ע' תרעא. מאמרי אדה\"א במדבר ח\"א ע' א. ח\"ג ע' תתקסה. אור התורה לך כרך ד ריש ע' תשכז."],["1162","18","<b>מצמיח חציר לבהמה</b>: תהלים קד, יד. סידור שחרית סב, ב."],["1163","19","<b>בהמה. . אלף טורין. . כמ\"ש בזהר</b>: ראה זהר בראשית יח, ב הנסמן במאמרי אדה\"א ויקרא ח\"א ע' יב."],["1164","20","<b>יוצר משרתים. . המלאכים</b>: ברכת יוצר. ראה איכה רבא פ\"ג, ח. טואו\"ח סנ\"ט. וראה לקו\"ת אמור לו, א. סידור סב, ב."],["1165","21","<b>הולך עם חכמים יחכם</b>: משלי יג, כ (ושם: את חכמים)."]]],[2100490269,"יחכם ובחכמה דייקא אתברירו כ\"ח מ\"ה דאצי' כו' כנ\"ל וד\"ל.\n<b>וז\"ס</b> מיעוט הירח<sup data-n=\"1166\">22</sup> שא\"ל הקב\"ה לכי ומעטי את עצמך, להיותה נשפלת לבי\"ע להיות ראש לשועלים שאזי מצטרך להתמעט אורה להיות נשפל לבי\"ע בחי' תחתונה שבמל' דאצי' מה דלא סגי בלא\"ה שאם יתגלה תוספ' הארתה בבי\"ע אזי לא יוכלו הנבראים לקבלו ויתבטלו במציאות ממש לחזור לאין ואפס כמקודם (כמאמ' הושיט<sup data-n=\"1167\">23</sup> אצבעו הקטנ\"ה ביניהם ושרפם כו') שעיקר ירידתה לבי\"ע בכדי לברר הניצוצין דתה\"ו שנפלו לבי\"ע כנ\"ל. ולכאורה יפלא פליאה דעת אל כל המעיין בספרי הקבלה בכ'<sup data-n=\"1168\">24</sup> אריז\"ל בע\"ח ופרע\"ח שנת' הכל שעיקר המברר כל הברורין הוא המ\"ד דש' מ\"ה דאצי' דייקא כי בחכמ\"ה אתברירו כנ\"ל ונת\"ל שמל' דאצי' שהיא בחי' ב\"ן דאצי' נשפלת בבי\"ע לברר ברורין וכנ\"ל.\n<b>אך</b> באמת אין זה סתירה כלל שבודאי עיקר המברר הוא שם מ\"ה דאצי' שמברר המ\"ן דב\"ן דאצי' כנ\"ל אך לצורך התהוות המ\"ן דב\"ן מהניצוצין דתהו שנפלו לבי\"ע מוכרחים להתברר ע\"י מל' דאצי' המשפילי בבי\"ע ולא בכח עצמה דלית לה מגרמה כלום בלתי מה שמקבלת משמשא הוא ש' מ\"ה דאצי' המאיר הארתו בהיר\"ח לתת בה כח המברר לברר הניצוצין המובלעים בבי\"ע שיהיו נבלעים בה להיות נעשה בה מהן בחי' העלא' מ\"ן וא\"ח למעלה &lt;צד&gt;\nואז ישרה עליהם המ\"ד דמ\"ה אז דוקא יהי' הגמר של הברור שלהם כי זה שנתבררו ע\"י מל' דאצי' להיות נעשה מהם בחי' העלא' מ\"ן אין זה תכלית שלימו' הבירור עד שישרה המ\"ד עליהם דוקא וכנ\"ל וד\"ל.\n<b>וביאור</b> הענין באר היטב ההפרש בין ב' בחי' הברורין אלו דמל' דאצי' המשפילי בבי\"ע לברר בכח הארת ש' מ\"ה שבה שנעשה מהן בחי' העלאו' מ\"ן ובין הבירור דמ\"ד דמ\"ה השורה על המ\"ן הזה דב\"ן שאז תכלית שלימות הברור כנ\"ל.\n<b>יובן</b> בפשיטות מבחי' ומדרגת משה רע\"ה ובחי' ומדרגת אליהו הנביא ז\"ל להבין ההפרש וההבדל שביניהם דהנה הגם שמעלת ומדרגת מרע\"ה עולה על כולם אשר לא<sup data-n=\"1169\">25</sup> קם כמוהו עוד נביא בישראל אשר ידעו ה' פנים אל פני\"ם כו' שהי' בחי'",[["1166","22","<b>מיעוט הירח שא\"ל הקב\"ה</b>: חולין ס, ב. ראה ביאוה\"ז אחרי עז, ב ואילך. מאמרי אדה\"ז על מאמרז\"ל ע' רכא. סה\"מ תקס\"ה ח\"ב ע' תקצד ואילך."],["1167","23","<b>הושיט אצבעו הקטנה</b>: סנהדרין לח, ב."],["1168","24","<b>בכ' אריז\"ל בע\"ח ופרע\"ח שנת'</b>: ראה פע\"ח (שער התפלה) ש\"א פ\"ז. מאמרי אדה\"א קונטרסים ס\"ע תקמג ואילך. וש\"נ."],["1169","25","<b>לא קם כמוהו עוד נביא בישראל</b>: ראה ברכה לד, י."]]],[2100490270,"ומדרגת מ\"ה שלמעלה כמ\"ש בעצמו בתורה ונחנו<sup data-n=\"1170\">26</sup> מ\"ה וגו' אעפ\"כ ימצא מעלה יתירה בבחי' ומדרגות אליהו דהיינו שבחי' אלי\"ה<sup data-n=\"1171\">27</sup> הוא מבחי' חיצוניו' שנק' מלא\"ך הברית כנודע אך החצוניו' נשפל למטה מאד במורד עד שנתפשט בחי' הביטול שלו בגוף שלו ממש עד שהי' משוטט בארץ לפרוח באויר כמ\"ש ויאמר<sup data-n=\"1172\">28</sup> ה' אליו קום לך צרפתה כו' והי' חגור באדרת שער כו' שזה מורה על בחי' מציאות הביטול שהי' נגלה בגוף שלו ממש (ולכך עלה<sup data-n=\"1173\">29</sup> בסערה השמים עם הגוף והוא מפני ששרשו מבחי' חיצוניות שלמעלה שיוכל להתפשט מאד במורד למטה שאף בבחי' חיצוניי' הגוף יתפשט ויתגלה בחי' מציאות הביטול שלו כנ\"ל משא\"כ משה רע\"ה ששרשו מבחי' הפנימיות שלמעלה שאמר ונחנו מ\"ה (הכתוב ומפורש בתורה ממש והוא תורה ממש) אבל בהגוף<sup data-n=\"1174\">30</sup> שלו לא הי' באפשר להתפשט כ\"כ מציאות הביטול זה כמו שהי' מתפשט באליה\"ו והיינו מפני שמצד שהי' מבחי' הפנימיות לא הי' יכול לישפל בחצוניו' וכמה שהעיד בעצמו כי כבד<sup data-n=\"1175\">31</sup> פה וכבד לשון אנכי וכו' זולתי בהיותו בהר מ' יום ולילה לילה ויום אז בלבד הי' מתגלה הביטול אף בחצוניו' הגוף שלו כנודע, נמצא לא ראי זה כראי זה שיש מעלה יתירה במשה שהוא מבחי' הפנימיו' הגבה למעלה משרשו של אליהו שבזה נאמר ולא קם עוד נביא כו' ויש מעלה יתירה באליהו שנתפשט בחי' מציאו' הביטול שלו בחצוניו' גופו ממש להיותו פורח באויר להיותו מלאך ממש ולכך עלה בסערה השמים וכלא חדא מילתא דהא בהא תלי' כנ\"ל וד\"ל.\n<b>((מפה\"ש</b><sup data-n=\"1176\">*31</sup> ) והנה ההפרש הזאת הוא ג\"כ בין מלאכים ונשמות שהנשמו' הם מפנימיו' והמלאכי' מחצוני' ואעפ\"י שהנשמו' גבוהי' יותר מן המלאכים מטעם זה אעפ\"כ ימצא מעלה יתירה בהמלאכים שנתפשט בחי' הביטול בחיצוני' הכלי' שלהם יותר כמו באליהו ז\"ל כנ\"ל ולכך נאמ' והאיש<sup data-n=\"1177\">32</sup> משה עניו מאד מכל האד\"ם אשר ע\"פ האדמה ודרשו רז\"ל<sup data-n=\"1178\">33</sup> מזה יכול אפי' ממלאכי השרת ת\"ל מכל האדם אשר ע\"פ האדמה דייקא פי' כי במלאכי' עליונים ימצא מעלה יתירה באופן אחד בבחי' העניוות והביטול המתפשט בחיצוניו' הכלים יותר משא\"כ בחי' משה רע\"ה שהוא בפנימיות &lt;צה&gt;\nבלבד ולכך נאמ' שהוא עניו מאד מכל האדם אשר ע\"פ האדמה הם הנשמו' ששרשן ג\"כ מפנימיו' אבל לא ממה\"ש כו' וכנ\"ל (עד כאן מפה\"ש ששמע מפ\"ק שי').",[["1170","26","<b>ונחנו מה</b>: בשלח טז, ז-ח. ראה סידור שחרית סג, ד. מאמרי אדה\"א ויקרא ח\"א ע' מא. שמות ח\"ב ע' שלא, וש\"נ."],["1171","27","<b>אליה. . שנק' מלאך הברית כנודע</b>: מלאכי ג, א. פדר\"א פכ\"ט. ילקוט שמעוני יהושע רמז טו. וראה זח\"ג יג, א. צג, א. רט, ב ועוד (וראה גם ספה\"מ תקס\"ה ח\"ב ע' תתקנה ואילך)."],["1172","28","<b>ויאמר ה' אליו קום לך צרפתה</b>: מלכים-א יז, ט. וראה מאמרי אדה\"ז ענינים ע' קד."],["1173","29","<b>עלה בסערה השמים</b>: ראה מאמרי אדה\"א קונטרסים ע' שעב, וש\"נ."],["1174","30","<b>בהגוף שלו. . כמו שהי' מתפשט באליהו</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תקנד וש\"נ. דרושי חתונה ח\"א ע' קיד."],["1175","31","<b>כבד פה וכבד לשון אנכי</b>: שמות ד, יוד."],["1176","*31","<b>מפה\"ש</b>: מפי השמועה."],["1177","32","<b>והאיש משה</b>: בהעלותך יב, ג."],["1178","33","<b>ודרשו רז\"ל</b>: ראה ספרי בהעלותך יב, ג."]]],[2100490271,"<b>וככה</b> ממש עד\"מ למעלה ההפרש בין בחי' המ\"ד דמ\"ה עצמו המברר את המ\"ן דב\"ן שמאחד של המתבררין ובין הארת ש' מ\"ה שבב\"ן שנותן בו כח והארתו לברר הניצוצין דבי\"ע כשנעשה ראש לשועלים כו' והיינו שהמ\"ד דמ\"ה הוא עיקר המברר שמברר את המ\"ן דב\"ן שהוא בחי' הבירור בבחי' הפנימיות ואלקות דאצי' ממש בהיות אף המ\"ן דב\"ן טרם השראת המ\"ד עליו הוא ג\"כ בחי' קדושה ואלקות ממש רק שאינו כמהו' תכלית הביטול דמ\"ד דמ\"ה עד שישרה עליו שעי\"ז יתברר ויתכלל בו להתהפך למהותו ואיכותו של המ\"ד דמ\"ה שהוא תכלית הביטול האמיתי דאצי' שאין זה חדוש כ\"כ שיתברר בחי' אלקות ממש מיש דמ\"ן דב\"ן לאי\"ן דמ\"ד דמ\"ה כמ\"ש אלה המלכים כו' מלכין קדמאין דתה\"ו שמתו ונשברו ונפלו לב\"ן דאצי' ונתבררי' ע\"י ש' מ\"ה דאצי' שכולם הם בחי' אלקות בחי' תה\"ו ותיקון והבירור הוא בפנימיות אלקות עצמו להתהפך ממ\"ן דב\"ן שנחשב לבחי' יש ודבר מה נגד מ\"ד דמ\"ה למהו' תכלית הביטול דמ\"ה, אבל זהו עיקר החדוש של הבירור חיצוני' דב\"ן דאצי' שנעשה ראש לשועלים דבי\"ע לברר הניצוצין דתה\"ו שבבי\"ע להיותם מתעלים ונכללי' בש' ב\"ן הוא מל' דאצי' שיתהפך ממהות המלאך הנברא ומחודש מאין ליש נפרד לבחי' אלקות ממש להיות נעשה מהמתבררין אלו בחי' ההעלאו' מ\"ן בנוק' דאצי' שאף גם זאת הוא ע\"י הארת ש' מ\"ה דאצי' בו לתת בו כח לברר אך מחמת שזהו הבירור בחיצוניות עולמות להתהפך הנברא היש נפרד לאלקות ממש לכך נמצא בו מעלה יתירה הגם שהוא למטה בערך מבחי' הבירור העיקרי דש' מ\"ה עצמו שבאצי' שהוא הגבה למעלה מאד נעלה בבחי' הפנימיו' אעפ\"כ בזאת ימצא מעלה יתירה בברור החצוני' דמל' דאצי' מצד ההתהפכו' של החצוני' לאלקות שמזה יקר מאד בעיני ה' מאד נעלה וה\"ז ממש כמו משה ואליהו הגם שמשה אדון הנביאים לא קם כמוהו עוד במעלת הביטול הפנימיי דמ\"ה כמ\"ש ונחנו מ\"ה אעפ\"כ ימצא מעלה יתירה באליהו שנתפשט הארת הביטול בחיצוני' הגוף עד שהי' פורח באויר (וכמארז\"ל שהי' אומר ש' בן י\"ב אותיות כו' וכי אחרים לא ידעו ש' זה אלא הענין כנ\"ל) כו' וד\"ל.\n<b>והנה</b> נת\"ל<sup data-n=\"1179\">34</sup> בדרוש דאב\"ק ועפר שהתהוות הקליפות הוא מהסיגים והפסולת של הכלים דתה\"ו שנפלו דרך שבירה לבי\"ע שהטוב שבהן מתברר ונכלל בקדושה דהיינו מה שאפשר להתברר ולהתכלל באצי' נכלל באצי' ומה שא\"א להתברר באצי' מתברר בבריאה כו' עד עולם העשי' שהוא עולם השפל תכלי' כל סדרי ההשתלשלו' כולן שמל' שבקליפה דעשי' היא נק' בחי' אב\"ק דאשתארת מן נורא שכמו האבק ואפר הכירה שנשרף באש כל היסודו' המעולי' ונסתלקו למקורם ונשאר רק יסוד העפר ואפר עד שאין בו כח עוד &lt;צו&gt;\nאפי' להצמיח כלל כך בחי' מל' דקליפה דעשי' שנתברר ממנה כל הטוב בתכלית ההתבררות ונשארה כמצולה שאין בה דגים רק רע גמור גשמיי ואעפ\"כ מוכרח להיות בה מעט טוב בשביל שתתקיים כדי חיונה כנ\"ל וממנה נסתעפי' הע' שרים דקליפה שהמה רע גמור ובחי' יש נפרד",[["1179","34","<b>נת\"ל בדרוש דאבק ועפר</b>: ראה לעיל ע' קסד ואילך."]]],[2100490272,"ממש רק דקרו<sup data-n=\"1180\">35</sup> לי' אלהא דאלהא כי רם<sup data-n=\"1181\">36</sup> על כל גוים ה' ושונאים את ישראל מחמת הקנאה שרואים איך ישראל חשובים בההוא עלמא ויקרי' בעיני ה' כו' ולזאת אש הקנאה תבער בהם על ישראל ואלמלא ניתן רשות לא הי' יכולי' לעמוד מפניהם אך אין בהם כח ויכולת לעבור פי ה' לעשות מאומה בלתי רשות, וכל המחשבות רעות וגזרות רעות אשר חושבי' העמים על ישראל להרע נשפע הכל מהשר שלהם כמ\"ש בזוהר<sup data-n=\"1182\">37</sup> ע\"פ ויאמר אל עמו הבה נתחכמה לו כו' ויאמר סתם מאן אמר דא שרו של מצרים דאעיל מחשבה דא בלבהון כו' שכל המחשבות נשפע להם מהשר שלהם ואלמלא שמכריזין עליו מלמעלה הזהר כו' הי' פועל רעות יותר כמ\"ש בת\"ז<sup data-n=\"1183\">38</sup> שאומרים לס\"ם ירא בוש\"ת ירא שמי\"ם זהו בראשי\"ת כו' נמצא הע' שרים דקליפה דעשי' הם רע גשמיי גמור אך הע' שרים דקליפה דיצירה אינו רע גמור גשמיי כאלו שהם מעורבים טו\"ר והם בדקות ורוחניות יותר והיינו כמארז\"ל שט\"ן<sup data-n=\"1184\">39</sup> ופנינה לש\"ש נתכוונו ודרשה ר' אחא בפפוניא אתא שט\"ן ונשקי' לכרעי' כו' ולפעמים נאמר בדרז\"ל בשט\"ן<sup data-n=\"1185\">40</sup> שנתן עיניו במקדש ראשון כו' ושניהם אמת<sup data-n=\"1186\">41</sup> שהשט\"ן דיצירה אינו פועל רע גמור מצד הקנאה והשנאה אף שהוא ג\"כ מקטרג על ישראל אך הוא מעט בדקות יותר שכונתו לש\"ש אבל השט\"ן דעשי' הוא פועל רע מצד הקנאה והשנאה ממש וזהו נתן עיניו במקדש ראשון מצד הקנאה בלבד וד\"ל.\n<b>והנה</b> כתיב כי תצא<sup data-n=\"1187\">42</sup> למלחמה על אויבך ושבית שביו וגו' פי' דכאשר נשפלת מדת מלכות דאצי' לבי\"ע לברר ברורין כמ\"ש ותקם<sup data-n=\"1188\">43</sup> בעוד לילה ותתן טר\"ף לביתה וגו' שמצטרכת לברר הטוב שבניצוצין דתה\"ו מן הרע דקליפות דבי\"ע שנבלעו בהם אזי הוא מלחמה עצומה כמשל מלחמת שני מלכי' אויבי' זל\"ז שלפעמי' מתגבר זה ומנצח המלחמה ולפעמי' להיפך אך אפי' כשהאחד גובר ומנצח המלחמה לפטור בלא כלום א\"א שאעפ\"כ מוכרח להיות נחסר ממנו אנשי' או ש\"ד שלוקח שונאו במלחמה כו' כך ממש עד\"מ למעלה כשמל' דאצי' נשפלת לבי\"ע לברר הטוב מן הרע וקליפות שנבלע בהם אזי הוא מלחמה עצומה בין סט' דקדושה לסט\"א וכמ\"ש ביעקב אע\"ה ויאבק איש עמו כל הלילה כו' כנ\"ל. אך אפי' כשגובר סט' דקדושה אעפ\"כ מוכרח להינתן להם ג\"כ בחי' הפסולת והסיגי' בחי' החיצוניות והאחוריי' שיאחזו בהם וינקו מהם ועי\"ז חוטפי' מהם בחי' הטוב הפנימיות להעלות לקדושה ממש וזהו ושבית שביו כו', וזהו ענין פגימת הלבנה שמקום החשך שבה שאין מאיר לשם אור השמש הוא המקום שנתן להחיצוני' לינק בשעת המלחמה",[["1180","35","<b>דקרו לי' אלהא דאלהא</b>: מנחות בסופה."],["1181","36","<b>רם על כל גוים ה'</b>: תהלים קיג, ד."],["1182","37","<b>בזוהר ע\"פ ויאמר אל עמו</b>: ראה זהר שמות יז, א."],["1183","38","<b>בת\"ז. . ירא בשת</b>: ראה ת\"ז בהקדמה (ה, ב). תכ\"ח."],["1184","39","<b>שטן ופנינה לש\"ש נתכוונו</b>: ב\"ב טז, א. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תעו. וש\"נ."],["1185","40","<b>בשטן שנתן עיניו במקדש ראשון</b>: סוכה נב, סע\"א. ראה מאמרי אדה\"א בראשית ע' צח וש\"נ."],["1186","41","<b>ושניהם אמת</b>: ראה ג\"כ לקו\"ת חקת סב, א. מטות פז, א. מסעי צב, א. תורת חיים נח נא, א. תולדות קנז, ב."],["1187","42","<b>כי תצא למלחמה על אויבך</b>: דברים כ, א."],["1188","43","<b>ותקם בעוד לילה</b>: משלי לא, טו."]]],[2100490273,"כשנתמעטה הירח להשפיל א\"ע לבי\"ע לברר הטוב הפנימיות מהן דלא סגי בלא\"ה עד שתינתן להם הפסולת והחיצוניות כנ\"ל וכדכתי' קץ<sup data-n=\"1189\">44</sup> &lt;צז&gt;\nשם לחשך וגו' דהיינו מה שניתן להם מקום החשך בהלבנה לינק משם שזהו רק באחורי עור דנוק' כנודע וכדכתי' עת<sup data-n=\"1190\">45</sup> אשר שלט האדם באדם לרע לו ממש שזה שניתן השליטה להחיצונים שינקו מאחוריי' והחיצוניות שבלבנה הוא לרע לו בכדי שיתברר הטוב הפנימי מהם מה דלא סגי בלא\"ה כנ\"ל, וכן למטה בגשמיות בזמן הגלות כשניתן להם שליטה וממשלה לא ניתן להם לשלוט רק על החיצוניות והפסולת כמו שהראו למשה במיכה שמעכו בבנין שעשה אח\"כ פסל מיכה וכו' וכן בבהמ\"ק שפך<sup data-n=\"1191\">46</sup> חמתו על עצים ואבנים כו'.\n<b>והענין</b> דהנה ארז\"ל בא<sup data-n=\"1192\">47</sup> נחש על חוה והטיל בה זוהמא כו' פי' שהשליטה של החיצוני' שניתן להם הוא רק בחיצוניו' הלבושי' שלמעלה שיתלבשו הם בהם ויטילו זוהמא כו' אבל בעצמות הכלי' והאורות דקדושה אין להם שליטה כלל, ואף גם זאת השליטה תלוי (באופן) מצד אופן ההשפעה העליונה במל' דאצי' שאם מקבלת מאותיות פל\"א שהם החסדים שלמעלה אזי אין להם מקום לשלוט כלל אך כאשר מל' דאצי' מקבלת מק\"ך צירופי (אותיות) אלקי' שהם מבחי' הגבורו' שהוא שרש החיצונים אזי יכולי' החיצונים לשלוט בהלבושי' דקדושה שזה הכח ניתן להם מצד מקורם כנ\"ל, וכ\"ז תלוי במעשה התחתונים כנ\"ל.\n<b>אך</b> בר\"ח במולד הלבנה שנתחדשה מחדש ע\"י עלותה לאצי' למלאות הפגימה שאז זמן עליות העולמות שעולין הנשמות מג\"ע התחתון לג\"ע העליון כמ\"ש והי'<sup data-n=\"1193\">48</sup> מדי חדש בחדשו וגו' אזי היו מקריבין ע\"ז קרבן מוסף ושעיר דר\"ח אמר<sup data-n=\"1194\">49</sup> הקב\"ה הביאו עלי כפרה ע\"ש שמעטתי את הירח כו', אך הנשמות הנולדי' מבטן הנוק' דאצי' שנשפעי' אלי' מז\"א דאצי' בזמן פגימת הלבנה אזי בכל אינון אתרין דמטון כו' אתברו ואתפגימו בכמה כאבין וצערין כו' פי' בהיות בכל נשמה ימצא בחי' לבושיה שנולדי' עמה משעת יציאת' מבטן הנוק' דלעילא ולכך מאחר שנולדה בזמן פגימת הלבנה לזאת החצוני' שולטי' בהלבושי' של הנשמה להיותה סובלת יסורי צער בכל עולם מעולם ועד עולם דרך הילוכה והמשכתה למטה מדי עברה דרך הלבושי' שלמעלה ניתן בעת ההיא מקום להחיצונים לשלוט כנ\"ל וכן למטה כשמתלבשת בגוף אזי הגוף שלה סובל יסורי צער אבל לא הנשמה שנמשכה מהפנימיות דקדושה שאין להם שליטה אף בזמנא דאתפגי' סהרא זולתי בהאחוריי' והחיצוניות בהכלי' בלבד כנ\"ל לכך סובלת יסורי הגוף בלבד כגוונא דלעילא כנ\"ל וד\"ל.\n<b>ובזה</b> יובן בפשיטות למה נסמכה ענין זה לפתיחת בעל המאמר שפתח בפ' אך אל הפרוכת לא יבא כו' וסיי' בענין זה כו' אך הענין הוא בהיות הכהן בעל מום",[["1189","44","<b>קץ שם לחושך</b>: איוב כח, ג."],["1190","45","<b>עת אשר שלט האדם באדם</b>: קהלת ח, ט."],["1191","46","<b>שפך חמתו על עצים ואבנים</b>: ראה איכ\"ר פ\"ד, יד וש\"נ."],["1192","47","<b>בא נחש על חוה</b>: שבת קמו, א."],["1193","48","<b>והי' מידי חדש בחדשו</b>: ישעי' סו, כג."],["1194","49","<b>אמר הקב\"ה הביאו עלי כפרה</b>: ראה חולין ס, ב."]]],[2100490274,"זהו ב' הפכי' ממש ששרשו<sup data-n=\"1195\">50</sup> של הכהן הוא מהחסדי' שלמעלה ובעל מום הוא מצד הגבור' שסובל יסורי', אך זהו בחי' הולדת הנשמה בזמנא דאתפגמת סיהרא שאז החיצונים שולטי' בהחיצוניו' והלבושי' &lt;צח&gt;\nולא בהפנימיות לכך בפנימיו' הוא כהן היינו בחי' נשמתו עצמה הגבה למעלה משרש החסדי' שלמעלה רק בהחיצוניות גופו סובל יסורי' שהוא בעל מום יבלת ודומיהן שזה מצד שליטת החיצונים על גופו, ולכך נאמר לחם הקדשי\"ם יאכל מצד שהלח\"ם הוא מן הקדשי' שהוא בחי' פנימיות בינה דאצי' עלמא דחירו שאין להם יניקה מהפנימיות כלל כנ\"ל לכך יאכל אך אל הפרוכת לא יבא עם המו\"ם להעלות המו\"ם של החיצונים ששולטי' על גופו לא יבא עמו אל הפנימיות דקדושה כו' אבל לחם הקדשי' שנימשך מפנימיות לחיצוניות אליו יאכל וד\"ל.",[["1195","50","<b>ששרשו של הכהן הוא מהחסדי'</b>: ראה זהר נשא קמה, ב. צו כז, א."]]],[2100490275,"<h3>ענין מצות פדיון הבן</h3>\n<b>בעזר\"ה על פדיון הבן</b>\n<b>ענין</b><sup data-n=\"1196\">1</sup> מצות פדיון הבן, כתיב קדש<sup data-n=\"1197\">2</sup> לי כל בכור כו', הנה יש להבין הטעם למצוה זו דפדיון הבן בבכור דוקא, אם משום דהבכורות נקדשו לה' בהיותם במצרים מה זה הטעם שנתנם<sup data-n=\"1198\">3</sup> לכהנים דוקא עד שצריך פדיון, וגם מה מועיל הפדיון בה' סלעים כסף כו', ועוד היא גופא קשי' למה נקדשו הבכורות דוקא במצרים הגם שמפרש בכתוב הטעם הפשוט משום<sup data-n=\"1199\">4</sup> מכות בכורות דמצרים גם זה אינו מובן למה במכה זאת דוקא הוא שגילה הטעם להקדיש בכורות בני ישראל.\n<b>אך</b> הנה הענין הוא דבחי' הבכור<sup data-n=\"1200\">5</sup> הוא בחכ' כידוע, ושרש<sup data-n=\"1201\">6</sup> הכהנים בבחי' החכמה ג\"כ ע\"כ צריך פדיון הבכור מיד הכהנים בה' כסף דוקא שהן ה' חסדים משום דכהן<sup data-n=\"1202\">7</sup> שרשו בחסד שבחכ' כו'.",[["1196","1","<b>ענין מצות פדיון הבן</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מכת\"י 1156 פו, א. נמצא ג\"כ בכת\"י 68 לה, ב. ושם בסוף המאמר רשום: מוגה מגוף כי\"ק אדמו\"ר נבג\"מ. נמצא ג\"כ בכת\"י 207 נד, א. (ושם: מאדמו\"ר הזקן מהרש\"ז נבג\"מ). 184 תכט, א. 448 תעה, ב. 665 קפח, א. 794 מח, ב. 898 (ושם בראש העמוד הנחת ר\"ה פה\"ב). וראה בפתח דבר מכ\"ק אדמו\"ר זי\"ע לדרך מצותיך ע' (וכנראה שם הכוונה למאמר אחר).\nנדפס ג\"כ במאמרי אדה\"ז על פרשיות התורה ע' רנב. (ושם לא נעתק מכת\"י 68 אלא מכת\"י 207).\nהנחת ר' משה בן אדה\"ז נדפס לקמן ע' רא. בכותרת: יום א' ערב חנוכה (בסעודה מצוה בפדיון הבן הנ\"ל). ובהתחלה: ”וידבר ה' אל משה. . קדש לי כל בכור."],["1197","2","<b>קדש לי כל בכור</b>: בא יג, ב."],["1198","3","<b>שנתנם לכהנים. . כסף</b>: ראה קרח יח, טו-טז."],["1199","4","<b>משום מכת בכורות</b>: בא יג, טו."],["1200","5","<b>הבכור הוא בחכמה</b>: ראה פרדס שער (כ\"ג) ערכי הכינויים מערכת בכור."],["1201","6","<b>ושורש הכהנים בבחי' חכמה</b>: ראה לקו\"ת תזריע כג, ב."],["1202","7","<b>דכהן שרשו בחסד</b>: ראה פרדס שער (כ\"ג) ערכי הכינויים מערכת כהן. זהר נשא קמה, ב. מערכת האלקות פ\"ד (נט, א). אגה\"ק סי\"ב (קיח, א)."]]],[2100490276,"<b>ולהבין</b> זה וגם איך יתכן לפדות החכ' דבכור בחסדים שהם למטה מן החכ' שהרי החסד<sup data-n=\"1203\">8</sup> הוא ענף החכ' בלבד כידוע.\n<b>אמנם</b> הנה יש להקדים תחלה שיש ג' קווין דחח\"ן<sup data-n=\"1204\">9</sup> קן הימין בג\"ה קו השמאל וקו האמצעי הוא דת\"י והוא הנק' ישראל<sup data-n=\"1205\">10</sup><sup data-n=\"1206\">11</sup> ישר אל וגם נק'<sup data-n=\"1207\">12</sup> ישורון כו' ובזהר<sup data-n=\"1208\">13</sup> נק' עמודא דאמצעיתא כו', והנה ידוע דהג' קווין הללו הן נרמזים ג\"כ בציור המנורה, דהנר אמצעי הוא נגד קו האמצעי וכתוב בי' אל<sup data-n=\"1209\">14</sup> מול פני המנורה יאירו כו', והענין הוא דכמו שהנר<sup data-n=\"1210\">15</sup> האמצעי<sup data-n=\"1211\">16</sup> ממנו יאירו כולם ומקבלים כולם כו', כך מבחי' קו האמצעי מקבלים כולם, מפני ששרש קו האמצעי עולה עד הכתר וידוע דבחי' הכתר עולה ע\"ג הג' קוין מלמעלה והוא נבדל מכולם בערך להיותו בחי' המקור והשרש של כל ההשתלשלות וכולל את הכל.\n<b>אך</b> הנה הקו האמצעי מגיע עד בחי' הכתר מה שאין ביכולת הב' קווין חח\"ן ובג\"ה להגיע לשם וע\"כ נק' בריח התיכון המבריח מן הקצה להקצה פי' מן הקצה היותר עליון שבבחי' הכתר שאין הקווין מגיעין לשם כלל והוא בחי' פנימיות הכתר כידוע בפרדס וזהו אל מול פני המנורה כו' פי' מול בחי' פנימיות הכתר שמשם נמשך ויורד לקו אמצעי הנק' דת\"י ומשם יאירו כל הפרטיו' או\"כ הנאצלים לימין ולשמאל כמו חח\"ן מימין ובג\"ה משמאל כו' וד\"ל.\n<b>וזהו</b> שארז\"ל ישראל עלה במח' פי' ישראל הוא ישר אל דהיינו בחי' קו האמצעי דת\"י כנ\"ל ולהיות עולה עד בחי' פנימי' הכתר כנ\"ל ע\"כ אמרו דישראל<sup data-n=\"1212\">17</sup> זה עבמ\"ח. כלומר עלה למעלה מעלה בבחי' פנימיות החכ' שבכתר והוא הנק' ח\"ס דא\"א כידוע שזה פי' במח' כלומר במח\"ס כו' והיינו עמב\"ח וד\"ל.\n<b>והנה</b> הכהן שרשו מבחי' קו הימין דהיינו חח\"ן, והרי ידוע דהחכ' מאין תמצא היינו מבחי' אין דכתר מפני שהכתר<sup data-n=\"1213\">18</sup> נק' אין כידוע, וכדי שיומשך אור החכ' מאין ליש ה\"ז בהכרח ע\"י צמצום וגבורות כדרך כל השתלשלות מאין ליש כידוע, ואמנם זהו דוקא בהכהנים כמו שהי' תחלה קודם שנמשח אהרן לכהן גדול וזרעו אחריו והובדלו כל אחיו הכהנים בקדושה יתירה כמבואר בכתוב, אבל אחר שהובדלו",[["1203","8","<b>החסד הוא ענף החכמה</b>: ראה זהר ואתחנן רסב, ט. לך צד, א. תרומה קעה, ב."],["1204","9","<b>חח\"ן. . בג\"ה. . דת\"י</b>: ראה פרדס שער (ו) סדר עמידתן פ\"א."],["1205","10","<b>וקו האמצעי. . הנק' ישראל</b>: ראה אוה\"ת בשלח ע' שנה."],["1206","11","<b>ישראל ישר אל</b>: ראה ר\"מ בוטריל לספר יצירה פ\"א, מ\"א (טו, א). רמ\"ז ר\"פ שמיני. סה\"מ תקס\"ד ע' קפא. אוה\"ת משפטים ע' א'שטז."],["1207","12","<b>נק' ישורון</b>: ראה אוה\"ת ברכה ע' א'תתעב. במדבר ע' לז."],["1208","13","<b>ובזהר</b>: רע\"מ תשא קפז, ב."],["1209","14","<b>אל מול פני המנורה</b>: בהעלותך ח, ב."],["1210","15","<b>שהנר האמצעי. . קו האמצעי</b>: זהר שמות יד, ב. אוה\"ת בהעלותך ע' שכה."],["1211","16","<b>האמצעי. . כולם</b>: ראה שבת כב, ב וברש\"י שם."],["1212","17","<b>דישראל זה עבמ\"ח</b>: ראה ב\"ר פ\"א, ד. לקו\"ת שה\"ש יט, ב."],["1213","18","<b>שהכתר נק' אין</b>: פרדס שער (כג) ערכי הכינויים מערכת אין."]]],[2100490277,"הכהנים בקדושה יתירה כמבואר בכתוב הנה עיקר סיבת יתרון זה הוא דוקא במה שהשמן המשחה נמשך על ראש אהרן ובניו כו' והוא אשר הוריד האור והשפע קדושה יתירה לאהרן ובניו וכמ\"ש כשמן<sup data-n=\"1214\">19</sup> הטוב היורד על הראש כו', ואז ניתן לאהרן ובניו כל ראשית בישראל כמ\"ש כל<sup data-n=\"1215\">20</sup> ראשית בישראל לך יהי' כו' ובחי' ראשית ידוע שהוא בחי' החכ' שנק' ראשית וכמ\"ש בראשית<sup data-n=\"1216\">21</sup> ברא ותרגומו בחוכמתא כו' והיינו שנמשך להם אור החכ' מאין דכתר שלא ע\"י גבורות וצמצומים אלא ע\"י בחי' רב טוב וחסד העליון הנק' ונוצר חסד וכמ\"ש בזהר דבהאי<sup data-n=\"1217\">22</sup> חסד בי' אחיד אור אבא כו' והוא ע\"י בחי' שמן הטוב שנמשח בו אהרן ובניו כו' וד\"ל. ואחר שניתן לכהנים כל בחי' ראשית שבישראל הרי חסר לישראל בחי' החכ' שנק' ראשית מצד עצמם אלא ע\"י שיקבלו מן הכהנים דוקא, ולזאת הוא עיקר טעם מצות פדיון בן הבכור.\n<b>דהנה</b> כל הבכור בישראל הוא בחי' החכ' כנ\"ל והרי אנו אומרים ובכורך<sup data-n=\"1218\">23</sup> ישראל גאלת ר\"ל שצריך לגאול בכור שבישראל מיד הכהנים ע\"י פדיון ה' כסף דוקא לפי שכבר ניתן החכ' כולה ביד הכהנים מטעם הנ\"ל, ובכדי להמשיך בחי' החכ' גם לישראל צריך לפדות בחי' החכ' מן הכהנים ע\"י ה' סלעים והוא בחי' ה' חסדים שנותנים להם בחילוף החכ' כדרך כל פדיי' שבעבור הדבר הנפדה הוא שנותן הפודה את הכסף, כך בעבור בחי' החכ' הנפדית מן הכהני' נותנים להם בחילוף זה ה' החסדים, וענין ה' חסדים הללו הוא דבר ומדריגה שאין ביכולת הכהנים להשיגם ובהכרח שיקבלו זה מישראל דוקא<sup data-n=\"e29\">*</sup>, להיות כי ישראל הוא בחי' קו האמצעי ומבואר למעלה דקו האמצעי עולה עד הכתר בבחי' פנימיו' דוקא ע\"כ ביכולת ישראל דוקא להמשיך בחי' פנימי' ה' החסדים שבכתר שהן הנמשכים בקו האמצעי דוקא כידוע בע\"ח והן הגבה מאד נעלה מן בחי' החסד שבחח\"נ ששרשו מן החסד המצומצם במזל ונוצר חסד שממנו מקבלים הכהנים כנ\"ל והוא הנק' ורב חסד כו', ובחילוף זה נוטלים מן הכהנים בחי' החכ' שכבר קיבלו מישראל בהנתן להם כל ראשית כנ\"ל וזהו כללות ענין מצות פדיון הבן וד\"ל.\n<b>וזהו</b> קדש לי כל בכור כו', כי בגלות מצרים הי' בחי' עיבור<sup data-n=\"1219\">24</sup> דז\"א במעי אימא כידוע, וכשיצאו ממצרים הי' בחי' הלידה וכמ\"ש ביחזקאל ומולודתיך<sup data-n=\"1220\">25</sup> ביום הולדת",[["1214","19","<b>כשמן הטוב</b>: ראה תהלים קלג, ב."],["1215","20","<b>כל ראשית בישראל</b>: ראה אוה\"ת תבא ע' תתרלח."],["1216","21","<b>בראשית. . ותרגומו בחוכמתא</b>: בראשית א, א. ובתרגום ירושלמי."],["1217","22","<b>דבהאי חסד</b>: ראה ע\"ח שער (יד) או\"א פ\"א."],["1218","23","<b>ובכורך ישראל גאלת</b>: תפלת שחרית (עזרת אבותינו)."],["1219","24","<b>עיבור ז\"א במעי אימא</b>: ראה פע\"ח שער (כא) חגה\"מ פ\"א."],["1220","25","<b>ומולודתיך ביום הולדת אותך</b>: יחזקאל טז, ד."],["e29","*","<b>דוקא</b>: בכת\"י 1156 הגה\"ה בגוכתי\"ק הצ\"צ בשולי הגליון: ולכן ארז\"ל כהני קפדני נינהו כידוע בפ' ג\"פ שתקנו גט מקושר בשבילם והיינו מפני שמצד עצמו אין להם בחי' ה\"ח אלו אלא שמקבלים זה מישראל ע\"י ה' כסף שנותנים להם."]]],[2100490278,"אותך לא כרת שרך כו' ואעבור<sup data-n=\"1221\">26</sup> עליך ואראך מתבוססת בדמיך כו' וכתיב בני<sup data-n=\"1222\">27</sup> בכורי ישראל וכמ\"ש בר\"מ והיינו ברא בוכרא לאו\"א כו'. וענין הבכור הוא ראשית אוני כלומר ראשית ההשפעה שמובדל מן שאר ההשפעות במה שהוא בדוגמא למשפיע כי כח המוליד אשר יוליד בדומה לו הוא דווקא בבחי' הראשית כמ\"ש בראובן כחי<sup data-n=\"1223\">28</sup> וראשית אוני כו' וזהו קדש לי דוקא וע\"כ אתם<sup data-n=\"1224\">29</sup> קרויים אדם כו' כי פי' אדם<sup data-n=\"1225\">30</sup> אדמה לעליון כו' וכתיב ישראל<sup data-n=\"1226\">31</sup> אשר בך אתפאר וד\"ל, ומשום דישראל עלה במח' בא\"ס ב\"ה בבחי' הראשית כנ\"ל וכמ\"ש קדש<sup data-n=\"1227\">32</sup> ישראל לה' ראשית תבואתו ע\"כ ציוה לפדות כל בכור בשעת יציאת מצרים לפי שהי' אז בחי' לידה דווקא כמ\"ש ביחזקאל ומולודתיך כו' ונק' ברא בוכרא לאו\"א כנ\"ל, וענין הפדיון מיד הכהנים דוקא מבואר הטעם למע' וכמבואר ג\"כ בכתוב שתחת<sup data-n=\"1228\">33</sup> הבכורות נתנו הלוים כו' והכל ענין אחד, ומבואר ליו\"ח וד\"ל.",[["1221","26","<b>ואעבור עליך</b>: שם ו."],["1222","27","<b>בני בכורי ישראל</b>: שמות ד, כב."],["1223","28","<b>כוחי וראשית אוני</b>: ויחי מט, ג."],["1224","29","<b>אתם קרויים אדם</b>: יבמות סא, א."],["1225","30","<b>אדם אדמה לעליון</b>: ראה של\"ה ג, א. הנסמן בד\"ה אל תצר (קה\"ת, תשל\"ו) ע' 94."],["1226","31","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג."],["1227","32","<b>קדש ישראל לה'</b>: ראה ירמי' ב, ג."],["1228","33","<b>שתחת הבכורות נתנו הלוים</b>: ראה במדבר ג, יב."]]],[2100490279,"<h3>נוסח שני: וידבר גו' קדש לי כל בכור</h3>\n<b></b><b>בעזה\"י, יום א' ערב חנוכה (בסעודת מצוה בפדיון הבן הנ\"ל)</b>\n<b>וידבר</b><sup data-n=\"1229\">1</sup> ה' אל משה לאמור קדש לי כל בכור<sup data-n=\"1230\">2</sup> פטר כל רחם בבנ\"י באדם ובבהמה לי הוא וגו' ונאמ' להלן והי'<sup data-n=\"1231\">3</sup> כי יביאך וגו' והעברת<sup data-n=\"1232\">4</sup> כל פטר רחם הזכרי' לה' וגו' וכל<sup data-n=\"1233\">5</sup> בכור אדם בבניך תפדה וגו'. להבין כ\"ז הטיב ענין פדיון הבן הבכור ע\"י ה'<sup data-n=\"1234\">6</sup> סלעי' שנותנים לכהן דוקא שמאחר שהבכור לה' הוא כמ\"ש כי<sup data-n=\"1235\">7</sup> לי כל בכור וגו' מה שייך זה לכהן, ועוד מה תלוי הקדושה של הבכור ביצ\"מ דוקא. והענין דהנה ידוע שבתיקון דאצי' נתחלקו הספי' לג'<sup data-n=\"1236\">8</sup> קווין ימין ושמאל ואמצע שהמה כהנים ולוים וישראלים, כהנים נמשכים מקו ימין חח\"ן והיינו כמארז\"ל הרוצה<sup data-n=\"1237\">9</sup> שיחכים ידרים כו' דהא בהא תלי' שהחסד<sup data-n=\"1238\">10</sup> נמשך ונסתעף מבחי' החכמה שהיא ראשית הנאצלי' ולכך הרוצה שיחכי' ידרים וזהו שרש הכהנים דאתו מסטר ימינא דכתי' ראשית<sup data-n=\"1239\">11</sup> עריסותיכם תרימו כו' וכן",[["1229","1","<b>וידבר ה' אל משה לאמר קדש לי כל בכור</b>: הנחת ר' משה בן אדה\"ז. נמצא בכת\"י 1042 (רכט, ב). הנחת כ\"ק אדמו\"ר האמצעי נדפס לעיל ע' קצח.\nברשימות כ\"ק אדמו\"ר מהוריי\"צ (נעתק במפתח ספרי לדרושי אדמו\"ר מהוריי\"צ) נרשם שמאמר זה נאמר על פדיון של הבן של כ\"ק הרב\"ש בן אדמו\"ר הצ\"צ.\nוראה לעיל ע' צז."],["1230","2","<b>וידבר ה' אל משה קדש לי כל בכור</b>: בא יג, ב."],["1231","3","<b>והי' כי יביאך</b>: שם ה."],["1232","4","<b>והעברת כל פטר רחם</b>: שם יב."],["1233","5","<b>וכל בכור אדם</b>: שם יג."],["1234","6","<b>ה' סלעים שנותנים לכהן</b>: ראה קרח יח, טו-טז."],["1235","7","<b>כי לי כל בכור</b>: במדבר ג, יג."],["1236","8","<b>לג' קווין. . כהנים. . ימין</b>: ראה זהר לך פז, ע\"א. פרדס ערך לוי. מא\"א אות למ\"ד סי\"ד. לקו\"ת נשא כב, ב."],["1237","9","<b>הרוצה שיחכים ידרים</b>: ראה בבא בתרא כה, ב."],["1238","10","<b>שהחסד. . ונסתעף מבחי' החכמה</b>: ראה זהר ואתחנן רסב, א. לך צד, א. תרומה קעה, ב."],["1239","11","<b>ראשית עריסותיכם תרימו כו'</b>: שלח טו, כ."]]],[2100490280,"ראשית הגז שמגיע לכהנים כל בחי' ראשי\"ת, מצד ששרשם מקו ימין דאצי' שמצד שהחסד נסתעף מהחכמה לכך נשפע אלי' בחי' ראשית חכמה דאצי' ולכך כל ראשית מגיע להכהנים, והרוצה שיעשיר יצפין כי מצפון<sup data-n=\"1240\">12</sup> זהב יאתה זהו שרש הלוים שנמשכי' מקו שמאל בג\"ה דאצי', וקו האמצעי הוא דעת\"י זהו שרשן של ישראלי', ולכך מגיע הבכור לכהן מפני שהבכו\"ר<sup data-n=\"1241\">14</sup> העליון הוא בחי' ראשית חכ' דאצי' שהיא ראשי' הנאצלי' ששייך לכה\"ן חסד עליון כנ\"ל, וז\"ש יורו<sup data-n=\"1242\">15</sup> משפטיך ליעקב וגו' מצד שכל בחי' הראשית חכמה נשפע אליהם דייקא לכך הם יורו משפטיך ליעקב דווקא שמצד שכל השפעת הראשית חכ' עליונה נשפע אליהם דייקא שהם מקבלים תחלה השפע כנ\"ל לכך נעדר השפעת החכמ\"ה מישראל שמקו האמצעי שהם נוטלים הראשית תחלה כנ\"ל.\nב) <b>אך</b> המאציל חפץ לזכות את ישראל שיגיע אליהם ג\"כ שפע החכמה מבכו\"ר העליון לזאת צונו לפדות הבן הבכור מהכהן בה' סלעי' כסף והיינו &lt;צט&gt;\nבהיות ארז\"ל ישראל<sup data-n=\"1243\">13</sup><sup data-n=\"1244\">16</sup> עלו במחשבה פי' ששרשן הגבה למעלה מבחי' המחשבה וחכמה עליונה בכור עליון רק שעלו במחשבה מלמעלה מהמחשבה כו' מפני שהם מקו האמצעי ששרשן הגבה למעלה מאד נעלה מב' קוין ימין ושמאל כנודע (שדעת\"י עולה עד הכתר) לכך יכולי' לפדות הבן הבכור מהכהן בה\"ס כסף דהיינו שממשיכי' ממקורם שלמעלה מהמחשבה עליונה את בכור העליון שפע החכמה עליונה לתוך קו האמצעי של ישראל דוקא ונוטלי' זאת מהכהן שנמשך מקו ימין העליון ע\"י שממשיכי' ממקורם שלמעלה מהחכמה טרם התפשטותה לתוך קו ימין שלא תגיע לקו ימין זולתי יהי' נמשכת לקו האמצעי של ישראל דוקא ותמורת זה נותנין לכהן ה\"ס כסף דהיינו שממשיכי' לו משרשם הנעלה חלוף זה ה\"ח לקו ימין שרש הכה\"ן כי זהו עיקר סדר התיקון דאצי' שיתחלפו האורות דוקא כנודע לכך עושין החליפין להמשיך הבכור\"ה לקו אמצעי וחילוף זה ממשיכי' ה\"ח לקו ימין שרשו של הכהן וזהו הה\"ס כסף פדיון הבכור שנותנים להכהן שעי\"ז נפדה הבכו\"ר העליון שיומשך לקו אמצעי דישראל וכ\"ז מצד שרשן של ישראל שעלו במחשבה ושרשן הגבה למעלה מהמחשבה כנ\"ל.\nג) <b>וזהו</b> ובכורך<sup data-n=\"1245\">17</sup> ישראל גאלת שזהו הפדיון של הבכור העליון שיומשך לישראל אל קו האמצעי דוקא ע\"י נתינת ה\"ס כסף לכהן וכדכתי' בני<sup data-n=\"1246\">18</sup> בכורי ישראל וגו' וזה נעשה בצאתם ממצרים דוקא שאז נאמר קדש לי כל בכור פטר כל רחם וגו' וכל בכור בניך תפדה בהיות ידוע שבחי' הגלות<sup data-n=\"1247\">19</sup> הוא זמן העיבור דז\"א בבטן אימא דאצי' שאז הוא בבחי' קטנות תלת כלילן גו תלת כו' ובחי' הגאולה הוא",[["1240","12","<b>מצפון זהב יאתה</b>: איוב לז, כב."],["1241","14","<b>שהבכור. . ראשית חכ'</b>: ראה פרדס שער (כג) ערכי הכינויים מערכת בכור. לקו\"ת בהעלותך לג, א."],["1242","15","<b>יורו משפטיך ליעקב</b>: ברכה לג, י."],["1243","13","<b>וקו האמצעי. . ישראל</b>: ראה אוה\"ת בשלח ע' שנה."],["1244","16","<b>ישראל עלו במחשבה</b>: ראה בראשית רבה פ\"א, ד."],["1245","17","<b>ובכורך ישראל גאלת</b>: תפלת שחרית (עזרת)."],["1246","18","<b>בני בכורי ישראל</b>: שמות ד, כב."],["1247","19","<b>הגלות הוא זמן העיבור דז\"א</b>: ראה זהר (תוספתא) בשלח נ, סע\"א. ע\"ח שער הכללים פ\"ב. ביאוה\"ז בשלח מז, ג ואילך."]]],[2100490281,"בחי' הלידה דז\"א דאצי' שיוצא מרחם אימא דאצי' שאז נגדל אח\"כ במוחין דיניקה ומוחין דגדלות לכך בצאתם ממצרים דוקא שאז הי' פטר רחם העליון דאימא דאצי' שהוא בחי' הלידה דז\"א כו' נאמר קדש לי כל בכור כו' וכל בכור בניך תפדה להמשיך הבכור העליון המוחין דחכמה עליונה לתוך ישראל הוא ת\"ת דז\"א דאצי' קו האמצעי כו' ע\"י נתינת ה\"ס כסף לכהן כנ\"ל וד\"ל.\n<b>ולכך</b> נאמר ועמך<sup data-n=\"1248\">20</sup> כמריבי כהן וגו' שהכהנים<sup data-n=\"1249\">21</sup> הם קפדנים בעניני גיטין כדאי' בגמ' בגט מקושר כו' ע\"ש והיינו מאחר שכבר ניטל הבכורה מהם לישראל ע\"י חלוף פדיון ה\"ס כסף שהם ה\"ח עליונים שממשיכים אליהם ישראל חלוף הבכורה כנ\"ל לכך לענין גטי נשים הם קפדנים בהיות שרש הנשים הוא מה\"ג עליונות ולגבי ה\"ג חזקים יותר הה\"ח של הכהן לכך מתגברים הה\"ח של הכהן על הה\"ג של שרש הנשים כו' ולכך לענין גיטין בלבד הם קפדנים ודו\"ק.\n&lt;ק&gt;\nבעזה\"י,",[["1248","20","<b>ועמך כמריבי כהן</b>: הושע ד, ד."],["1249","21","<b>שהכהנים הם קפדנים. . בגמ' בגט מקושר</b>: ב\"ב קס, ב."]]],[2100490282,"<h3>מזמור שיר חנוכת הבית לדוד</h3>\n<b></b><b>בחנוכת הביה\"מ ליל א' דחנוכה</b>\nליל א' דחנוכה\n<b>מזמור</b><sup data-n=\"1250\">1</sup> שיר חנוכת הבית לדוד<sup data-n=\"1251\">2</sup> ארוממך הוי' כי דיליתנ\"י ולא שמחת אויבי לי וגו', הנה בשעה<sup data-n=\"1252\">3</sup> שאמר הקב\"ה נעשה אדם וגו' אמרו מה\"ש לפני הקב\"ה מה<sup data-n=\"1253\">4</sup> אנוש כי תזכרנו וגו' ואח\"כ בשעת מתן תורה בשעה שהקדימו<sup data-n=\"1254\">5</sup> נעשה לנשמע כו' הודו ואח\"כ כשחטאו בעגל חזרו ואמרו זהו שאמרנו לפניך בתחלה מה אנוש כי תזכרנו וגו' ואח\"כ בעשיית המשכן מהזהב שהתנדבו על המשכן הי' מכפר על זהב העגל לכך על אותו העת נאמ' ולא שמחת אויבי לי הם מה\"ש שהיו מקטרגי' עלינו עתה בבנין ביהמ\"ק לא שמחת להם כי המשכן והמקדש הכל א' שכמו שהי' עשרה קדושות במקדש כך המשכן רק שהמקדש הי' גדול יותר כו' לכך אמר דוד על שניהם ולא שמחת אויבי לי וגו'.\n<b>ולהבין</b> כ\"ז באר היטב מה שהמלאכי' שבחו א\"ע לפני הקב\"ה שהם למעלה מישראל שלמטה עד שאמרו מה אנוש כי תזכרנו כו' והקב\"ה אמר להם",[["1250","1","<b>מזמור שיר חנוכת הבית לדוד</b>: הנחת ר' משה בן אדה\"ז. נמצא בכת\"י 1042 (רלא, א).\nהנחת כ\"ק אדמו\"ר האמצעי ממאמר זה נמצא בכת\"י 68 ל, ב. נדפס בסידור (ערה, ג). הנחת המהרי\"ל נדפס בלקו\"ת ברכה צז, ד.\nלכמה ענינים המבוארים במאמר זה ראה סה\"מ תרל\"ג ע' רסח."],["1251","2","<b>מזמור שיר חנוכת הבית לדוד</b>: תהלים ל, א."],["1252","3","<b>בשעה שאמר הקב\"ה נעשה אדם</b>: בסה\"מ תרל\"ג שם מציין: במד\"ת סי' ח' ע\"פ מה אנוש כי תזכרנו שבשלשה מקומות היו המלאכים מדיינים כנגד הקב\"ה באדם ובמשכן ובתורה, ע\"ש באריכות. וראה ב\"ר פ\"ח."],["1253","4","<b>מה אנוש כי תזכרנו</b>: תהלים ח, ה."],["1254","5","<b>שהקדימו נעשה לנשמע</b>: שבת פט, א."]]],[2100490283,"שישראל הם למעלה מהם אף שהמה למטה בגופי' גשמיי' והראה להם בהנפילים אשר הפילם על הארץ למטה ויראו בני האלקי' את בנות האדם כו'. ויובן כ\"ז בהקדים לבאר הטיב ענין שרש המלאכים והנשמות וההבדל שביניהם, הנה המלאכי'<sup data-n=\"1255\">6</sup> וכל צבא השמים העומדים ברומו של עולם אומרי' שירה בכל בתמידיות שיש כתות מלאכים שאומרי' קדוש ויש שאומרי' ברוך ויש שאומרי' ימלוך כו' כמ\"ש יחזקאל הנביא ע\"ה ואשמע<sup data-n=\"1256\">7</sup> אחרי קול רעש גדול ברוך כבוד ה' ממקומו וגו' שזהו בחי' הביטול שלהם למקורן מדת מלכותו ית' כמ\"ש מלכותך<sup data-n=\"1257\">8</sup> מל' כ\"ע וגו' שמתבטלין במציאות ע\"י השרש שלהם, והנה מהות המלאכי' הם בבחי' חומר וצורה שהחומר הוא הגוף והכלי שלו שהוא בגדר מקום וזמן כענין שארז\"ל בסנד\"ל<sup data-n=\"1258\">9</sup> שגבוה ת\"ק שנה ויש מהם שהוא גבוה כשליש<sup data-n=\"1259\">10</sup> העולם שהוא ק\"ס שנה כנז' בדרז\"ל אך החומר הגוף שלהם איננו גשמיי כשלנו שהוא מורכב מד' יסודות פשוטי' דארמ\"ע כ\"א הוא בדקות ורוחניות יותר שמורכב רק מב' יסודות הרוחני' יותר והמה רו\"ח וא\"ש כמ\"ש עושה<sup data-n=\"1260\">11</sup> מלאכיו רוחות משרתיו אש לוהט וכפי'<sup data-n=\"1261\">12</sup> הרמב\"ן ז\"ל אבל הגוף שלהם הוא בגדר מקום וזמן כנ\"ל והצורה הוא האור השכל וההשגה שלהם שהוא כמהות השכל וההשגה שלנו כו' שע\"י השכל משיגי' גדולתו ית' ומתבטלים בהשיר שלהם כנ\"ל.\n<b>והנה</b> גם הנשמות שבג\"ע שבלתי גופים הם יוצאים בשיר ונמשכים בשיר בבחי' הביטול תמידי בלי הפסק בעליות וירידות מג\"ע התחתון לעליון ומעליון לתחתון (כמ\"ש ילכו<sup data-n=\"1262\">12</sup> מחיל אל חיל וכמארז\"ל שאין<sup data-n=\"1263\">13</sup> להם מנוחה לא בעה\"ז ולא בעה\"ב) כו' וזהו יוצאי'<sup data-n=\"1264\">14</sup> בשיר ונמשכי' בשיר כמ\"ש במ\"א ולפ\"ז צ\"ל מפני מה נזכר במרכבת יחזקאל ע\"ה השיר של המלאכי' כמ\"ש ואשמע אחרי קול רעש כו' ולא נז' בו ולא בשום מקום בתורה &lt;קא&gt;\nהשיר של הנשמות בג\"ע כו'.",[["1255","6","<b>המלאכים. . אומרי' שירה</b>: ע' חגיגה (יג, ב) ובתוד\"ה מזיעתן. וראה בהנסמן בהמ\"מ בלקו\"ת ברכה צח, א."],["1256","7","<b>ואשמע אחרי קול רעש גדול</b>: יחזקאל ג, יב."],["1257","8","<b>מלכותך מל' כ\"ע</b>: תהלים קמה, יג."],["1258","9","<b>בסנדל שגבוה ת\"ק שנה</b>: ראה חגיגה יג, א. פסק\"ר פ\"כ. וראה ג\"כ חולין צא, ב."],["1259","10","<b>כשליש העולם</b>: דמלאך הוא שלישו של עולם. ע' ירושלמי פ\"ב דר\"ה [ה\"ד]. וע' ב\"ר פמ\"ח. ופס\"ח סי' יז. ובילקוט דניאל ר' ב' תתרס\"ו עה\"פ וגויתו כתרשיש ע\"ש. סידור שער החנוכה רעו, א."],["1260","11","<b>עושה מלאכיו רוחות משרתיו אש לוהט</b>: תהלים קד, ד."],["1261","12","<b>וכפי' הרמב\"ן ז\"ל</b>: ראה סידור שער החנוכה ערה, ד בשם ספר הגמול להרמב\"ן. וראה לקו\"ש ח\"ט ע' 405. וש\"נ."],["1262","12","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["1263","13","<b>שאין להם מנוחה</b>: ברכות סד, א."],["1264","14","<b>יוצאי' בשיר ונמשכי' בשיר כמ\"ש במ\"א</b>: שבת נא, ב. ראה לקו\"ת ברכה צב, א — כמבואר בלק\"א הגדול. מובא עוד בשם הה\"מ בסידור עם דא\"ח ערה, ב: וכמו שמבואר בספר לק\"א הגדול על ענין המשנה כל בעלי השיר יוצאין בשיר. ובס' מאמרי אדה\"ז על מארז\"ל ע' קכ: יוצאין בשיר ונמשכין בשיר, כמבואר במ\"א ע\"ז בשם מורי זלה\"ה. סה\"מ מלוקט ח\"ו ע' צה [וע\"ש המצוין ע\"ז עוד]. ומביא גם פירוש זה בסתם: בתו\"א ז, ג. סה\"מ תקס\"ח ח\"א ע' תקנג. תו\"ח בראשית לד, ד. מאמרי אדה\"א דברים ח\"ב ע' תקפב [וע\"ש בהמ\"מ]. שם דרושי חתונה ע' תקיח. וראה גם בלק\"א להה\"מ סי' ס\"ד וסי' רד\"ע ע\"ד שירת ישראל שלמעלה משירת המלאכים. ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקפב, וש\"נ."]]],[2100490284,"<b>אך</b> הענין הוא דהנה ידוע ששרש המלאכי' הוא מחיצוניות העולמות שהם בחומר וצורה שהחומר הגוף הוא מורכב מב' יסודי הרוחני' דרוח ואש כו' ולכך השיר שלהם נרגש בקול רעש גדול עד שאמר יחזקאל ואשמע אחרי קול רעש גדול ואשמע ממש אחר\"י בחיצוניו' העולמות קול רעש גדול שניכר ונרגש הקו\"ל של השיר שלהם בבחי' הרגשה חיצוניות ברעש גדול ממש וכמ\"ש וקול<sup data-n=\"1265\">15</sup> כנפיהם כקול מים רבים וגו' משא\"כ הנשמו' הם מבחי' פנימיות העולמו' שאין להם למעלה בחי' גופים וכלים כלל רק הם צורות פשוטי' מופשטי' מגדר כלים וחומריי' אלו של המלאכים מצד ששרשן הנעלה שהם מפנימיו' העולמות ולכך אין הביטול של השיר שלהן ניכר ונרגש בהרגשה חיצוניות וקול רעש ממש, שההרגשה זו של הביטול של המלאכים הוא מצד שהם בחיצוניות העולמות ומלובשים בחומריי' וגופי' שמצד חומר הגוף נרגש הקול רעש בבחי' הרגשה חיצוני' ממש משא\"כ בנשמו' שמופשטי' מחומרי' אלו ושרשן מפנימיו' העולמו' לכך הביטול הוא בפנימיו' האורו' שלהן עצמן שהוא בדקות ורוחניות יותר עד שאין נרגש כלל ולא הי' יכול יחזקאל ע\"ה לשמוע קול רעש של הביטול זו שאינו בגדר שמיעה והרגשה כלל זולת הם יוצאין בשיר הוא הביטול פנימי שלהן להיות יוצאין בשיר בהסתלקות והתכללות במקורם כביטול הנר בפני האבוקה ולכך לא נזכר השיר שלהן בתורה וד\"ל.\n<b>וז\"ש</b> בתפילת יוצר סיפור שבחן של המלאכי' איך שמשבחי'<sup data-n=\"1266\">16</sup> ומפארי' ומעריצים ומקדישים וממליכי' את שם האל המלך כו' ועונים באימה ואומרי' ביראה ג\"פ קדוש והאופנים כו' ברעש גדול מתנשאי' כו' ואח\"כ בתפילה נאמר אתה קדוש ושמך קדוש וקדושים בכל יום יהללוך סלה פי' קדושי' הם הנשמות ישראל שלמעלה בג\"ע שמופשטי' מגדר חומרי' וכלים ולכך בכל יום יהללוך סלה פי' שהמלאכי' שהם בחיצוניות העולמו' בחומר וצורה לכך הם בגדר מקום וזמן כנ\"ל שיש מלאכי' שהכלי שלהם גבוה ת\"ק שנה ויש שהוא כשליש העולם ק\"ס שנה נמצא הם בגדר מקום וזמן מצד התלבשותן בגדר כלי והכלי היא בגדר מקום וזמן כנ\"ל אבל הנשמות שמפנימיו' העולמו' שמופשטי' מגדר כלי לכך הם מופשטי' מגדר מקום וזמן ולזאת בכל יו\"ם יהללוך סל\"ה<sup data-n=\"1267\">17</sup> בתמידות ובלי הפסק שאין להם זמן ועת כלל מצד שהם למעלה מהזמן (כי הזמן<sup data-n=\"1268\">18</sup> הוא הנברא כמו המקום כו') אבל המלאכי' שהם בגדר מקום וזמן יש זמן להשיר שלהם כנודע (שיש מלאכי' שהשיר שלהם ביום כמ\"ש ברן<sup data-n=\"1269\">19</sup> יחד כוכבי בוקר וגו' ויש שהשיר שלהם בלילה) ולכך בכל יו\"ם יהללו\"ך סל\"ה וד\"ל.\n<b>והנה</b> המלאכים אמרו מה אנוש כי תזכרנו כי מאחר שיש לנו גופים מה צורך להאדם שירדו הנשמות להתלבש בגופי' חומריי' יותר בעה\"ז, תנה<sup data-n=\"1270\">20</sup> הודך",[["1265","15","<b>וקול כנפיהם כקול מים רבים</b>: יחזקאל א, כד."],["1266","16","<b>שמשבחי'. . מתנשאי'</b>: ברכת יוצר."],["1267","17","<b>סלה. . ובלי הפסק</b>: עירובין ד, א."],["1268","18","<b>הזמן הוא הנברא</b>: ראה סידור שער הק\"ש עה, סע\"ד בשם הה\"מ. לקו\"ת בלק ע, ג. ועוד."],["1269","19","<b>ברן יחד כוכבי בוקר</b>: איוב לח, ז."],["1270","20","<b>תנה הודך על השמי'</b>: תהלים ח, ב. שבת שם."]]],[2100490285,"על השמי', שאף הם בחומר וצורה והחומריי' הגופי' שלהם הם דקי' ורוחניי' יותר, אך תשובת הקב\"ה הי' שמצטרך להיות הנשמה &lt;קב&gt;\nשמפנימיות העולמו' שמופשטת מגדר גוף וחומר למעלה לירד בגוף הגשמיי שלמטה שאף כמו שהיא בגוף גשמיי למטה ימצא בחי' הביטול אליו ית', ולזאת נתאוה<sup data-n=\"1271\">21</sup> הקב\"ה להיות לו דירה בתחתונים דוקא ולכך אמר ועשו<sup data-n=\"1272\">22</sup> לי מקדש ושכנתי בתוכם וגו' משא\"כ המלאכי'<sup data-n=\"1273\">23</sup> הנפילים אשר הי' בארץ שנאמ' ויראו<sup data-n=\"1274\">24</sup> בנות האדם כו' ולזאת נאמ' בחנוכת הבית ולא שמחת אויב\"י לי וגו' כנ\"ל.\n<b>והענין</b> דהנה כתי' ועשו לי מקדש ושכנתי בתוכם בתוכו<sup data-n=\"1275\">25</sup> לא נאמ' אלא בתוכם כו' מפני שעיקר השראת השכינה ב\"ה הוא על ישראל דאכל<sup data-n=\"1276\">26</sup> עשרה שכינתא שרי', אך לפ\"ז צ\"ל מה צורך בבנין בהמ\"ק אם ההשראה הוא העיקר בתוכם כו', אך הנה נאמר בתפילת מוסף דשלש רגלי' ואין אנו יכולי' לעלות ולראות ולהשתחוות לפניך מפני היד שנשתלחה במקדשיך דלכאורה יפלא מפני מה אין אנו יכולי' להשתחוות עתה הלא השכינה בכ\"מ כי מלא<sup data-n=\"1277\">27</sup> כל הארץ כבודו ואכל עשרה שכינתא שרי' בשלמא לעלות ולראות לחיי אבל להשתחוות מפני מה אין אנו יכולי'. אך התירוץ הוא שיש ב' בחי' השתחוואות בחי' השתחוואה בגוף ובחי' השתחוואה בנפש, פי' ההשתחוואה בגוף הוא ביטול חיצוניי ביטול הגוף בלבד כמשל במלך ב\"ו כשרואהו עבדו נופל לארץ ומשתחווה לפניו בבחי' ביטול ממש שאף עפ\"י שהוא בטל באמת אעפי\"כ הביטול הוא בגוף בלבד ואין נוגע לעצמו' נפשו כי יכול להרהר בשעת ההשתחוואה תאות זרות מה שלבו חפץ ואין הרצון שלו נכנע וכפוף לפניו וכן תיכף לאח\"כ חלף עבר הביטול וחזר לקדמותו לכל עסקיו כו' לכן ההשתחוואה זו אנו יכולים אף עתה לכרוע במודים ולבטל א\"ע בבחי' ביטול חיצוניי של הגוף לכוף כאגמון ראשו כו' בהכרח וכפיי' לכל מילי דשמי' שהוא הכל מצד ההכרח ואעפי\"כ יכול להתאוות רצונות אחרי' של עה\"ז כו', אבל בחי' ההשתחוואה בנפש הוא בחי' הביטול האמיתי של הרצון שבנפש שמתבטל מפני רצון העליון ב\"ה שאין לו רצון אחר בלתי לה' לבדו כמארז\"ל בטל<sup data-n=\"1278\">28</sup> רצונך מפני רצונו וכמ\"ש מי<sup data-n=\"1279\">29</sup> לי בשמים ועמך לא חפצתי בארץ וגו' והוא כביטול הנר בפני האבוקה שהנר מסתלק האש ממנה ליכלל בהאבוקה הגדולה כך עד\"מ הביטול של הנשמה למקורה עצמותו ית' שכלתה נפשו בהסתלקות אליו ית' וממילא בטל מכל וכל שאין לו חפץ",[["1271","21","<b>נתאווה הקב\"ה להיות לו דירה בתחתונים</b>: תנחומא נשא טז. וראה תניא רפל\"ו. בהנסמן בליקוט פירושים לשם."],["1272","22","<b>ועשו לי מקדש ושכנתי בתוכם</b>: תרומה כה, ח."],["1273","23","<b>המלאכים הנפילים אשר היו בארץ</b>: ראה ילקוט שמעוני בראשית רמז מד. זח\"א כג, א. כה, א-ב."],["1274","24","<b>ויראו בנות האדם</b>: בראשית ו, ב."],["1275","25","<b>בתוכו לא נאמר אלא בתוכם</b>: ראה ראשית חכמה (שער האהבה פ\"ו קרוב לתחלתו). ובשל\"ה (ש' האותיות אות ל. מסכת תענית רד\"ה מענין העבודה. פ' תרומה חלק תו\"מ — שכה, ב. שכו ב, ועוד."],["1276","26","<b>דאכל עשרה שכינתא שרי'</b>: סנהדרין לט, א."],["1277","27","<b>מלא כל הארץ כבודו</b>: ישעי' ו, ג."],["1278","28","<b>בטל רצונך מפני רצונו</b>: אבות פ\"ב, מ\"ד."],["1279","29","<b>מי לי בשמים</b>: תהלים עג, כה."]]],[2100490286,"אחר בלתי אליו הוא נושא את נפשו כנ\"ל וזה ההשתחוואה אין אנו יכולי' מפני שאין לנו בהמ\"ק שזה החיוב של עולי רגלי' בזמן שבהמ\"ק קיים דכתי' שלש<sup data-n=\"1280\">30</sup> פעמי' בשנה יראה כל זכורך את פני הוי' וגו' פי' שבבהמ\"ק הי' גילוי שכינ\"ה שהוא בחי' ממכ\"ע מדת מל' ית' המתלבשת תוך כ\"ע להחיותם כמ\"ש מלכותך<sup data-n=\"1281\">31</sup> מל' כ\"ע וגו' ולכך כשהיו עולי' לראות פני ה' ית' בבהמ\"ק הי' נשפע בהם בחי' הביטול האמיתי של ההשתחוואה בנפש להיות בטל רצונו מפני רצון העליון ב\"ה בתכלית הביטול, והי' זה להם לקיום מרגל לרגל מפסח עד שבועות ומשבועות עד סוכו' לכך ג\"פ בשנה יראה כל זכורך וכמארז\"ל כשם<sup data-n=\"1282\">32</sup> שבא לראות כך בא לראו\"ת כו' וז\"ש פנ\"י הו\"י ל' רבים שהי' מתגלה שם בחי' ממכ\"ע שנק' שכינ\"ה ובחי' סכ\"ע שנק' קוב\"ה ששם הי' יחוד קב\"ה ושכינת' כו' כנ\"ל וד\"ל.\n&lt;קג&gt;\n<b>אך</b> הנה כתי' ואהי<sup data-n=\"1283\">33</sup> להם למקדש מעט בארצות אשר באו שם וכמארז\"ל ע\"ז<sup data-n=\"1284\">34</sup> אלו בתי כנסיות ובתי מדרשות כו' שאף הם נק' מקדש מעט מפני שאכל עשרה שכינתא שרי', אך הוא רק בחי' מקדש מעט בהיות בזמן בהמ\"ק קים הי' גילוי כללות השכינה ב\"ה שנק' בחי' כנס\"י מקור כנס\"י שלמטה ולכך הי' נתגלה בהם בחי' מציאו' הביטול האמיתי להתכלל נר<sup data-n=\"1285\">35</sup> ה' נשמת אדם הפרטי בפני האבוקה הכללי' שהיא מקור כל נשמות פרטי' של ישראל כנ\"ל. ועתה משחרב בהמ\"ק בעו\"ה נתחלקה השפע כוללית של השכינה ב\"ה דרך פרט בארצות אשר באו שם בכל מדינה ומדינה עיר ועיר בבתי<sup data-n=\"1286\">36</sup> כנסיות ובתי מדרשות להיות אכל עשרה שכינתא שרי' פי' חלק פרטי ממנה שורה ומתגלה עליהם, וזהו ואהי להם למקדש מעט דוקא, ולכן יוכל להיות נמצא אפס קצהו ושמץ מנהו מבחי' ההשתחוואה בנפש ההיא אף עתה (בנפש) בקרב ישראל ע\"י היגיעה והעמלה בתורה ועבודה<sup data-n=\"1287\">37</sup> שבלב זו תפילה וד\"ל.\n<b>וזהו</b><sup data-n=\"1288\">*37</sup> מזמור שיר חנוכת הבית וגו', דהנה ההפרש בין תיבת מזמו\"ר לתיבת שי\"ר בלה\"ק הוא שהזמר והניגון שמזמר בכלי זמר בנבל וכנור כו' נק' הניגון ההוא קול זמרה מצד שהוא הקול זמרה היוצא מן הכלי זמר, ושיר<sup data-n=\"1289\">38</sup> הוא בפה הקול היוצא מהפה שאינו מלובש בכלי וזהו מזמו\"ר שי\"ר פי' מזמו\"ר הוא שירת המלאכי' העומדי' ברומו של עולם שהם מחיצוניו' העולמות שהם בבחי' חומר וצורה אור וכלי",[["1280","30","<b>שלש פעמים בשנה יראה כל זכורך את פני הוי'</b>: פ' ראה טז, טז."],["1281","31","<b>מלכותך מל' כ\"ע</b>: תהלים קמה, יג."],["1282","32","<b>כשם שבא לראות כך בא לראות</b>: חגיגה ב, א. ד, ב."],["1283","33","<b>ואהי להם למקדש מעט</b>: יחזקאל יא, טז."],["1284","34","<b>וכמארז\"ל ע\"ז אלו בתי כנסיות</b>: מגילה כט, א."],["1285","35","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["1286","36","<b>בבתי כנסיות. . שכינתא שרי'</b>: ראה ברכות ו, א. שו\"ע או\"ח רסי' נה."],["1287","37","<b>ועבודה שבלב זו תפלה</b>: ספרי (ופרש\"י) עקב יא, יג. תענית ב, סע\"א."],["1288","*37","מכאן עד סוף קטע ”אך הנה במקדש\" נאמר במוצש\"ק שבת חנוכה. נעתק בלקו\"ת ברכה צח, ג-ד."],["1289","38","<b>שהזמר. . בכלי זמר. . ושיר הוא בפה</b>: ראה אוה\"ת וישב תתקו שמביא ענין זה ובחצאי עיגול (וצ\"ע בפ\"ק דגיטין ד\"ז ע\"א גבי זמרא מנלן דאסור כו' משמע דקאי על זמרא דפומא וכן דהע\"ה שאמר זמירות היו לי חוקיך היינו ודאי זמרא דפומא)."]]],[2100490287,"שהשיר שלהן שמזמרי' ומשבחי' ומפארי' את שם כבוד מלכותו ית' בתודה וקול זמרה נק' בחי' מזמו\"ר מצד שהוא הזמר המלובש בהכלי שהם בבחי' חומר וצורה ולכך לא ימצא בהם בחי' הביטול האמיתי להכלל במקור' כנר בפני האבוקה שהכלי שלהם מעכב ולזאת גם הביטול שלהם נרגש בקול רעש גדול הכל מסיבת הכלי כנ\"ל, ושיר הוא בחי' השי\"ר של הנשמות שבג\"ע שיוצאין בשיר ונמשכי' בשיר בהביטול האמיתי כביטול הנר בפני האבוקה מצד שאינם מלובשים בחומר וכלי כנ\"ל ולכך נק' השיר שלהם בחי' שיר מצד שאינו מלובש בכלי כי אין להם חומריי' וכלי כו' כנ\"ל<sup data-n=\"e30\">*</sup>.\n<b>אך</b> הנה במקדש הי' גילוי שכינה מקור הנשמו' והמלאכים כמ\"ש מלכותך<sup data-n=\"1290\">39</sup> מל' כ\"ע וגו' לכך נאמ' בחנוכת הבית מזמור שיר שהי' מתגלה שם שניהם בחי' המזמור של המלאכי' והשיר של הנשמות מצד שמקור כולם הוא גילוי שכינה ב\"ה שנתגלה במקדש כנ\"ל (וכן הי' למטה במקדש בשיר של הלוים שנתחלקו לב' חלקי' מהם היו המשוררי' בפה ומהם המזמרים בכלי וכדאי' פלוגתא<sup data-n=\"1291\">40</sup> בגמ' אם עיקר שירה בפה או בכלי כו' יע\"ש ומ\"ש לפעמי' להיפך שיר<sup data-n=\"1292\">41</sup> מזמור לבני קרח כו' היינו בהיות המזמור הוא בחיצוניות המלובש בכלי והשיר בפנימיות שבלתי כלי ולכך כשמצטרכי' להתחבר יחד הוא בב' פנים או שהעליון יורד למטה או התחתון מתעלה למעלה ולכך כשנאמ' מזמו\"ר &lt;קד&gt;\nשיר הוא בחי' ההעלאה של המזמור לכלל בהשי\"ר ולהתחבר בו ושי\"ר מזמור הוא כשהעליון השיר יורד למטה להתחבר אליו וד\"ל. גם מזמור הוא ל'<sup data-n=\"1293\">42</sup> זמר והתחלקות כמ\"ש וכרמך לא תזמו\"ר כו' שהוא לשון פרור והתחלקות של הניגון שנחתך לחלקי' קטנים בתוך הכלי זמר משא\"כ השיר וכמ\"כ הוא למעלה וד\"ל.",[["1290","39","<b>מלכותך מל' כ\"ע</b>: נסמן לעיל הערה 31."],["1291","40","<b>בפלוגתא בגמ'. . בפה. . בכלי</b>: ערכין יא, א."],["1292","41","<b>שיר מזמור לבני קרח</b>: תהלים מח, א. פח, א."],["1293","42","<b>ל' זמר. . כמ\"ש וכרמך לא תזמור</b>: בהר כה, ד. וראה תו\"א בשלח סג, ד. לקו\"ת ברכה צח, ד."],["e30","*","<b>בכת\"י 1042 הגה\"ה בגוכתי\"ק הצ\"צ בצידי הגליון</b>: (ועמ\"ש ע\"פ שיר השירים [ראה לקו\"ת שה\"ש א, א ואילך] וע\"פ ובלילה שירה עמי בד\"ה ויהי מקץ [תו\"א לא, ג] וע' בזח\"א ויצא קמ\"ח ב' בענין ההפרש בין שיר הלוים לבחי' וחסידיך ירננו דכהנים שהיא בחי' עליונה יותר ועד\"ז יובן מעלת בחי' שיר על בחי' מזמור, ע' גם בפרדס בעה\"כ ערך שיר פי' כי שיר הוא בחכמה)."]]],[2100490288,"<h3>חנוכת הבית לדוד</h3>\n<b></b><b>(ע\"כ<sup data-n=\"1294\">43</sup> ד\"ק במש\"ק דחנוכה ושייך לכאן)</b>\n<b>חנוכת</b> הבית לדוד כתי' חנוך<sup data-n=\"1295\">44</sup> לנער עפ\"י דרכו וגו' פי' ענין החינוך של הנער עד\"מ כשמחנכי' אותו ללמוד התורה שמצטרך האב לעשות לו איזה דבר",[["1294","43","<b>ע\"כ ד\"ק במש\"ק</b>: — עד כאן דברי קדשו במוצאי שבת קודש."],["1295","44","<b>חנוך לנער על פי דרכו</b>: משלי כב, ו. ראה גם סידור שער החנוכה רעז, א. לקו\"ת נשא כט, א. ברכה צח, ב ואילך. מאמרי אדה\"א במדבר ח\"ג ע' תתקמו ואילך."]]],[2100490289,"חדש נוסף על הלימוד בכדי להרגילו להלימוד מאחר שזה דבר חדש אצלו לזאת מצטרך להנהיגו ולהמשיכו שילך אל הרב ללמוד, והדבר חדש הנוסף הוא שהאב מראה לו חיבה יתירה שהולך ג\"כ עמו ומוליכו לבית הספר או שנותן לו מעדנים מיני מתיקה וכדומה בכדי לשעשע אותו שעי\"ז ימשיך לבו שילך לבית הספר וילמוד שזה נק' חינוך בלה\"ק שממשיכו לדבר הלימוד ההוא ע\"י תוספת דבר אחר שמראה לו חיבה יתירה וכדומ' כנ\"ל, כך עד\"מ למעלה ענין חנוכת המזבח שהחנוך הוא ע\"י תוספת ד\"א יתר על המדה הראוי' בכדי לחנכו בזה שישכון כבוד ה' בחי' שכינתו ית' בבית הזה שבנה שלמה המלך ע\"ה ובהיות ידוע שעצמות אור א\"ס ב\"ה מרומם לבדו ואין ערוך אליו כלל לזאת הוא באמת ירידה גדולה שישפיל א\"ע לשרות בעה\"ז בק\"ק בין בדי הארון (וכמ\"ש שלמה המלך ע\"ה בעצמו בחנוכת הבית הן<sup data-n=\"1296\">45</sup> השמים ושמי השמים לא יכלכלוך וגו') ולכן בתחלה נצטרך לחנכ\"ו כביכול שירד ה' ב\"ה לשרות בבהמ\"ק והחינוך הוא הבקר והצאן אשר הקריב שלמה כמ\"ש בד\"ה ויזבח<sup data-n=\"1297\">46</sup> המלך שלמה את זבח הבקר עשרי' ושנים אלף וצאן מאה ועשרים אלף ויחנכו את בית האלקי' וגו' שהקרבנות האלו הם רק בשביל חנוכת הבית בכדי להמשיך תוספת אורו' עליונים יתר על המדה שהי' אח\"כ מצד שהוא התחלת החנוכ\"ה שמצטרך להמשיך תוספ' אורו' עליונים שיומשך עי\"ז גילוי השכינה בק\"ק שהיא ירידה גדולה באמת וכנ\"ל במשל, וכן בחנוכת<sup data-n=\"1298\">47</sup> המשכן שהקריבו הנשיאים ככתוב בתורה שהי' חנוכת המזבח שנאמ' ביום<sup data-n=\"1299\">48</sup> הראשון כו' נחשון בן עמינדב וקרבנו קערת כסף אחת כו' כף אחת עשרה זהב משקלה כו' ולזבח השלמי' כו' ביום<sup data-n=\"1300\">49</sup> השני נתנאל בן צוער כו' זאת<sup data-n=\"1301\">50</sup> חנוכת המזבח ביום המשח אותו כו' שמאחר שנצטרכו להמשיך גילוי כבודו ית' על המזבח כו' נצטרכו לחנכו בקרבנות הנשיאי' להמשיך תוספת אורות עליונים כנ\"ל, וכן בחנוכה קוראין פרשת הנשיאי' מפני שבחנוכ\"ה הי' הנס שגברו יד חשמונאי' על היונים ונצחום שהיונים עשו בו &lt;קה&gt;\nי\"ג פרצות כו' (וטמאו<sup data-n=\"1302\">51</sup> אבני המזבח כדאי' בגמ') לכך אח\"כ כשגברו החשמונאי' עליהם נצטרכו לחנך<sup data-n=\"1303\">52</sup> המזבח מחדש מאחר שנסתלק ממנו כו' ולכך קוראי' בפ' נשיאי' ולכן<sup data-n=\"1304\">53</sup> מפורש בתורה בפ' נשיאים כל קרבן של כל נשיא בפ\"ע אף שהי' שוין כולן",[["1296","45","<b>הן השמים ושמי השמים לא יכלכלוך</b>: מלכים-א ח, כז."],["1297","46","<b>יזבח המלך שלמה את זבח הבקר</b>: דברי הימים-ב ז, ה."],["1298","47","<b>חנוכת המשכן שהקריבו הנשיאים</b>: נשא ז, י ואילך."],["1299","48","<b>ביום הראשון כו' נחשון בן עמינדב</b>: נשא ז, יב."],["1300","49","<b>ביום השני נתנאל בן צוער</b>: נשא ז, יח."],["1301","50","<b>זאת חנוכת המזבח</b>: נשא ז, פד."],["1302","51","<b>וטמאו אבני המזבח כדאי' בגמ'</b>: ראה ע\"ז נב, ב."],["1303","52","<b>לחנך המזבח מחדש</b>: ראה שו\"ת דברי נחמי' חאו\"ח השלמות לשו\"ע דרז\"ל סעת\"ר ס\"ב. ס\"ג [נדפסו גם בשו\"ע אדה\"ז חאו\"ח ח\"ג-ד ע' תרפה]. לקו\"ש כ\"ד כסלו (כרך כ) ע' 449 הערה 26. חנוכה ע' 633 בהערה."],["1304","53","<b>ולכן מפורש בתורה. . נשיא בפ\"ע</b>: ראה גם סידור שער החנוכה רעז, ב ואילך. מאמרי אדה\"ז תקס\"ז ע' רכ. תו\"א בראשית ח, ב. לקו\"ת ברכה צח, ג."]]],[2100490290,"ולכאורה הוא פלאי דהל\"ל וכן עשה השני וכן עשה השלישי ולמה מפרש כל חד וחד באנפי נפשי' כו', אך הענין הוא בהיות ידוע ששרש הי\"ב שבטים למעלה הם מחולקי' בשרשן זמ\"ז שלכך נק' בשם שבטי' כמשל הענפי' הנמשכי' מהאילן שזה פונה לכאן וזה לכאן ואין שרשו ועיקרו של זה שוה עם עיקרו של זה כך עד\"מ השבטים מחולקי' בשרש המשכותן שהם י\"ב מיני אבוקות שונות זמ\"ז ולכן כל שבט ושבט המשיך תוספת אור בחי' אבוקה שלו משרשו ע\"י הקרבת הקרבן של הנשיא שלו כו'. והנה התורה היא נצחיות שנכתב כאו\"א מפורש בפ\"ע בכדי שע\"י הקריאה בתורה בהקרבת הקרבן של כל שבט ושבט בפ\"ע ימשיכו בחי' י\"ב אבוקות שונות ממקורם ושרשם של י\"ב השבטי' ולכך קוראי' בחנוכה בפ' נשיאי' בכל שבט ושבט איך שהקריב הקרבן בפ\"ע כמפורש בתורה כנ\"ל וזהו מזמור שיר חנוכ\"ת הבית וד\"ל.\n<b>ארוממך</b><sup data-n=\"1305\">54</sup> ה' כי דיליתני הנה במלת<sup data-n=\"1306\">55</sup> דיליתנ\"י יש ג' פירושי' וכולם עולי' בקנה א' והיינו הפי' הראשון הוא לשון עילוי והגבהה כאילו הי' נאמ' הגבהתני והיינו העילוי וההגבה של כנ\"י הי' בזמן בנין בהמ\"ק שהי' גילוי כבודו ית' למטה במקדש כמ\"ש ה'<sup data-n=\"1307\">56</sup> אמר לשכון בערפל כו' וכתי' ולא<sup data-n=\"1308\">57</sup> יכלו הכהנים לשרת מפני הענן וגו' והעילוי וההגבה זו של נשמות ישראל הוא מצד מקורם ושרשם שהם מפנימיו' העולמו' והם למעלה טרם ירידתן לגוף בלעדי חומריי' וכלי' כלל משא\"כ המלאכי' ולכך דיליתנ\"י נגד המלאכי' של מעלה אשר אמרו מה<sup data-n=\"1309\">58</sup> אנוש כי תזכרנו כו'. והשני הוא לשון דלות ועניות והוא נותן טעם לראשון שלכך הגבהתנ\"י יותר מן המלאכי' עד שנתאוה הקב\"ה להיות לו דירה בתחתונים דוקא מצד שדיליתני בבחי' דלות ועניות שערומים הם נשמות ישראל בשרשן למעלה מופשטי' מגדר לבושי' וכלי' חומריי' לכך הגבהתנ\"י להיות הגבה למעלה מהמלאכי' שאינם דלי' כמונו שיש להם חומריי' וגופי' הם הכלי' שלהם כנ\"ל, והפי' השלישי הוא לשון שאיבה כמו וגם דלה<sup data-n=\"1310\">59</sup> דל\"ה לנו והוא הנותן טעם לשני שזה גופא מפני מה שרש הנשמות הם מופשטי' מגדר לבושי' וכלי' שלכך הם למעלה מהמלאכי' שמצד זה יוכל להיות נמצא בהם בחי' הביטול האמיתי כנר בפני האבוקה משא\"כ המלאכי' שהכלי מעכב ואם שיתבטלו בכלות הנפש מן הכלי אזי זהו עונשן שחזרו לאין ואפס ממש כמאר\"ז הושיט<sup data-n=\"1311\">60</sup> אצבעו הקטנה ביניהם ושרפן אבל הנשמו' יכולי' להתקיים ואעפ\"כ ימצא בהם הביטול כנר בפני האבוקה מצד שאין לה כלי' בשרשם למעלה לכך אף בהתלבשותן בגוף למטה ימצא בהן הביטול הזה כנ\"ל וכ\"ז הוא כי דיליתנ\"י מים החכמה שלמעלה כמ\"ש ותמלא<sup data-n=\"1312\">61</sup> כדה ותעל &lt;קו&gt;\nוכמ\"ש<sup data-n=\"1313\">62</sup> בזוהר שזה כ\"ד ספרי דאוריי'",[["1305","54","<b>ארוממך ה' כי דילתני</b>: תהלים ל, ב."],["1306","55","<b>במלת דילתני יש ג' פירושים</b>: ראה לקו\"ת ברכה צח, ד. אוה\"ת ואתחנן ע' שכא."],["1307","56","<b>ה' אמר לשכון בערפל</b>: דברי הימים ב ו, א."],["1308","57","<b>ולא יכלו הכהנים לשרת מפני הענן</b>: מלכים א ח, יא. דברי הימים ב ה, יד."],["1309","58","<b>מה אנוש כי תזכרנו</b>: תהלים ח, ה."],["1310","59","<b>דלה דלה</b>: שמות ב, יט."],["1311","60","<b>הושיט אצבעו הקטנה ביניהם</b>: סנהדרין לח, ב. וראה מאמרי אדה\"א ויקרא ח\"א ע' קסא. וש\"נ."],["1312","61","<b>ותמלא כדה ותעל</b>: חיי שרה כד, טז."],["1313","62","<b>וכמ\"ש בזוהר שזה כ\"ד ספרי דאורייתא</b>: ראה תקוני זהר תכ\"א (מו, ב). מאמרי אדה\"א שמות ח\"א ע' ק, וש\"נ."]]],[2100490291,"שדלה מים החכמה שלמעלה וזהו שרש כנ\"י דקוב\"ה<sup data-n=\"1314\">63</sup> ואורייתא וישראל כלא חד, ולזאת מאחר ששרש כנ\"י הוא הגבה למעלה מאד נעלה משרש המלאכי' שהמלאכי' שרשן מבחי' מדת מלכותו ית' בחי' ממכ\"ע בלבד אבל הנשמו' שרשן מים החכמה שלמעלה ולכך הם דלי\"ם למעלה מבחי' החומריי' והכלי' שמופשטי' מגדר כלי כנ\"ל וגם אף כשמתלבשי' בגוף למטה ימצא בהם בחי' הביטול האמיתי כנר בפני האבוקה וזה הי' עיקר בזמן בהמ\"ק שהי' גילוי שכינה ב\"ה וג\"פ בשנה יראה כל זכורך את פני ה' להשתחוות לפניו ית' ולכך ולא שמחת אויב\"י לי הם המלאכי' המקטרגי' שהודו אח\"כ בבנין בהמ\"ק כנ\"ל וד\"ל.",[["1314","63","<b>דקוב\"ה ואורייתא וישראל כולא חד</b>: ראה זהר אחרי עג, א הנסמן במאמרי אדה\"א קונטרסים ע' שלט."]]],[2100490292,"<h3>רבת את ריבם</h3>\n<b></b><b>בעזה\"י בלילה<sup data-n=\"1315\">1</sup> ההיא הנ\"ל</b>\n<b>רב\"ת</b><sup data-n=\"1316\">2</sup> את ריבם, וכמ\"ש בתפלה ומלך<sup data-n=\"1317\">3</sup> גבור לריב ריבם פי' הנה נאמר בזהר<sup data-n=\"1318\">4</sup> ע\"פ ויאמר אל עמו הבה נתחכמה וגו' שנאמ' ויאמר סתם מאן אמר דא שרו של מצרים דאיהו יהיב אינון מחשבתי' בלבהון, והיינו כנודע שהשר של האומה ההוא המשפיע להם כל החיות וכל המחשבות שלהם נשפעים הכל מהשר וכל תבואות הארץ של מדינתו כי אין<sup data-n=\"1319\">5</sup> לך עשב שאין לו מזל כו' והוא מקבל מקדושה מבחי' אחוריי' כנודע והנה השר הוא בחי' קליפה ממש שהוא שונא לישראל מחמת הקנאה שרואה למעלה מאן חשיב ישראל אשר בהם בחר מכל העמים לעם סגולה ואף כשהם בגולה לא מאסתים ולא געלתים כו' כי שמו נקרא עליהם כמשל בן יחיד של המלך שנתרחק מאביו המלך אעפ\"כ בן המלך נקרא, שאין לו אחר זולתו בנו יחידו זה כו' ואלמלא ניתן להם רשות הי' ח\"ו מחריבי' לשונאי ישראל אך שומר ישראל ה' והם לא יוכלו לעבור את פ\"י ה' כלל (כמו שנאמר יפול<sup data-n=\"1320\">6</sup> מצדך אלף כו') וארז\"ל אלמלא ניתן רשות לעין לראות כו' ואעפ\"כ אינם עושים מאומה בלתי רשות כו' וכמ\"ש אם<sup data-n=\"1321\">7</sup> תגביה כנשר משם אורידך כו' וכמ\"ש בת\"ז<sup data-n=\"1322\">8</sup> שאו' לס\"ם ירא שמים יראת בושת כו' והנה השר של יון התנשא אז לעלות לירושלים וגברה יד ישראל על",[["1315","1","<b>בלילה ההיא</b>: ליל א' דחנוכה. הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1042 (רלו, א)."],["1316","2","<b>רבת את ריבם</b>: נוסח ועל הניסים."],["1317","3","<b>ומלך גבור לריב ריבם</b>: תפלת שחרית."],["1318","4","<b>בזהר ע\"פ ויאמר אל עמו. . מאן אמר דא שרו של מצרים</b>: ראה זהר שמות יז, א. יח, א."],["1319","5","<b>אין לך עשב שאין לו מזל</b>: ראה בראשית רבא פ\"י, ו. מאמרי אדה\"א דברים ח\"ג ע' תתמח, וש\"נ."],["1320","6","<b>יפול מצדך אלף</b>: תהלים צא, ז."],["1321","7","<b>אם תגביה</b>: עובדי' א, ד."],["1322","8","<b>בת\"ז שאו' לס\"ם ירא שמים יראת בושת</b>: ת\"ז בהקדמה ה, ב. ת\"ז תכ\"ח. וראה ברכות לג, ב. שבת לא, ב. וראה תו\"א וישב כז, ב."]]],[2100490293,"העליונה ועשו מה שעשו, אך על להבא שלא יתנשא עוד לזאת נאמר רבת את ריבם שהוא הרוגז והחימה שיצא עלי' מלמעלה לגעור בו בנזיפה שלא ירים ראשו עוד, וכן הוה שק\"ג שנה אח\"כ הי' מנוחה לישראל, ואף אח\"כ לא ממנו יצא הרעה של חורבן בהמ\"ק בעו\"ה כ\"א מהרומיים כו', וזהו ומלך גבו\"ר לריב ריבם כי הקב\"ה הוא רב חסד והטוב והמטיב לכל, אך נתלבש במדת הגבורה לריב ריבם להשפיל השר ההוא וכמ\"ש יפקוד<sup data-n=\"1323\">9</sup> על צבא המרום במרום ואח\"כ על מלכי האדמה באדמה וכמ\"ש בזוה\"ק ע\"ש וד\"ל.\n&lt;קז&gt;",[["1323","9","<b>יפקוד על צבא המרום במרום</b>: ישעי' כד, כא."]]],[2100490294,"<h3>רני ושמחי בת ציון</h3>\n<b></b><b>בעזהי\"ת וית\"ש לע\"ו, תורה ברבים, שבת חנוכה שנת תקסוא\"ו לפ\"ק</b>\nשבת חנוכה\n<b>רני</b><sup data-n=\"1324\">1</sup> ושמחי בת ציון<sup data-n=\"1325\">2</sup> כי הנני בא ושכנתי בתוכך נאום ד' וגו', להבין ענין רינה ושמחה גם מה השייכות זאת לענין חנוכ\"ה, והל\"ל התחלת<sup data-n=\"1326\">3</sup> ההפטורה מפסוק ראיתי<sup data-n=\"1327\">4</sup> והנה מנורת זהב וגו', אך הנה כתיב עבדו<sup data-n=\"1328\">5</sup> את ד' בשמח\"ה ובואו לפניו ברננה ונאמר בזוהר ע\"ז רננה<sup data-n=\"1329\">6</sup> ברמשא ושמחה בצפרא, וגם זה צריך ביאור מהו רננה ומהו שמחה ומהו רמשא ומהו צפרא. הענין דהנה רננה הוא בחי' עבודת המלאכים ועירין<sup data-n=\"1330\">7</sup> קדישין עליונין שעבודתם בתמידיות הוא בתודה וקול זמרה בבחי' השתוקקות נפלאה בגבורות רשפי אש להיות נכספה<sup data-n=\"1331\">8</sup> וגם כלתה נפשם למקורם מדת מלכותו ית' אשר היא מלכות<sup data-n=\"1332\">9</sup> כל עולמים כו' והיינו מבחי' ההתבוננות שלהם בגדולתו ית' אשר לגדולתו<sup data-n=\"1333\">10</sup> אין חקר, היש<sup data-n=\"1334\">11</sup> מספר לגדודיו ואתה<sup data-n=\"1335\">12</sup> מחיה את כולם בהארת של כבוד מלכותו ית' שנקרא עליהם בלבד אבל מהותו ועצמותו מרומם לבדו עד שאין ערוך אליו כלל ומתנשא מימות עולם ועי\"ז מתעוררים בתשוקה נפלאה בבחי' רננה ושירה להכלל ולהבטל במקורם מדת מלכותו ית' המחיה אותם ומהוה מאין ליש תמיד, וזהו דכתיב זכר<sup data-n=\"1336\">13</sup> רב טובך יביעו וצדקתך ירננ\"ו פי' צדקתך הוא מדת מלכותו ית' כמאמר<sup data-n=\"1337\">14</sup> אליהו צדק הוא מלכותא",[["1324","1","<b>רני ושמחי בת ציון</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 2140 קיא, א.\nהנחת כ\"ק אדמו\"ר האמצעי ממאמר זה מכת\"י 68 לו, א נדפס בסידור עם דא\"ח (רעח, ג). והביאור נדפס לקמן ע' ריח.\nהנחת המהרי\"ל נדפס בתו\"א לו, ד.\nוראה שערי אורה (כד, ב) באריכות."],["1325","2","<b>רני ושמחי בת ציון</b>: זכרי' ב, יד."],["1326","3","<b>התחלת ההפטורה מפסוק</b>: ראה מגילה לא, א. — בחנוכה מפטירין בנרות דזכרי', ובפרש\"י שם."],["1327","4","<b>ראיתי והנה מנורת זהב</b>: זכרי' ד, ב ואילך."],["1328","5","<b>עבדו את ה' בשמחה</b>: תהלים ק, ב."],["1329","6","<b>רננה ברמשא ושמחה בצפרא</b>: זח\"א רכט, א."],["1330","7","<b>ועירין קדישין</b>: ראה זח\"א מד, א."],["1331","8","<b>נכספה וגם כלתה נפשם</b>: ע\"פ תהלים פד, ג."],["1332","9","<b>מלכות כל עולמים</b>: תהלים קמה, יג."],["1333","10","<b>לגדולתו אין חקר</b>: תהלים קמה, ג."],["1334","11","<b>היש מספר לגדודיו</b>: איוב כה, ג."],["1335","12","<b>ואתה מחיה את כולם</b>: נחמי' ט, ו."],["1336","13","<b>זכר רב טובך</b>: תהלים קמה, ז."],["1337","14","<b>כמאמר אליהו</b>: ראה תיקוני זהר בהקדמה (יז, ב)."]]],[2100490295,"קדישא מאזני<sup data-n=\"1338\">15</sup> צדק תרין סמכין קשוט כו' פי' צד\"ק הוא בחי' מדת מלכותו ית' הממלא תוך כ\"ע להחיות את כולם וכמ\"ש וצדק<sup data-n=\"1339\">16</sup> מלאה ימינך דהיינו בחי' החיות המגיע לכל הנבראים פרטיים הוא ממדת החסד ימין העליון שבמל' ית' כמ\"ש בתפלה מכלכל<sup data-n=\"1340\">17</sup> חיים בחסד וגו' ומאזני צדק פי' המשקל של המאזניים דלעילא למדוד השפע שבמל' ית' שנשפע להנבראים פרטיים שמודדים השפע זו במאזני צדק הם תרין סמכי קשוט כמה בשעור ומדה יומשך מבחי' צדק עליון היא מדת מל' ית' להנברא פרטי זה דהיינו כמה יומשך לו במדה בחי' קבלת עול מ\"ש אם רב או מעט כפי זכותו אם ראוי לגילוי רב או מעט כ\"ז נמדד הכל במאזניים דלעילא הם תרין סמכין קשוט במשקל ופלס ושיעור ומדידה ולכך נק' מאזני צד\"ק שהם המשק\"ל והמדה של הצד\"ק שיומשך בשיעור ומדה לכאו\"א לפום שיעורא דיליה כפי הראוי לו כו' כנ\"ל וד\"ל.\n<b>ולזאת</b> מאחר שבחי' צדק עליון מקור החיים של הנפעלים עליונים ותחתונים לכך ירננ\"ו המלאכים תמיד את בחי' צדקת\"ך בבחי' שירה ורננה בכלות הנפש בהשתוקקות נפלאה לכלל במקור החיים ב\"ה, והיינו שכל סדרי ההשתלשלות הוא הכל בבחי' עילה ועלול, שכל עלול תשוקתו נפלאה להדבק בעילתו מקורו וליכלל בו כנודע, וז\"ש מלכותך מלכות כל עולמים וממשלתך בכל דור ודור פי' שמדת<sup data-n=\"1341\">18</sup> מלכותו ית' בחי' צדק עליון היא מקור הזמן ומקום שמתפשטת על כל עולמות שזהו בחי' גדולתו ית' בבחי' המקום ובכל דור ודור שזהו התפשטות גדולתו ית' בבחי' הזמן וכמ\"ש ד' מלך ד' מלך ד'<sup data-n=\"1342\">19</sup> ימלוך וגו' שהוא בבחי' סדר הזמן ומקום, אבל עצמותו ית' מרומם לבדו מבחי' סדר הזמן והמקום כי אני<sup data-n=\"1343\">20</sup> הוי\"ה לא שניתי כתיב, ומאחר שבעצמו ית' הוא מרומם לבדו לכך א\"א להתפשט החיות של הנפעלים ממהותו ועצמותו ית' זולתי משם כבוד מלכותו ית' שמתלבש תוך כ\"ע בבחי' מקום וזמן להחיות את כולם וזהו מלכותך מלכות כל עולמים וממשלתך בכ\"ל דור ודור וכנ\"ל וד\"ל.\n<b>אך</b> הנה כתיב זכר רב טובך יביעו ואח\"כ וצדקת\"ך ירננ\"ו, והיינו שאף זאת שיומשך בחי' מדת מלכותו ית' המחי' את כולם מעצמותו ית' מוכרח להיות כמה וכמה מיני צמצומים אין חקר כלל והצמצומים אלו נק' בשם רב טוב'ך כענין שנאמר אמרו<sup data-n=\"1344\">21</sup> צדיק כי טוב וגו', שמצטרך להיות רב טובך רבוא רבבות צמצומים עליונים עד שיוכל להיות בחי' צדקת\"ך זכ\"ר בעלמא מרב טובך המה יביעו ואח\"כ וצדקתך ירננו כנ\"ל וד\"ל.",[["1338","15","<b>מאזני צדק</b>: קדושים יט, לו. וראה תקו\"ז בהקדמה (יז, ב). שעה\"י קכה, א ובהערה 4. תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] יד, א. פיה\"מ עח, רע\"א."],["1339","16","<b>וצדק מלאה ימינך</b>: תהלים מח, יא."],["1340","17","<b>מכלכל חיים בחסד</b>: תפלת שמו\"ע."],["1341","18","<b>שמדת מלכותו. . מקור הזמן</b>: ראה גם שער היחוד והאמונה פ\"ז."],["1342","19","<b>דימלוך</b>: שמות טו, יח. וראה זח\"א לד, א."],["1343","20","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["1344","21","<b>אמרו צדיק כי טוב</b>: ישעי' ג, י."]]],[2100490296,"<b>וזהו</b> רננה ברמשא דייקא כדכתיב נפשי<sup data-n=\"1345\">22</sup> אויתיך בלילה דייקא, פי' שעיקר ההשתוקקות הוא כשנעדר האור והגילוי של אור א\"ס ב\"ה בהם שהוא מסתתר מהם בבחי' העלם והסתר וישת<sup data-n=\"1346\">23</sup> חושך סתרו שאזי צמאה<sup data-n=\"1347\">24</sup> נפשם בכלות הנפש בהשתוקקות נפלאה אל גילוי אור א\"ס ב\"ה הנעדר מהם וא\"א להם להשיגו שהם כחולת אהבה ומרננים ברננה במרירות מאד מהעדר השגתם אותו ית' שאו' איה מקום כבודו להעריצו כו' וזהו נפשי אויתיך בלילה דוקא שאז תגדל הצמאון וההשתוקקות הנפלאה בבחי' רננ\"ה בכלות הנפש ממש. וכמ\"כ הוא בנשמות ישראל שלמטה בעבודה<sup data-n=\"1348\">25</sup> שבלב זו תפלה שבפסוקי דזמרה שמב\"ש עד ישתבח כו' שנק' שערי זמרה שהם שירות ותושבחות של דוד המלך ע\"ה שהוא בחי' הרננה להרים קול זמרה בהשתוקקות נפלאה אל עצמות אור א\"ס ב\"ה להיות נכספה וגם כלתה נפשו בצמאון גדול בגבורות רשפי אש ושלהבת עזה אליו ית' והוא ע\"י התבוננות ברוממותו ית' איך שלגדולתו אין חקר והחיים של כל הנפעלים עליונים ותחתונים אשר אין להם מספר כלל מריש כל דרגין עד סוף כל דרגין הוא הכל מבחי' שם כבוד מלכותו ית' המחיה את כולם ומתפשטת בכל עולמות ובכל דור ודור אבל עצמותו ית' מרומם ונשגב לבדו ומתנשא מימות עולם, אי לזאת תכלה נפש כל חי אליו ולא למדותיו ית' באהבה רבה וצמאון גדול, וזהו רננה ברמשא כמ\"ש נפשי אויתיך בלילה בהיות עצמותו ית' המרומם לבדו לית מחשבה תפיסה ביה כלל כי ישת חשך סתרו ולזאת מהעדר האור והגילוי שלו ית' תשתוקק הנפש בצמאון גדול מאד בבחי' רננה במרירות וחולת אהבה כנ\"ל.\n<b>אך</b> בק\"ש<sup data-n=\"1349\">26</sup> נאמר תחלה בחי' יחודא עילאה ויחודא תתאה ואח\"כ ואהבת<sup data-n=\"1350\">27</sup> את הוי\"ה אלקיך שזהו בחי' הרננה ברמשא כי נפשי אויתיך בלילה בכלות הנפש שבק\"ש ואח\"כ נאמר והיו<sup data-n=\"1351\">28</sup> הדברים האלה אשר אנכ\"י מצוך היום על לבבך וגו' פי' שזהו ענין השמחה בצפרא כמ\"ש עבדו את ה' בשמחה דהיינו שבאמת ע\"י ההעלאה מלמטה למעלה בגבורות רשפי אש וצמאון גדול אליו ית' א\"א להשיגו כלל בשום אופן דלית<sup data-n=\"1352\">29</sup> מחשבה תפיסא ביה כלל וישתאר לעולם בבחי' מדת לילה וחשך אך המאציל ב\"ה המרומם לבדו הוא משפילי<sup data-n=\"1353\">30</sup> לראות בשמים וארץ בשוה דקמי' כחשיכה<sup data-n=\"1354\">31</sup> כאורה מעלה ומטה גשמיות ורוחניות ארץ ושמים שוים בהשואה אחת שאף הרוחניות לגשמיות נחשב נגדו ולכך כולם שוים קמיה בערך הביטול כלא חשיבא השוה ומשוה קטן וגדול ואין יתרון לגדול על הקטן נגדו כלל כנודע. ולזאת",[["1345","22","<b>נפשי אויתיך בלילה</b>: ישעי' כו, ט. וראה גם תניא פמ\"ד."],["1346","23","<b>וישת חושך סתרו</b>: ע\"פ תהלים יח, יב."],["1347","24","<b>צמאה נפשם</b>: ראה תהלים קז, ה."],["1348","25","<b>דעבודה שבלב זו תפלה</b>: ראה ספרי (ופרש\"י) עקב יא, יג. תענית ד, סע\"א. רמב\"ם ריש הל' תפלה."],["1349","26","<b>בק\"ש. . יחודא עילאה ויחודא תתאה</b>: זהר בראשית יח, ב."],["1350","27","<b>ואהבת את הוי' אלקיך</b>: ואתחנן ו, ה."],["1351","28","<b>והיו הדברים האלה</b>: ואתחנן ו, ו."],["1352","29","<b>דלית מחשבה תפיסא ביה כלל</b>: תקו\"ז בהקדמה."],["1353","30","<b>משפילי לראות בשמים וארץ</b>: ע\"פ תהלים קיג, ו."],["1354","31","<b>כחשיכה כאורה</b>: תהלים קלט, יב."]]],[2100490297,"יוכל להמשיך בחי' גילוי אור א\"ס ב\"ה מלמעלה למטה מטה, וזהו והיו הדברים האלה אשר אנכ\"י<sup data-n=\"1355\">32</sup> מי שאנכ\"י בחי' עצמות אור א\"ס ב\"ה מצוך היום על לבבך שנמשך בחי' גילוי עצמות אור א\"ס ב\"ה למטה מטה להתלבש בתורה ומצות שנמשכים מחכמתו ורצונו ית' כנודע וזהו ודברת בם וגו'.\n<b>והענין</b> דהנה רמ\"ח<sup data-n=\"1356\">33</sup> פקודין דעשה נקראו רמ\"ח אברין דמלכא שדרך כלל נחלקין לשלשה קוין ימין ושמאל ואמצע שהם שלשה<sup data-n=\"1357\">34</sup> דברים שהעולם עומד עליהן תורה ועבודה וג\"ח, ג\"ח ובכללן הוא מעשה הצדקה הוא מקו ימין, כי חסד<sup data-n=\"1358\">35</sup> דרועא ימינא, ועבודה מקו שמאל ותורה מקו האמצעי כמשנ\"ת במ\"א, וכמו עד\"מ בנפש האדם המלובשת בתוך רמ\"ח אברי הגוף שכל חלק וכח פרטי מהנשמה מתלבש באבר פרטי המיוחד לו ולזאת כשיאחזנו חבירו באבר א' מאבריו בידו או ברגלו יוכל להמשיכנו עי\"ז אליו ממ\"ש כך ממש רמ\"ח מ\"ע הם אברים דמלכא שע\"י קיום המ\"ע ימשיך גילוי עצמו' אור א\"ס ב\"ה מלמעלה למטה וכן בת\"ת<sup data-n=\"1359\">36</sup> שכנגד כולן דאורייתא<sup data-n=\"1360\">37</sup> מחכמה נפקא וזהו בחי' השמחה שישמח ישראל בעושיו כאשר מקיים מצותיו ית' ועוסק בתורה שהיא חכמתו ית' לקשר מחשבה במחשבה ודבור בדבור ומעשה במעשה שזהו בכל<sup data-n=\"1361\">38</sup> נפשיך כמ\"ש במ\"א שעי\"ז ימשיך גילוי עצמו' אור א\"ס ב\"ה אשר הי' כלתה נפשו אליו ית' למטה כמ\"ש והיו הדברים האלה אשר אנכי מצוך וגו' וכמארז\"ל אין<sup data-n=\"1362\">39</sup> עומדין להתפלל לא מתוך שחוק כו' אלא מתוך שמחה<sup data-n=\"1363\">40</sup> של מצוה וכן לדבר הלכה שמצטרך להיות בשמחה<sup data-n=\"1364\">41</sup> וטוב לבב מרוב כל וזהו עבדו את ה' בשמחה אך תחילה צריך להיות בחי' רננה ברמשא וזהו ובאו לפניו ברננה וכמארז\"ל כברייתו<sup data-n=\"1365\">42</sup> של עולם ברישא חשוכא והדר נהורא שזהו מפסוקי דזמרה עד ק\"ש ואח\"כ מצטרך לחבר מדת לילה ביום שהוא בחי' ואהבת שבק\"ש שהוא בחי' רננה ברמשא ואח\"כ והי' הדברים אשר אנכי מצוך כו' שהוא בחי' יו\"ם בחי' שמחה בצפרא כו' כנ\"ל וד\"ל.\n<b>וזהו</b> רנ\"י ושמח\"י בת ציון שהנביא מנחם לכנ\"י שאף שהוא עתה בזמן הגלות בחי' בת ציון אעפ\"כ תתעלה לע\"ל להיות נמצא בה בחי' רננה ושמחה והענין הוא דהנה כתיב כי<sup data-n=\"1366\">43</sup> מלך אלהיך ציון שציון נק' בחי' מלך שהיא מדת מלכותו ית' המתלבשת בבחי' מקום וזמן להחיות את כולם כמ\"ש מלכותך מלכות כל עולמים",[["1355","32","<b>אנכי מי שאנכי</b>: ראה זהר ח\"א קסז, ב. לקו\"ת להאריז\"ל תולדות כז, יט. וראה תניא מהדו\"ק ספמ\"ט (ע' תו)."],["1356","33","<b>רמ\"ח פקודין. . רמ\"ח אברין</b>: ראה תיקוני זהר ת\"ל (עד סע\"א). וראה תניא ר\"פ כ\"ג."],["1357","34","<b>שלשה דברים שהעולם עומד</b>: ראה אבות פ\"א, מ\"ב."],["1358","35","<b>חסד דרועא ימינא</b>: תיקוני זהר בהקדמה (יז, א)."],["1359","36","<b>בת\"ת שכנגד כולן</b>: סוף מס' פיאה."],["1360","37","<b>דאורייתא מחכמה נפקא </b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קנא, א."],["1361","38","<b>בכל נפשך</b>: ואתחנן ו, ה."],["1362","39","<b>אין עומדין להתפלל לא מתוך שחוק</b>: ברכות לא, א."],["1363","40","<b>שמחה של מצוה. . לדבר הלכה</b>: שבת ל, ב. פסחים קיז, א."],["1364","41","<b>בשמחה וטוב לבב מרוב כל</b>: תבוא כח, מז."],["1365","42","<b>כברייתו של עולם</b>: שבת עז, ב."],["1366","43","<b>כי מלך אלקיך ציון</b>: ראה ישעי' כד, כג."]]],[2100490298,"וממשלתך בכל דור ודור וגו' ולזאת נק' בחי' ציון מלשון אות וסימנא כמ\"ש ציון<sup data-n=\"1367\">44</sup> המצויינת כו', והיינו כדכתיב נעשה<sup data-n=\"1368\">45</sup> אדם בצלמינו כדמותינו פי' שיש למעלה בחי' צל\"ם ודמות שמדת מלכותו ית' נקראת בחי' דמות העליון שהיא בחי' האות והסימן של התורה והמצות שלמעלה שנחקקו בה בבחי' דמות וציון וסימן בלבד פי' כי התורה ומצות שלמטה שמלובשים בגשמיות אינם מעצמו' התו\"מ שלמעלה ברוחניות כ\"א זה בחי' הלבשה שנתלבשה התו\"מ במלבושים גשמיים דעה\"ז כמו צמר הגשמיי של הטלית והציצית שהוא למטה צמר גשמיי ולמעלה נאמר עוטה<sup data-n=\"1369\">46</sup> אור כשלמה שמהשלמה עליונה שנעשה מהודו מעטה לבושו יוצאים בחי' ציצית שהם המשכות השערות עליונות וכן קלף גשמיי של התפילין שהוא רק בחי' דוגמא וציור דוגמת המצות רוחניים עליונים איך שהם בשרשן שהצמר של הטלית וציציותיו הגשמיים הוא הדמות והציור דוגמת הטלית עליון שעוטה אור כשלמה והציציות רוחניים השערות עליונות ועד\"ז חכמת התורה המלובשת בגשמיים בעניני עה\"ז הוא הדמות והציור דוגמת ח\"ע הרוחניי' של התורה ועד\"ז כל המצות כולן שמלובשים בלבושים גשמיי' של עה\"ז נק' בחי' דמות וציור בלבד שהוא הדוגמא והסימן בלבד של התו\"מ רוחניי' שהאות והסימן של התו\"מ גשמיי' הוא בחי' הוראה על העצם המקור בחי' התו\"מ רוחניים דלעילא ולכך נקראת מדת מלכותו ית' בשם ציו\"ן מצד שבה מסומן ונצטיירו בחי' התו\"מ שלמעלה בבחי' דמות וסימנא בלבד שמראה על העצם איך שהם במקורן ושרשן עצמו' כנ\"ל (ומאחר שמדת מלכותו ית' הוא בחי' הדמות עליון שבה נצטייר בחי' תו\"מ בבחי' התלבשות בציונים וסימנים בלבד להראות על העצם כו' לכך נק' בחי' ציון וד\"ל).\n<b>וזהו</b> שמברכין<sup data-n=\"1370\">47</sup> עובר לעשייתן של המצות ברו\"ך אתה הוי' אמ\"ה אקב\"ו כו', פי' ברוך<sup data-n=\"1371\">48</sup> הוא לשון ברכ\"ה והמשכה וכמו המברי\"ך<sup data-n=\"1372\">49</sup> את הגפן שכופף ראש הגפן לעפר הארץ שמוגדל ממנו ענף אחר שכל המשכה שנמשכת בשפע בתוספות ורבוי נק' בחי' ברכה שע\"י הברכת הגפן יצמיח ענף אחר בתוספות ורבוי מקדם אשר לא נעשה, וכן ביוסף הצדיק עליון נאמר ויקראו<sup data-n=\"1373\">50</sup> לפניו אבר\"ך בהיות יוסף<sup data-n=\"1374\">51</sup> הוא בחי' צדי\"ק עליון המשפיע ומבריך השפע עליונה למטה (שהוא<sup data-n=\"1375\">52</sup> המשביר כנודע) לכך ויקראו לפניו אבר\"ך שהוא מבריך השפע להשפיע מעולם ועד עולם למטה וכמ\"כ עובר לעשיית המצות אומרים ברוך אתה כו' שיומשך השפע עליונה בתוספת גילוי מלמעלה למטה שיהי' מלך אלהיך ציון בבחי' גילוי ממש ולא יסתיר העולם להתראות ליש ודבר שבפני עצמו וזהו מלך העולם וד\"ל.",[["1367","44","<b>ציון המצויינת</b>: לשון הושענא אבן שתי' (ליום ב')."],["1368","45","<b>נעשה אדם בצלמינו כדמותינו</b>: בראשית א, כו."],["1369","46","<b>עוטה אור כשלמה</b>: ראה גם מאמרי אדה\"ז תקס\"ד ע' צב. ע' ערב. אוה\"ת בשלח ע' תעג."],["1370","47","<b>שמברכין עובר לעשייתן</b>: ראה פסחים ז, ב. וש\"נ. שו\"ע אדה\"ז או\"ח סי' מו, ג. קנח, טז. ובכ\"מ."],["1371","48","<b>ברוך לשון המשכה</b>: ראה לקו\"ת בחוקתי מח, ב. ראה כט, א."],["1372","49","<b>המבריך את הגפן</b>: כלאים ר\"פ ז."],["1373","50","<b>ויקראו לפניו אברך</b>: מקץ מא, מג."],["1374","51","<b>יוסף הוא בחי' צדיק עליון</b>: ראה זח\"א קנג, ב."],["1375","52","<b>שהוא המשביר</b>: ראה מקץ מב, ו."]]],[2100490299,"<b>והנה</b> כ\"ז הוא בחי' ציון אך בזמן הגלות נקראת כנ\"י<sup data-n=\"1376\">53</sup> בחי' בת ציון בהיות ארז\"ל איש<sup data-n=\"1377\">54</sup> מזריע תחלה יולדת בת כו' אשה מזרעת תחלה יולדת זכר כמ\"ש אשה<sup data-n=\"1378\">55</sup> כי תזריע וילדה זכר וגו' פי' דכאשר אשה מזרעת תחלה שהוא בחי' אתערותא דלתתא דכנ\"י שמתעוררת מלמטה למעלה בבחי' רננה ושמחה בעבודה שבלב זו תפלה כמ\"ש עבדו את ה' בשמחה ובואו לפניו ברננה אזי יולדת זכר שע\"י אתערותא דלתתא<sup data-n=\"1379\">56</sup><sup data-n=\"1380\">57</sup> מעוררים לעילא להמשיך בחי' גילוי השפעת חסדים למטה שהחסד<sup data-n=\"1381\">58</sup> נק' בחי' זכר כדכתיב זכר<sup data-n=\"1382\">59</sup> חסדו וגו' אבל כשאין נמצא בבחי' אתערותא דלתתא כ\"א איש העליון מזריע תחלה מעצמו וממילא בלתי אתערותא דלתתא כלל אזי יולדת נקבה בחי' בת ציון שנעשי' בחי' מקבלים להשפע עליונה בלבד וזהו בזמן הגלות בעו\"ה כשאין נמצא בחי' רננה ושמחה שאז איש מזריע תחלה ויולדת בת ציון ולזאת הנביא מנחם לכנ\"י רני ושמחי בת ציון שאף שעתה אין נמצא בכנ\"י בחי' רננה ושמחה מצד שהיא בחי' ב\"ת אעפ\"כ לע\"ל יהי' אף בבת ציון בחי' רננה ושמחה, והיינו כמ\"ש ולציון<sup data-n=\"1383\">60</sup> יאמר אי\"ש ואי\"ש יולד בה וגו' פי' שלע\"ל תתהפך מבחי' בת ציון להיות בחי' איש זכר כי אז יהי' בחי' אשה מזרעת תחלה שיולדת זכר לזאת תתהפך מבחי' בת ציון שעתה לבחי' איש זכר, ואיש יולד בה הנה בחי' ואיש השני הוא בחי' התגלות השפע מלעילא לעילא אשר אין בחי' אתערותא דלתתא מגיע לשם כלל כ\"א ואי\"ש דלעילא לעילא מזריע השפע עליונה מעצמו וממילא מלמעלה למטה לע\"ל כמ\"ש והוא<sup data-n=\"1384\">61</sup> יכוננהו עליון שזהו בבחי' ואי\"ש שיולד בה שהוא לעילא לעילא אשר אין מגיע לשם בחי' אתערותא דלתתא כלל. וזהו רני ושמחי בת ציון כי הנני בא ושכנתי בתוכך שזהו לע\"ל כשאיש ואיש יולד בה והוא יכוננהו עליון שזהו ושכנתי בתוכך שהוא בחי' ואי\"ש שיולד בה מלעילא לעילא ממקום שאין מגיע לשם בחי' אתערותא דלתתא כלל כנ\"ל, אז יהי' רני ושמחי בת ציון מפני שאיש ואיש יולד בה וד\"ל.\n<b>וזהו</b> ענין הדלקת נר<sup data-n=\"1385\">62</sup> חנוכה על פתח הבית מבחוץ דוקא, דהנה כתיב פתחו<sup data-n=\"1386\">63</sup> לי שערי צדק אבא בם אודה י\"ה וגו' פי' שערי צדק הוא בחי' שערי זמרה דפסד\"ז שבתפלה שהם נקראו שערי צדק כמ\"ש וצדקתך<sup data-n=\"1387\">64</sup> ירנ\"נו שהוא בחי' הרננה ברמשא שנז\"ל כדכתיב נפשי<sup data-n=\"1388\">65</sup> אויתיך בלילה כו', אך מי שאינו זוכה וראוי להגיע לבחי' רננה אל שערי צדק להיותו מרנ\"ן את בחי' צדקתך כשירת המלאכים עליונים בגבורות רשפי אש וצמאון גדול בבחי' השתוקקות נפלאה להיות כלתה נפשו לחצרות ה' כו', לזאת",[["1376","53","<b>כנס\"י. . ציון</b>: ראה לקו\"ש חכ\"ד ע' 353 בהערה."],["1377","54","<b>איש מזריע תחלה</b>: ברכות ס, א."],["1378","55","<b>אשה כי תזריע</b>: תזריע יב, ב."],["1379","56","<b>פי' דכאשר אשה מזרעת. . אתערותא דלתתא</b>: ראה תו\"א מקץ לז, ג — וכנודע בזוהר [ראה תיקוני זהר תי' (פז, א)]. וראה לקו\"ת תזריע ד\"ה שוש תשיש ועוד."],["1380","57","<b>דלתתא מעוררים דלעילא</b>: ראה זח\"א פח, א."],["1381","58","<b>שהחסד. . זכר</b>: ראה לקוטי אמרים להה\"מ [הוצאת קה\"ת] סימן רכא, ועוד."],["1382","59","<b>זכר חסדו</b>: תהלים צח, ג."],["1383","60","<b>ולציון יאמר איש ואיש יולד</b>: תהלים פז, ה."],["1384","61","<b>והוא יכוננהו עליון</b>: המשך הפסוק."],["1385","62","<b>נר חנוכה על פתח ביתו מבחוץ</b>: שבת כא, ב."],["1386","63","<b>פתחו לי שערי צדק</b>: תהלים קיח, יט."],["1387","64","<b>וצדקתך ירננו</b>: תהלים קמה, ז."],["1388","65","<b>נפשי אויתיך בלילה</b>: ישעי' כו, ט."]]],[2100490300,"תיקנו הסופרים בחי' הדלקת נר חנוכה על פתח הבית מבחוץ בהיות שמן הוא נמשך מחכמה עליונה שהתורה נקראת בחי' שמן<sup data-n=\"1389\">66</sup> ותורה אור לכך מדליקין נר חנוכה על פתח מבחוץ שעי\"ז ממשיכים בחי' גילוי אור א\"ס ב\"ה למטה מטה מבחוץ לשערי צדק העליון שישרה בחכמתו ית' ורצונו הם התו\"מ מעשיות שהאדם מקיימן אף שאינו יכול להגיע לשערי צדק ברננה ושמחה הנ\"ל, רק רחמנא<sup data-n=\"1390\">67</sup> לבא בעי אם<sup data-n=\"1391\">68</sup> ישום אליו לבו אזי רוחו ונשמתו אליו יאסוף כמ\"ש בזהר דרוח<sup data-n=\"1392\">69</sup> אייתי רוח ואמשיך רוח פי' שישים אליו לבו שיהי' חפץ בבחי' המשכת הגילוי של אור א\"ס ב\"ה בעסקו בתו\"מ מעשיות אף שאינו יכול להתעורר ברננה ושמחה אזי ונשמתו אליו יאסוף, למטה מטה מבחוץ לשערי צדק הנ\"ל מפני שלגבי עצמותו ית' כחשיכה כאורה גשמיות ורוחניות שוי' השוה ומשוה קטן וגדול המשפילי לראות בשמים ובארץ בשוה ולכך יוכל להשפיל למטה מטה להתגלות אף חוץ לשערי צדק וזהו כי הנני בא ושכנתי בתוכך אף שאין בך נמצא בחי' הרננה ושמחה אעפ\"כ הנני בא ונמשך מלמעלה למטה מטה ושכנתי בתוכך מבחוץ לפתח הבית וזהו ממשיכים במצות הדלקת נר חנוכה מבחוץ וזהו ונלוו<sup data-n=\"1393\">70</sup> גוים רבים אל הוי' שכ\"כ יומשך השפע של גילוי אור א\"ס ב\"ה למטה עד מקום הגוים שאף הם ילוו אל הוי' ולכך מפטירין הפטורה זו בשבת חנוכה דוקא כנ\"ל וד\"ל.",[["1389","66","<b>שהתורה נקראת בחי' שמן</b>: ראה ברכות נז, א. זח\"ג לט, א."],["1390","67","<b>רחמנא לבא בעי</b>: ראה סנהדרין קו, ב וברש\"י שם. ספר חסידים סתק\"ל (ובהנסמן במקור חסד שם) וסתק\"צ. חובת הלבבות בהקדמה ד\"ה וכאשר התברר לי."],["1391","68","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["1392","69","<b>רוח אייתי רוח</b>: ראה זהר תרומה קסב, ריש ע\"ב."],["1393","70","<b>ונלוו גוים רבים אל הוי'</b>: זכרי' ב, טו."]]],[2100490301,"<h3>להבין שרשי הדברים הנ\"ל</h3>\n<b></b><b>בעזה\"י [ביאור על תורה רני ושמחי כו']</b>\n<b>להבין</b><sup data-n=\"1394\">1</sup> שרשי הדברים הנ\"ל. הנה שרש ענין בת<sup data-n=\"1395\">2</sup> ציון הוא בחי' יסוד דנוק' שנק' ציו\"ן ולפעמים הוא ג\"כ בל' זכר לגבי<sup data-n=\"1396\">3</sup> ירושלים כו' ונק' ג\"כ בשם חות\"ם וכלול מדכר ונוק' וכאשר יורדת המל' בבי\"ע אז נק' בת ציו\"ן לפי שצריך לבקוע המסך כידוע והאור<sup data-n=\"1397\">4</sup> הנראה מתוך המסך הוא רק בחי' אור של תולדה כמ\"ש במ\"א",[["1394","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מכת\"י 1156 פו, ב. נמצא גם בכת\"י 68 (לח, א).\nהמאמר עצמו נדפס בסידור שער החנוכה (רעח, ג).\nהנחת המהרי\"ל נמצא בכת\"י 954 נח, א. 1824 יז, ג. ובשינויים בכת\"י 396 צא, ב.\nהנחת ר' אהרן הלוי מסטרשאלי נדפס בעבודת הלוי ח\"ב כט, א (בכותרת: כת\"ק בעת ששמע אדמו\"ר הזקן).\nנמצא בשינויים קלים בכת\"י 633 כ, ב.\nנוסח התו\"א לז, ד מיוסד על ב' נוסחות הנ\"ל."],["1395","2","<b>בת ציון</b>: זכרי' ב, יד."],["1396","3","<b>לגבי</b>: בכת\"י ב': שבחי."],["1397","4","<b>והאור המאיר מתוך החשך. . אור של תולדה</b>: ראה תו\"א יב, ב. וירא יד, ג. סידור קמה, ב. ביאוה\"ז לאדה\"א יז, א. סה\"מ תקס\"ט ע' ג."]]],[2100490302,"ע\"כ נק' בת ציון כו' וזהו דוקא כשיורדת בבי\"ע לברר בירורי' דרפ\"ח כו' וכמ\"ש ותקם<sup data-n=\"1398\">5</sup> בעוד לילה כו' בלילה דוקא ואז זמן עלייתה למעלה ג\"כ ע\"י בחי' רינה וכמאמר הנ\"ל רננה<sup data-n=\"1399\">6</sup> ברמשא דוקא כו' וכמ\"ש הנותן<sup data-n=\"1400\">7</sup> זמירות בלילה כו' כי אז דוקא מרננת וכמ\"ש מתרפק\"ת<sup data-n=\"1401\">8</sup> על דודה כו' ולהיכן היא עולה בשיר וזמרה היינו לבחי' גבורו' דאימא ששם מקור הגבורות וההסתלקות בבחי' רצוא שהוא דוקא ע\"י ההתבוננו' שבבחי' אימא כו' וזהו פי' רני ופי' שמחי הוא בחי' חסדי' דאימא והוא מ\"ש אם<sup data-n=\"1402\">9</sup> הבנים שמחה שהוא בחי' המשכו' חסדים לבוא מן ההעלם לגילוי ע\"י השמחה כו' וזהו שרש ענין רני ושמחי בת ציון ע\"פ הקבלה.\n<b>ולהבין</b> זה בתוס' ביאור הנה אנו רואים כדוגמא כזו למטה ממל' דאצי' בעולמות כו'. דהנה זה שעיקר עבודת המלאכי' הוא רק הרינה בלבד כנ\"ל, הענין הוא לפי שאין להם בחי' השמחה של מצוה עד שיהא להם בחי' שמחה היפך הרינה מאחר שאין להם תומ\"צ כלל א\"כ אין עבודתם אלא אחת והוא הרינה שהוא רק בחי' גבורות והסתלקות כמאמר כל<sup data-n=\"1403\">10</sup> בעלי השי\"ר יוצאין בשי\"ר וכמ\"ש למעלה. ועיקר הטעם לפי ששרש התהוות המלאכים הוא רק מבחי' המל' שבכל עולם ועולם כמו בחי' מל' דבריאה הוא שרש בחי' המלאכים דבריאה ובחי' מל' דיצי' שרש המלאכים דיצי' וגם המלאכים היותר עליונים הם רק בחי' חיצוני' דזו\"נ דבי\"ע מבחי' הבל נשיקין כו' אבל הנשמות מבחי' פנימי' דזו\"נ דגם בחי' ז\"א דכ\"ר כלול בנשמה וע\"כ נק' אדם<sup data-n=\"1404\">11</sup> דכליל דכר ונוק' כמ\"ש בזוהר ובע\"ח. והנה להיות כי המלאכים שרשן רק מבחי' הנוק' דכל עולם ע\"כ גם מדריגת השי\"ר שלהם הוא רק בבחי' החיצוני' בלבד כמו שהן בשרשם בבחי' קול הדיבור שבמל' שהוא רק בחי' החיצוני' כידוע. והמופת לזה שהשיר שלהם הוא בחי' חיצוני' הנה יובן ע\"ד דוגמא למטה כי בהיות האדם עומד בהיכל המלך ורואה כל גדולתו הוא בבחי' ביטול המציאות מכל וכל ואין לו פנאי לספר השבחי' וגם למה יספר אחר שנראה לעין כל אך כשיצא לחוץ יספר השבחי' של גדולת המלך ויתגדל רוממו' המלך בפיו להודות ולהלל בהתפעלות גדולה אבל כשהי' עומד בהיכל המלך לא הי' אז בהתפעלות הזאת כלל לרומם גדולת המלך אחר שרואה בעיניו ונמצא כי ההתפעלות הזאת היתה כלא חשיבא בהיותו עומד בהיכל המלך ורואה בעיניו אך כאשר יצא לחוץ ונתרחק משם אז מתפעל בהתפעלות מורגשת מאד ואע\"פ שאין כל חדש בזה כו' וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן במלאכים דלפי שהן עומדים מחוץ לבחי' היכלות הפנימיי' די\"ס דבי\"ע ע\"כ יתגדל בעיניהם רוממות וגדולת ה' להודות ולהלל",[["1398","5","<b>ותקם בעוד לילה</b>: משלי לא, טו."],["1399","6","<b>רננה ברמשא</b>: זח\"א רכט, א."],["1400","7","<b>הנותן זמירות בלילה</b>: איוב לה, י. — נתן זמירות בלילה."],["1401","8","<b>מתרפקת על דודה</b>: שה\"ש ח, ה."],["1402","9","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["1403","10","<b>כל בעלי השיר יוצאין בשיר וכמ\"ש למעלה</b>: שבת נא, ב. וראה הנסמן לעיל בד\"ה מזמור שיר."],["1404","11","<b>אדם דכליל דכר ונוק' כמ\"ש בזוהר ובע\"ח</b>: ראה זהר בראשית נה, ב. ויצא קסה, א. וישב קפב, סע\"א. וראה פע\"ח (שער הזמירות) ש\"ו פ\"ו."]]],[2100490303,"בשיר וזמרה בהתפעלות גדולה, אבל הנשמות שעומדי' יותר פנימה הן למעלה מבחי' התפעלות הזאת לספר בשבחים כו' אחר שנראה עליהם אור האלקי בבחי' גילוי ממש בהיותם נהנין מזיו השכינה כו' וד\"ל. וזהו ענין ההליכה ויציאה שמוזכר במלאכים כענין המאמר בעלי השיר יוצאין כו' כי הולכים ויוצאים מהיכל להיכל בדרך יציא' לחוץ כמו שיוצא אדם מהיכל המלך חוץ להיכל לספר את השבחי' כו' כך המלאכים יוצאים מהיכלות דבריאה חוץ להיכל לספר בשיר כו' ואין התפעלו' הזאת ענין ביטול פנימי רק חיצוני משא\"כ בנשמות שעומדי' פנימ\"ה שביטול שלהם פנימי' וזהו שאמר הנביא ואשמע<sup data-n=\"1405\">12</sup> אחרי קול רע\"ש כו' כמ\"ש במ\"א וד\"ל. וזהו מ\"ש נכספה<sup data-n=\"1406\">13</sup> וגם כלתה נפשי לחצרות כו' פי' לחצרות דוקא להיותו בבחי' חיצוני' הנה שם דוקא יתכן כלות הנפש בתשוקה מורגשת כי כל תשוקה מורגשת היא מרחוק דוקא כו' וכ\"ז מפני ששרשם ג\"כ בבחי' חיצוני' והוא בחי' קול שבמל' הנק' דיבור כנ\"ל וד\"ל.\n<b>והנה</b> הקול של השיר שבא בהתפעלות הוא למעלה מבחי' הדיבור, כי הנה אנו רואים דמה שמתפעל האדם בלבו בהתפעלות יתירה לא יוכל להביאה כלל בדיבור רק בשיר וניגון בלבד הוא שיכול להוציא כל כח כונת ההתפעלות שבלב משום דהמדו' שבלב מתלבשים רק בקול ושיר ואופן הניגון והשיר הוא לפי אופן ההתפעלות של המדה אם ההתפעלות היא מחדוה ושמחה כך ינגן בשיר המורה תנועת שמחה וחדוה ואם ההתפעלות מבחי' מרירו' ינגן בתנועה שהוא קול מרירו' ואם משניהם יחדיו ינגן מב' תנועות מורכבות יחד כו' וכללות כל ההתפעלות של המדות היא מדת האהבה אלא שהיא מתחלקת בכמה מיני אופני' שונים שיש לפעמי' התפעלות אהבה שמתלבשת בדרך חדוה ותענוג ויש לפעמי' שתתלבש בדרך מרירו' ועוצב מפני הריחוק וכיוצא ויכול להיות שיהי' זה נוגע בפנימי' הנפש ביותר מבחי' אהבה בתענוגי' שאינה נוגעת בפנימי' כ\"כ כו' והכל מין א' והוא רק מבחי' אור האהבה אלא שמתלבשת בניגון בכמה מדרגו' דהיינו בכל חלקי הו' מדות חג\"ת כו' והוא הקול שיש בו ו' מדות בהעלם ובגילוי והן שית כנפי ריאה ושית עזקאן דקנה כו' וד\"ל. וזהו ענין המאמר בזוהר ע\"פ יומם יצוה כו' דמה שאמר יומ\"ם במ\"ם כפולה להיות כי זהו בחי' אור האהבה והוא הנק' עננא<sup data-n=\"1407\">14</sup> דאהרן דאזיל עם כולהו יומין כו' לפי שהיא בחי' כוללת הכל כנ\"ל וע\"כ הגם דעננא דאהרן הוא רק בחי' חסד מ\"מ הם ז' ימי סוכות ז' מקיפי' דחסד שבחסד וגבו' שבחסד כו' והכל מעננא דאהרן דאזיל עם כולהו יומין כו' וד\"ל.",[["1405","12","<b>ואשמע אחרי קול רעש כו'</b>: יחזקאל ג, יב."],["1406","13","<b>נכספה וגם כלתה נפשי</b>: ע\"פ תהלים פד, ג."],["1407","14","<b>עננא דאהרן דאזיל עם כולהו יומין</b>: תהלים מב, ט. ראה זהר אמור קג, א-ב. בלק קצא, ב. וראה זהר בראשית מו, א: יומא קדמאה אזיל עם כולהו. עץ חיים שער (כה) דרושי הצלם דרוש ב כלל ז ושער מאמרי רשב\"י יתרו סח, ב־ עטרת ראש דרוש לש\"ת מז, ב־ יומם. . דאזיל (וראה ע\"ח שם סוף כלל ח). פרי עץ חיים שער (כח) הסוכות פ\"א־ סידור כאן רלז, ג־ שחרית נב, ד־ לקוטי תורה האזינו עו, ב: יומא דאזיל. שערי מאמרי רשב\"י תרומה קלט, א־ אמור קג, ב: יומא דכליל. לקוטי שיחות י\"ט כסלו כרך ה ע' 174 בהערה. וראה באור החמה לזהר אמור קג, ב־ רמ\"ז לזהר ויחי רמז, א־ מקדש מלך וארא לא, א: יומא דכליל. ניצוצי אורות לזהר וארא שם: יומא דאזיל."]]],[2100490304,"<b>וזהו</b> שרש ענין וצדקתך<sup data-n=\"1408\">15</sup> ירננ\"ו פי' לפי ששרש המלאכי' מבחי' חיצוני' המל' כנ\"ל ע\"כ הם עומדים מרחוק וכל תשוקה מרחוק דהיינו כאשר חסר לו אותו הדבר שמתאוה לו כו' וכנ\"ל לכך וצדקתך דוקא ירננו צדק דאיהו דין וגבורות וכמ\"ש למעלה רק שהביטול משי\"ר שלהם מגיע לבחי' א\"ס שבמדה זו כי אליו ולא למדותיו כו' וזהו נפשי<sup data-n=\"1409\">16</sup> איויתיך בלילה דוקא פי' במדת לילה שהמלאכי' עומדים חוץ להיכל הפנימי' אזי דוקא זמן התשוק' שלהם בניגון ושיר להודות ולהלל כו' בכל פרטי חלקי' הששה מדות אוי\"ר כו' וזהו הטעם למאמר הנ\"ל דרננה ברמשא דוקא וכמ\"ש למעלה וד\"ל.\n<b>והנה</b> הדוגמא מכל הנ\"ל במלאכים יובן ג\"כ למשכיל למעלה בבחי' מל' דאצי' עצמה לגבי אורות העליונים דאצי' שעיקר זמן בחי' השיר שלה הוא ג\"כ בליל\"ה דוקא וכמ\"ש אלקי'<sup data-n=\"1410\">17</sup> אל דמי לך כו' ואמרו<sup data-n=\"1411\">18</sup> בזוהר דקארי תדיר לנהורא עילא' ולא שכיך כו' וכמ\"ש למען<sup data-n=\"1412\">19</sup> יזמרך כבוד ולא ידום, כבו\"ד הוא ל\"ב נ\"ח שבמל' דאצי' בכלל ובלילה עולין בחי' המוחין בבחי' הסתלקות והתכללות ע\"י בחי' רינה וזמרה דוקא כענין ודוגמא שהמלאכים יוצאי' בשיר כנ\"ל וזהו הנותן זמירות בלילה דוקא לפי שאז הוא דוקא הזמן שמתרפקת על דודה כו' לפי שעומדת בריחוק מקום כו' וכל תשוקה והשתוקקות מרחוק דוקא וכמשל המספר שבחי המלך כשעומד חוץ להיכל והוא הנק' בחי' עולם הדיבור העליון שמרנן ומזמר וכמ\"ש למען יזמרך כבוד כו', והוא מ\"ש אלקי' אל דמי לך כו' פי' אלקי' שבבחי מל' בכלל משום דעיקר הרננה ברמשא כנ\"ל במלאכים וזהו שרש ענין רני ושמחי בת ציון כנ\"ל שהמל' הנק' בת ציון באה למעלה בבחי' רינה דוקא בלילה ועולה היא בבחי' הרצוא הזה עד בחי' גבורות דאימא דשם הוא מקור חוצבה בבחי' הגבורות וכמ\"ש במ\"א בענין המאמר דאימא<sup data-n=\"1413\">20</sup> אוזיפת מאנהא לברתא דהיינו ה\"ג מנצפ\"ך שבה דשם אלקי' שבמל' נחצב משם וזהו אלקי' אל דמי לך פי' לך לבחי' הגבורות דאימא כו' וד\"ל. וכ\"ז בדוגמות המלאכים שאין להם רק בחי' הרינה בלבד כנ\"ל, אבל הנשמות יש להם ג\"כ בחי' השמחה וזהו רני ושמחי כו'.\n<b>וביאור</b> הדברי' הנה מבואר למעלה דשרש המלאכים רק מבחי' מל' כו' אבל שרש הנשמות מבחי' ז\"א ג\"כ ולכך נק' אדם וכמ\"ש נעשה<sup data-n=\"1414\">21</sup> אדם בצלמינו כו' והוא כלול מכל הפרצופים כו' כידוע ע\"כ יש בנשמות כל מה שיש למעלה והוא שיש בהם ג\"כ בחי' השמחה שהוא היפך הרינה דהיינו בחי' המשכת חסדי' דאימא כו' שיהא דוקא בחי' הגילוי מן ההעלם היפך בחי' העלי' וההסתלקו' דבחי' הרינה",[["1408","15","<b>וצדקתך ירננו</b>: תהלים קמה, ז."],["1409","16","<b>נפשי איויתיך בלילה</b>: ישעי' כו, ט."],["1410","17","<b>אלקי' אל דמי לך</b>: תהלים פג, ב."],["1411","18","<b>ואמרו בזהר דקארי תדיר לנהורא עילאה</b>: ראה זהר (היכלות) פקודי רנו, ב. תרומה קמ, רע\"א. וישלח קעח, ב. לך עז, ב. פו, ב."],["1412","19","<b>למען יזמרך כבוד ולא ידום</b>: תהלים ל, יג."],["1413","20","<b>דאימא אוזיפת</b>: ראה זהר בהקדמה ב, א. וראה תו\"ח נח כח, ד. מאמרי אדה\"א דברים ח'א ע' רלו. וש\"נ."],["1414","21","<b>נעשה אדם</b>: בראשית א, כו."]]],[2100490305,"כו' וסיבת השמחה למעלה בא ע\"י מעשה המצות דוקא וכמ\"ש פיקודי<sup data-n=\"1415\">22</sup> ה' משמחי לב פי' לב העליון דבחי' ז\"א כו' כמ\"ש אלה<sup data-n=\"1416\">23</sup> המצות אשר יעשה אותם האדם וחי בהם קאי לבחי' האדם דלעילא כמ\"ש למעלה ופקודי הוי' הן מצות הוי' כמו מה שהקב\"ה<sup data-n=\"1417\">24</sup> מניח תפילין וכיוצא והן המשמחי' הלב דוקא.\n<b>וביאור</b> הדברים הנה מבואר בע\"ח<sup data-n=\"1418\">25</sup> דהגדלת אברי' בז\"א הוא מפני ה\"ח המגדילים כי כל אבר כלול מרת\"ס פנימי אמצעי וחיצון ג' כלים וטפ\"ט בגי' פ\"א וג\"פ פ\"א בגימ' רמ\"ג וה\"ח המגדילים הוא רמ\"ח כו' וה\"ח המגדילים בכל אבר הן ה\"ח דרמ\"ח מ\"ע בכלל המאירים בכל אבר בפרט כו' והיינו ע\"י ענין השמחה של מצוה שמחמת שמחה זו מאיר מאור אימא בחי' החסדים ונמשכים ה\"ח בז\"א להגדיל כו' אמנם מ\"מ לא מסיבת גילוי החסדי' דאימא בלבד הוא שיגדל אלא רק מצד שרש שרשן של המצות שהוא במקום הגבוה מאד נעלה גם מאור אימא והוא בבחי' מו\"ס וגלגלתא דא\"א דתרי\"ג ארחין דמתפלגין בז\"א מאורחא חד כו' כמ\"ש באד\"ר ונק'<sup data-n=\"1419\">26</sup> ארחות הוי' כו' ושרשם בלבנוני' דגלגלתא ונק' י\"ג חוורתא כו' וע\"כ פקודי הוי' משמחי לב האדם העליון כי שרשם מבחי' הכת\"ר ונק'<sup data-n=\"1420\">27</sup> תר\"ך עמודי אור כידוע ועד\"מ העמוד<sup data-n=\"1421\">28</sup> שראשו מחובר לגג וסופו נעוץ בארץ ע\"כ מחבר הוא הגג עם הקרקע, כך המצות שרשן בבחי' הכתר וסופן מאירים ומשמחי' בלב דז\"א כשמניח תפילין וכיוצא וד\"ל.\n<b>והנה</b> כאשר אורות עליונים דמ\"ס וגלגלתא כו' מאירים ברמ\"ח אברים דז\"א זהו<sup data-n=\"1422\">*28</sup> מ\"ש עבדו<sup data-n=\"1423\">29</sup> את הוי' בשמחה שהוי' שהוא בבחי' ז\"א כידוע נמשך בו מן בחי' ההעלם דכתר בבחי' גילוי אור ע\"י שמחה של מצוה כמ\"ש פיקודי הוי' משמחי לב כנ\"ל וכשהמל' מקבלת אותן ההארות עליוני' מרמ\"ח אברי' דז\"א אז נק' ציון לפי שמצויין בה אותן אורות עליונים דכתר שברמ\"ח אברים דז\"א כו' וכללות נש\"י ששרשם בבחי' מל' דאצי' כשעושין המצות בפו\"מ נק'<sup data-n=\"1424\">30</sup> ב\"ת ציו\"ן להיות כי גם בהמעשה מצוה הגשמי' שלהם נמשך בהם גילוי אא\"ס שבכתר ואך ורק שהוא בדרך אות וציון סימנא בעלמא שהרי המצוה הנעשי' למטה הרי היא מלובשת בענין גשמי כמו פ' קדש דתפילין שהוא קלף עור בעלמא אבל מ\"מ נחקק בה בבחי' סימן לפ' קדש<sup data-n=\"1425\">31</sup> לי כל בכור כמו שהוא למעלה בבחי' האצי' דבחי' אור החכמ' דאא\"ס שורה",[["1415","22","<b>פיקודי ה' משמחי לב</b>: תהלים יט, ט."],["1416","23","<b>אלה המצות. . וחי בהם</b>: ראה אחרי יח, ה."],["1417","24","<b>הקב\"ה מניח תפילין</b>: ראה ברכות ו, א."],["1418","25","<b>בע\"ח דהגדלת אברי' בז\"א</b>: ראה ג\"כ תו\"א סח, ג. סט, א. קו\"א לתניא בד\"ה להבין מ\"ש בפע\"ח (קנה, ב)."],["1419","26","<b>ונק' ארחות הוי'</b>: ראה תהלים כה, י: כל ארחות ה' חסד ואמת. וראה ביאוה\"ז וישלח יט, ב."],["1420","27","<b>ונק' תר\"ך עמודי אור</b>: ראה תורת העולה להרמ\"א ח\"ג פל\"ח (לב, א). של\"ה יתרו שיו, א. מאו\"א מערכת תר\"ך סנ\"ו."],["1421","28","<b>העמוד שראשו. . הגג עם הקרקע</b>: ראה אגה\"ק סכ\"ט."],["1422","*28","<b>זהו מ\"ש. . אברי' דז\"א</b>: ליתא בכת\"י 1156."],["1423","29","<b>עבדו את הוי' בשמחה</b>: תהלים ק, ב."],["1424","30","<b>נק' כנס\"י</b>: נסמן לעיל ע' ריז."],["1425","31","<b>קדש לי כל בכור</b>: בא יג, ב."]]],[2100490306,"בה בהיות הקב\"ה מניח תפילין כו' וכמ\"ש וראו<sup data-n=\"1426\">32</sup> כי שם הוי' כו' וכיוצא בזה לכל המצות שהם בחי' סימנא לאורות עליונים אך בהעשות המצוה בפו\"מ אז הוא בחי' הגמר של הגילוי אורות העליונים כו' וע\"כ גם בכלל כשבחי' המל' שנק' בחי' עשי' לבחי' אורות העליונים מקבלת ההארה מרמ\"ח אברים דז\"א כו' אזי הוא בחי' הגמר כמו שבאה המצוה לפו\"מ וע\"כ נק' ציון וחותם כו' וד\"ל. וזהו שארז\"ל מצות<sup data-n=\"1427\">33</sup> צריכות כונה, פי' המצות כמו שהן נעשי' בפו\"מ נק' מצות סתם והן צריכות כונה והכונה הוא להמשכות אורות העליונים בחי' ארחין דגלגלתא כו' ובמעשה של המצוה נגמר הגילוי שלהם וכך למעלה בבחי' מל' דאצי' שנק' ציון הוא בחי' מעשה המצוה כמו שהיא כו' ולכך נק' המל'<sup data-n=\"1428\">34</sup> בשם מצות המלך וכמ\"ש כי נ\"ר<sup data-n=\"1429\">35</sup> מצו\"ה כו' וכמ\"ש בתיקונים. אבל אינה אלא בחי' כלי לקבל האורות עליונים שברמ\"ח אברים דמלכא כו' וד\"ל.\n<b>ובכ\"ז</b> יובן מה שהקדי' לומר עבדו ה' בשמחה ואח\"כ בואו לפניו ברננה ואע\"פ שמלמטה למעלה נהפך הוא הסדר דהרינה קדמה לשמחה משום דבחי' הרינה הוא העלא' מ\"נ דשרשה בגבו' דאימא כנ\"ל והסדר שהוא מלמטה למעלה צריך להיות הרננה קודם אבל בפסוק זה מיירי במצות שהן בחי' המשכות אורות העליונים מלמעלה למטה ומלמעלה למטה הסדר בהיפוך שבחי' השמחה קדמה לרננה כו', ויובן זה עד\"מ מי שרוצה לבא לפני המלך א\"א לו כ\"א שיכין א\"ע בהכנה להיות עולה במעלו' ומדריגו' עד שיוכל לבא ולעמוד בהיכל המלך פנימ' והוא ע\"י שיזמר וירנן דברי שבח והודי' וכיוצא אבל כשהמלך רוצה לבוא אליו לבית העבד מה צריך העבד להכין א\"ע ברינה ושבחים וכיוצא אחר שהמלך בא לביתו כו' אלא יגיל לבו וישמח בתוכו ופנימיותו ממה שהמלך בביתו וא\"כ יובן למעלה ג\"כ ע\"ד הזה שבעלי' מלמטה למעלה בא יבא לפני ה' ברינה דוקא ואח\"כ ישמח בבואו לפני ה' כו', אבל במצות מעשיו' דמשמחי' לב מלמעלה למטה כנ\"ל בתחלה השמחה באה כו' וד\"ל.\n<b>וזהו</b> רני ושמחי בת ציון כו', פי' הנביא בא לנחם לכנ\"י<sup data-n=\"1430\">36</sup> בזמן הגלו' שנק' בת ציון והוא בחי' המל' שנק' ציון כנ\"ל במצות מעשיו' כשיורדת בבי\"ע לברר בירורים נק' בת ציון כנ\"ל והוא משארז\"ל גלו<sup data-n=\"1431\">37</sup> לאדום שכינה עמהם שהשכינה מתלבשת בע\"ש כמו בשר של אדום וכיוצא וידוע מ\"ש עת<sup data-n=\"1432\">38</sup> אשר שלט האדם באדם לרע לו כו' דבזה מתברר הטוב מהשר ההוא ונהפך גם הוא לטוב וממילא יאבד בכלות הבירור כו' וזהו ומלכותו<sup data-n=\"1433\">39</sup> בכל משלה שבחי' מל' משפלת עצמה מאד",[["1426","32","<b>וראו כי שם הוי'</b>: תבוא כח, י."],["1427","33","<b>מצות צריכות כוונה</b>: ראה עירובין צה, סע\"ב."],["1428","34","<b>נק' המל' בשם מצות המלך</b>: ראה תו\"א מקץ לט, ד. לקו\"ת ויקרא ב, א. במדבר יז, ב. ובכ\"מ."],["1429","35","<b>כי נר מצוה</b>: משלי י, כג."],["1430","36","<b>לכנס\"י. . שנק' בת ציון</b>: ראה ג\"כ תו\"א מקץ לז, ג. לקו\"ש כרך כד ע' 353 בהערה."],["1431","37","<b>גלו לאדום שכינה עמהם</b>: ספרי בהעלותך יוד, לה. ס\"פ מסעי. מכילתא בא יב, מא. ועוד. וראה מגילה כט, א."],["1432","38","<b>עת אשר שלט האדם באדם</b>: קהלת ח, ט."],["1433","39","<b>ומלכותו בכל משלה</b>: תהלים קג, יט."]]],[2100490307,"מאד עד הע\"ש למטה כדי לבררם ולהכניעם כו' והנה בזמן בהמ\"ק לא היתה השכינה בגלו' ההתלבשו' בע\"ש אלא היתה דבוקה ומיוחדת בבחי' יחוד העליון הוא בחי' יחוד דמ\"ן ומ\"ד דז\"א ונוק' שנעשה ע\"י הקרבנות כידוע ולהיות כי ביחוד זה נתעלה כל העולם בתכלית העילוי מפני עוצם רוממות האור האלקי כי נעלה הוא מאד ע\"כ ממילא מתבטלים יניקות החיצונים ומתבררי' בתכלית וכמ\"ש כהמס* דונג כו', וזהו שאנו מוצאים בימי שלמה משום דקיימא<sup data-n=\"1434\">40</sup> סיהרא באשלמותא כמ\"ש בזוהר מפני יחוד השלם שהי' במל' כו' לכך היו כל האומות נכנעים תחת שלמה והיו מביאים לו מנחה ומסים ממילא מעוצם ביטול שלהם מפני בחי' גילוי שכינה בתכלית השלימות מאור יחוד העליון וזהו מ\"ש ותר\"ב<sup data-n=\"1435\">41</sup> חכמ\"ת שלמה גם מכל בני קד\"ם כו' וע\"ד<sup data-n=\"1436\">42</sup> הפשוט היו באי' כולם לשמוע חכמת שלמה וכך למעלה הי' ביטול כל הע\"ש נגד חכ' שבמל' דאצי' ממילא כו' וד\"ל. משא\"כ בזמן הגלות שאין היחוד למעלה כלל שמחמת זה יהי' ביטול החיצוני' ממילא ע\"כ בא הנביא לנחם לכנ\"י דמ\"מ רני ושמחי בת ציון כו' אע\"פ שנק' בת מטעם דאיש מזריע תחלה יולדת בת כנ\"ל, והוא אתדל\"ע שמצד עצמו כשאין אתדל\"ת למטה כמ\"ש למעלה משום דהיא הנותנת דאחר שאתדל\"ע בא מצד עצמו כמ\"ש למעני<sup data-n=\"1437\">43</sup> למעני אעשה הרי בזה יש יתרון מעלה הרבה גם מגופו של יחוד העליון שהי' בזמן בהמ\"ק כו' לפי שצריך להשפיל א\"ע למטה לעשות מלחמה לברר בירורים בבי\"ע עד הע\"ש כדי להכניעם כו' וזהו מצד עצמות התעוררות שלו כמ\"ש למעני למעני כו', ועצמות כחו ודאי גדול הרבה יותר מכחו של המשכת מ\"ד שע\"י העלא' מ\"ן כי העלא' מ\"ן דנוק' הי' תלוי באופן הכוונות והיחודים שבקרבנות משא\"כ כח האלקי מצד עצמו שאין בו שינוי ולא גרעון אור לעולם וכמ\"ש שד\"י<sup data-n=\"1438\">44</sup> לא מצאנוהו שגיא וכו'.\n<b>ויובן</b> דוגמא כזו ממה שידוע בענין הטלית וק\"ש קטנה שלפני פסד\"ז שהם גורמים הכוונה שבלב בבחי' מקיף והעלם כו' וכך כל עיקר ענין הבירורי' דמל' מברר מצד עצמו' למעני למעני כו' בע' השרים הוא מאד גבוה במדרגה אך שהוא בהעלם ובחי' מקיף ולע\"ל יתגלה וכמ\"ש ונגלה<sup data-n=\"1439\">45</sup> כבוד ה' וראו כל בשר כו' ומ\"מ בבחי' חיצוני' גם עכשיו מאיר ולע\"ל יבא האור גם בבחי' הפנימי' כו' וה\"ז כמו התפעלות הרינה בפסד\"ז שבאה בבחי' פנימי' ג\"כ וכמ\"ש בואו לפניו ברננה לפניו בבחי' פנימי' האור כו' וד\"ל.\n<b>כי</b> הנני בא ושכנתי בתוכך נאום הוי', פי' כי הנני כו' כמו נתינת טעם למ\"ש רני ושמחי בת ציון כו' דעיקר הטעם שגם בהיותה בבחי' בת בגלות כנ\"ל מ\"מ רני ושמחי היינו מפני סיבת מעשה המצות דוקא דלכך נק' בת ציון המצויינת באורות",[["1434","40","<b>דקיימא סיהרא באשלמותא</b>: זהר בראשית קנ, א. רכג, א. שמות רלה, ב. דברים רצז, יא."],["1435","41","<b>ותרב חכמת שלמה</b>: מלכים-א ה, י."],["1436","42","<b>וע\"ד הפשוט. . לשמוע חכמת שלמה</b>: ראה תו\"א ו, א."],["1437","43","<b>למעני למעני</b>: ישעי' מח, יא."],["1438","44","<b>שדי לא מצאנוהו שגיא</b>: איוב לז, כג."],["1439","45","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."]]]]});
